          </div>
        </section>
      )}
    </div>
  )
}

export default function DashboardPage() {
  const router = useRouter()
  const { mutate: mutateCache } = useSWRConfig()
  const isMobile = useIsMobile() ?? false
  const { division } = useDivision()
  useEffect(() => { void loadECharts() }, [])
  const { data: termData, error: termError, mutate: mutateTerms } = useSWR<{ selectedTermId?: string | null; terms: Array<{ id: string; name: string; status: 'DRAFT' | 'ACTIVE' | 'ARCHIVED' }> }>('/api/admin/academic-terms', async (url: string) => {
    const response = await fetch(url, { cache: 'no-store' })
    if (!response.ok) throw new Error('运营批次加载失败')
    return response.json()
  })
  const terms = useMemo(() => termData?.terms || [], [termData?.terms])
  const defaultTermId = termData?.selectedTermId
    || terms.find((term) => term.status === 'ACTIVE')?.id
    || terms[0]?.id
  const [selectedTermId, setSelectedTermId] = useState('')
  const [switchingTermId, setSwitchingTermId] = useState<string | null>(null)
  useEffect(() => {
    if (!defaultTermId) return
    setSelectedTermId((current) => current === defaultTermId ? current : defaultTermId)
  }, [defaultTermId])
  const changeTermScope = async (termId: string) => {
    if (!termId || termId === selectedTermId || switchingTermId) return
    setSwitchingTermId(termId)
    try {
      const response = await fetch('/api/admin/academic-terms/scope', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ termId }),
      })
      const payload = await response.json().catch(() => ({}))
      if (!response.ok) throw new Error(payload.error || '切换运营批次失败')
      const persistedTermId = payload.term?.id || termId
      await mutateCache(isAdminTermScopedSWRKey, undefined, { revalidate: false })
      const nextDashboardUrl = `/api/dashboard?division=${division}&termId=${encodeURIComponent(persistedTermId)}`
      const nextDashboardResponse = await fetch(nextDashboardUrl, { cache: 'no-store' })
      const nextDashboardPayload = await nextDashboardResponse.json().catch(() => ({}))
      if (!nextDashboardResponse.ok) {
        throw new Error(nextDashboardPayload.error || '所选批次数据加载失败')
      }
      await mutateCache(nextDashboardUrl, nextDashboardPayload, { revalidate: false })
      await mutateTerms((current) => current ? {
        ...current,
        selectedTermId: persistedTermId,
      } : current, { revalidate: false })
      setSelectedTermId(persistedTermId)
      message.success(`已切换到“${payload.term?.name || '所选批次'}”`)
    } catch (error) {
      message.error(error instanceof Error ? error.message : '切换运营批次失败')
    } finally {
      setSwitchingTermId(null)
    }
  }
  const effectiveTermId = selectedTermId || defaultTermId || ''
  const selectedTerm = terms.find((term) => term.id === effectiveTermId)
  const termScopeReady = termData !== undefined || termError !== undefined
  const dashboardUrl = termScopeReady
    ? `/api/dashboard?division=${division}${effectiveTermId ? `&termId=${encodeURIComponent(effectiveTermId)}` : ''}`
    : null
  const { data, error, isLoading } = useSWR(dashboardUrl, fetcher, {
    // 教师约课后，管理首页应在较短时间内自动出现动态。
    refreshInterval: 30_000,
    revalidateOnFocus: true,
    dedupingInterval: 10_000,
  })

  if (!termScopeReady || isLoading) {
    return <DashboardSkeleton />
  }

  if (error || !data) {
    return (
      <Alert
        type="error"
        showIcon
        message="数据总览加载失败"
        description="请检查数据库连接、登录状态或稍后重试。"
      />
    )
  }

  if (isMobile) {
    return (
      <div style={{ background: '#FAF6EE', minHeight: '100dvh' }}>
        <div style={{ padding: '0 16px', background: '#FAF6EE' }}>
          {selectedTerm?.status === 'DRAFT' && (
            <Alert
              type="warning"
              showIcon
              message="当前批次尚未启用，仅供查看"
              action={<Button size="small" onClick={() => router.push('/academic-terms')}>去启用</Button>}
              style={{ marginTop: 10, borderRadius: 10 }}
            />
          )}
          {selectedTerm?.status === 'ARCHIVED' && (
            <Alert type="info" showIcon message="当前正在查看历史归档数据" style={{ marginTop: 10, borderRadius: 10 }} />
          )}
        </div>
        <MobileDashboard data={data} />
        <div style={{ padding: '14px 16px 0', background: '#FAF6EE', width: '100%', maxWidth: '100%' }}>
          <QuickStartGuide storageKey={`mz_admin_quick_start_v1_${division}`} title="三步开始管理工作" steps={ADMIN_QUICK_STEPS} />
        </div>
      </div>
    )
  }

  return (
    <div style={{ paddingBottom: 24, background: '#FAF6EE', minHeight: '100vh' }}>
      <DashboardHero
        metrics={data.metrics}
      />
      <AdminServiceOverviewCard />
      {selectedTerm?.status === 'ARCHIVED' && <Alert type="info" showIcon message="正在查看历史归档数据" style={{ marginBottom: 16 }} />}
      {selectedTerm?.status === 'DRAFT' && (
        <Alert
          type="warning"
          showIcon
          message="这是尚未启用的批次，目前仅用于查看"
          description="如需在本批次添加学员、建班、排课和录入业务，请到“学期与批次”点击“启用并进入”。"
          action={<Button size="small" onClick={() => router.push('/academic-terms')}>去启用</Button>}
          style={{ marginBottom: 16 }}
        />
      )}
      <AdminTodayTodoBar data={data} />
      <MetricsCards data={data.metrics} />
      <Card
        style={{ marginTop: 16, borderRadius: 14, border: '1px solid rgba(58,50,39,.07)', boxShadow: '0 2px 8px rgba(58,50,39,.04)' }}
        styles={{ body: { padding: '14px 18px' } }}
      >
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 12 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
            <span style={{ width: 3, height: 14, borderRadius: 2, background: 'linear-gradient(180deg,#FFB84D,#E8784A)' }} />
            <span style={{ fontSize: 14, fontWeight: 700, color: '#2B2110' }}>教师考勤 · 反馈（今日）</span>
            <span style={{ fontSize: 12, color: '#A89C8A' }}>未提交项优先置顶</span>
          </div>
          {data.teacherCompliance.some((item) => item.pendingAttendance > 0 || item.pendingFeedback > 0) && (
            <Tag color="#C05A2E" style={{ borderRadius: 20, fontWeight: 600 }}>
              待办 {data.teacherCompliance.reduce((sum, item) => sum + item.pendingAttendance + item.pendingFeedback, 0)} 项
            </Tag>
          )}
        </div>
        {data.teacherCompliance.length === 0 ? (
          <GuidedEmpty
            title="今日暂无教师履约监控数据"
            description="当天教师开课后会实时汇总出勤与反馈记录。"
            compact
          />
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column' }}>
            <div style={{ display: 'grid', gridTemplateColumns: '1.4fr 0.6fr 1fr 1fr', padding: '8px 12px', background: '#F3EBDD', borderRadius: 8, fontSize: 12, color: '#9A8E7A', fontWeight: 600 }}>
              <span>教师</span>
              <span>今日课次</span>
              <span>考勤</span>
              <span>课堂反馈</span>
            </div>
            {data.teacherCompliance.map((item) => {
              const hasPending = item.pendingAttendance > 0 || item.pendingFeedback > 0
              return (
                <div
                  key={item.teacherId}
                  onClick={() => router.push(`/teacher-compliance?teacherId=${encodeURIComponent(item.teacherId)}`)}
                  role="button"
                  tabIndex={0}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') router.push(`/teacher-compliance?teacherId=${encodeURIComponent(item.teacherId)}`)
                  }}
                  style={{
                    display: 'grid',
                    gridTemplateColumns: '1.4fr 0.6fr 1fr 1fr',
                    alignItems: 'center',
                    padding: '9px 12px',
                    borderBottom: '1px solid #F0E9DD',
                    background: hasPending ? 'rgba(245,166,35,.06)' : 'transparent',
                    borderRadius: hasPending ? 8 : 0,
                    cursor: 'pointer',
                  }}
                >
                  <span style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    <CachedAvatarImage
                      src={getTeacherAvatarUrl(item.avatar, item.gender, item.teacherId)}
                      fallbackSrc={getTeacherAvatarUrl(null, item.gender, item.teacherId) || DEFAULT_TEACHER_AVATAR}
                      alt={item.name}
                      style={{ width: 26, height: 26, borderRadius: 999, objectFit: 'cover', flexShrink: 0 }}
                    />
                    <span style={{ fontSize: 13, fontWeight: 600, color: '#1F241F' }}>{item.name}</span>
                  </span>
                  <span style={{ fontSize: 12, color: '#5C4F3F', fontVariantNumeric: 'tabular-nums' }}>{item.todayLessons} 节</span>
                  <span>
                    <span style={{
                      fontSize: 12, fontWeight: 600, padding: '2px 10px', borderRadius: 999, whiteSpace: 'nowrap',
                      color: item.pendingAttendance > 0 ? '#C05A2E' : '#1E7A3C',
                      background: item.pendingAttendance > 0 ? '#FFEDE4' : '#DFF5E8',
                    }}>
                      {item.pendingAttendance > 0 ? `待录 ${item.pendingAttendance} 节` : `已提交 ${item.attendanceDone}/${item.todayLessons}`}
                    </span>
                  </span>
                  <span>
                    <span style={{
                      fontSize: 12, fontWeight: 600, padding: '2px 10px', borderRadius: 999, whiteSpace: 'nowrap',
                      color: item.pendingFeedback > 0 ? '#C0392B' : '#1E7A3C',
                      background: item.pendingFeedback > 0 ? '#FDEAEA' : '#DFF5E8',
                    }}>
                      {item.pendingFeedback > 0 ? `未发 ${item.pendingFeedback} 节` : `已发布 ${item.feedbackDone}/${item.todayLessons}`}
                    </span>
                  </span>
                </div>
              )
            })}
          </div>
        )}
      </Card>
      <div className="admin-dashboard-workspace">
        <div className="admin-dashboard-workspace__main">
          <AdminExceptionCenter metrics={data.metrics} />
          <StudentGrowthChart data={data.growthData} />
        </div>
        <aside className="admin-dashboard-workspace__aside" aria-label="今日动态与课表">
          <IntensiveAppointmentCard items={data.intensiveAppointments} />
          <TodayScheduleCard data={data.schedules} />
        </aside>
      </div>

      <Row gutter={[16, 16]} style={{ marginTop: 16 }}>
        <Col xs={24} lg={12}>
          <TeacherWorkloadCard data={data.workloads} />
        </Col>
        <Col xs={24} lg={12}>
          <ActivityLogCard data={data.logs} />
        </Col>
      </Row>
      <div style={{ marginTop: 16 }}>
        <QuickStartGuide storageKey={`mz_admin_quick_start_v1_${division}`} title="三步开始管理工作" steps={ADMIN_QUICK_STEPS} />
      </div>
    </div>
  )
}

'use client'

import { useEffect, useRef, useState } from 'react'
import { useRouter } from 'next/navigation'
import useSWR from 'swr'
import { Alert, Button, Card, Empty, Form, Input, InputNumber, Modal, Select, Space, Typography, message } from 'antd'
import type { InputRef } from 'antd'
import { DownloadOutlined, FileTextOutlined, BarChartOutlined } from '@ant-design/icons'
import { PageLayout } from '@/components/Layout/PageLayout'
import { useIsMobile } from '@/hooks/useIsMobile'
import { calculateGradeStats, countCompletedGradeEntries, isInvalidGradeScore } from '@/lib/gradebook-stats'

type Student = { id: string; name: string }
type Group = {
  id: string
  name: string
  course: { name: string; subject: string | null; grade: string | null }
  enrollments: Array<{ studentId: string; student: Student }>
}
type Assessment = {
  id: string
  name: string
  type: string
  assessDate: string
  fullScore: number
  absentStudentIds: string[]
  gradeRecords: Array<{ id: string; score: number; comment: string | null; notifySent: boolean; student: Student }>
}

const EXAM_TYPES = [
  { value: 'STAGE', label: '阶段测评' },
  { value: 'WEEKLY', label: '周测' },
  { value: 'MONTHLY', label: '月考' },
  { value: 'MOCK', label: '模拟考' },
]
const TYPE_LABELS: Record<string, string> = {
  DIAGNOSTIC: '诊断测评', STAGE: '阶段测评', WEEKLY: '周测', MONTHLY: '月考', FINAL: '期末测评', MOCK: '模拟考',
}

const fetcher = async (url: string) => {
  const response = await fetch(url)
  const data = await response.json().catch(() => ({}))
  if (!response.ok) throw new Error(data.error || '加载失败')
  return data
}

function localDateInput() {
  const date = new Date()
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`
}

export default function GradebookPage() {
  const isMobile = useIsMobile() ?? false
  const router = useRouter()
  const [groupId, setGroupId] = useState('')
  const [assessmentId, setAssessmentId] = useState('')
  const [scores, setScores] = useState<Record<string, string>>({})
  const [absent, setAbsent] = useState<Record<string, boolean>>({})
  const [createOpen, setCreateOpen] = useState(false)
  const [creating, setCreating] = useState(false)
  const [saving, setSaving] = useState(false)
  const [exporting, setExporting] = useState(false)
  const [form] = Form.useForm()
  const inputRefs = useRef<Record<string, InputRef | null>>({})

  const { data: groups = [], error: groupsError, isLoading: groupsLoading } = useSWR<Group[]>(
    '/api/class-groups?status=ACTIVE&include=all', fetcher,
  )
  const selectedGroup = groups.find((group) => group.id === groupId)
  const assessmentUrl = groupId ? `/api/assessments?groupId=${encodeURIComponent(groupId)}` : null
  const { data: assessments = [], error: assessmentsError, isLoading: assessmentsLoading, mutate: refreshAssessments } = useSWR<Assessment[]>(assessmentUrl, fetcher)
  const exam = assessments.find((item) => item.id === assessmentId)
  const students = selectedGroup?.enrollments.map((enrollment) => enrollment.student) || []
  const fullScore = exam?.fullScore ?? 100

  useEffect(() => {
    if (!groupId && groups.length) setGroupId(groups[0].id)
  }, [groupId, groups])

  useEffect(() => {
    if (assessments.length && !assessments.some((item) => item.id === assessmentId)) setAssessmentId(assessments[0].id)
    if (!assessments.length) setAssessmentId('')
  }, [assessmentId, assessments])

  useEffect(() => {
    if (!exam) {
      setScores({})
      setAbsent({})
      return
    }
    setScores(Object.fromEntries(exam.gradeRecords.map((record) => [record.student.id, String(record.score)])))
    setAbsent(Object.fromEntries((exam.absentStudentIds || []).map((studentId) => [studentId, true])))
  }, [exam])

  const isInvalid = (value?: string) => isInvalidGradeScore(value, fullScore)
  const studentIds = students.map((student) => student.id)
  const hasInvalid = students.some((student) => !absent[student.id] && isInvalid(scores[student.id]))
  const doneCount = countCompletedGradeEntries(studentIds, scores, absent)
  const scoreValues = students.flatMap((student) => {
    const value = scores[student.id]?.trim()
    if (absent[student.id] || !value || isInvalid(value)) return []
    return [Number(value)]
  })
  const stats = calculateGradeStats(scoreValues)

  const focusNext = (index: number) => {
    const next = students[index + 1]
    if (next) inputRefs.current[next.id]?.focus()
  }

  const selectAssessment = (nextId: string) => {
    setAssessmentId(nextId)
    setScores({})
    setAbsent({})
  }

  const createAssessment = async () => {
    setCreating(true)
    try {
      const values = await form.validateFields()
      if (!groupId) {
        message.error('请先选择班级')
        return
      }
      const response = await fetch('/api/assessments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          groupId,
          name: values.name.trim(),
          type: values.type,
          assessDate: values.date,
          fullScore: values.fullScore,
        }),
      })
      const result = await response.json().catch(() => ({}))
      if (!response.ok) throw new Error(result.error || '创建测评失败')
      setCreateOpen(false)
      form.resetFields()
      await refreshAssessments()
      setAssessmentId(result.id)
      setScores({})
      setAbsent({})
      message.success('已创建，可以开始录入')
    } catch (error) {
      if (error && typeof error === 'object' && 'errorFields' in error) return
      message.error(error instanceof Error ? error.message : '创建测评失败')
    } finally {
      setCreating(false)
    }
  }

  const save = async (notifyParents: boolean) => {
    if (!exam) return
    if (hasInvalid) {
      message.error(`有成绩超出 0–${fullScore} 的范围，请先修正`)
      return
    }
    if (notifyParents && doneCount < students.length) return
    if (doneCount === 0) {
      message.error('请先录入成绩或标记缺考')
      return
    }

    const records = students.flatMap((student) => {
      const value = scores[student.id]?.trim()
      if (absent[student.id] || !value) return []
      return [{ studentId: student.id, score: Number(value) }]
    })
    const absentStudentIds = students.filter((student) => absent[student.id]).map((student) => student.id)
    setSaving(true)
    try {
      const response = await fetch('/api/grade-records', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ assessmentId: exam.id, records, absentStudentIds, replaceRosterState: true, notifyParents }),
      })
      const result = await response.json().catch(() => ({}))
      if (!response.ok) throw new Error(result.error || '保存成绩失败')
      await refreshAssessments()
      message.success(notifyParents ? '成绩已保存，并已通知家长' : '成绩已保存')
    } catch (error) {
      message.error(error instanceof Error ? error.message : '保存成绩失败')
    } finally {
      setSaving(false)
    }
  }

  const exportGrades = async () => {
    if (!exam) return
    setExporting(true)
    try {
      const response = await fetch(`/api/grade-records/export?assessmentId=${encodeURIComponent(exam.id)}`)
      if (!response.ok) {
        const result = await response.json().catch(() => ({}))
        throw new Error(result.error || '导出失败')
      }
      const url = URL.createObjectURL(await response.blob())
      const anchor = document.createElement('a')
      anchor.href = url
      anchor.download = `${exam.name}_成绩单.xlsx`
      anchor.click()
      URL.revokeObjectURL(url)
      message.success('成绩单已导出')
    } catch (error) {
      message.error(error instanceof Error ? error.message : '导出失败')
    } finally {
      setExporting(false)
    }
  }

  return (
    <PageLayout
      title="测评成绩"
      subtitle="选择班级和测评，逐人录入成绩或标记缺考"
    >
      <div style={{ paddingBottom: 88, width: '100%', maxWidth: 900, margin: '0 auto' }}>
        {groupsError && <Alert type="error" showIcon message={groupsError.message} style={{ marginBottom: 12 }} />}
        {assessmentsError && <Alert type="error" showIcon message={assessmentsError.message} style={{ marginBottom: 12 }} />}

        <div style={{ position: 'sticky', top: 0, zIndex: 20, background: 'var(--color-surface-1)', border: '1px solid var(--color-hairline)', borderRadius: 14, padding: 12, boxShadow: '0 6px 18px rgba(26,18,1,.06)' }}>
          <Space style={{ display: 'flex', width: '100%' }} size={8}>
            <Select
              aria-label="选择班级"
              loading={groupsLoading}
              size="large"
              value={groupId || undefined}
              onChange={(value) => { setGroupId(value); setAssessmentId(''); setScores({}); setAbsent({}) }}
              options={groups.map((group) => ({ value: group.id, label: group.name }))}
              placeholder="选择班级"
              style={{ flex: 1, minWidth: 0 }}
              getPopupContainer={(trigger) => trigger.parentElement || document.body}
              listHeight={280}
              virtual={false}
            />
            <Select
              aria-label="选择测评"
              loading={assessmentsLoading}
              size="large"
              value={assessmentId || undefined}
              onChange={selectAssessment}
              options={assessments.map((item) => ({ value: item.id, label: item.name }))}
              placeholder="选择测评"
              notFoundContent="还没有测评"
              style={{ flex: 1, minWidth: 0 }}
              getPopupContainer={(trigger) => trigger.parentElement || document.body}
              listHeight={280}
              virtual={false}
            />
            <Button type="primary" style={{ minHeight: 44, background: '#14574D', borderColor: '#14574D' }} onClick={() => setCreateOpen(true)}>新建</Button>
          </Space>
        </div>

        {!exam ? (
          <div style={{ padding: '56px 12px' }}>
            <Empty description={groups.length ? '先新建或选择一场测评，再录入成绩' : '当前学部暂无在读班级'}>
              {!!groups.length && <Button type="primary" style={{ minHeight: 44, background: '#14574D', borderColor: '#14574D' }} onClick={() => setCreateOpen(true)}>新建测评</Button>}
            </Empty>
          </div>
        ) : (
          <>
            <div style={{ padding: '12px 4px', display: 'flex', flexWrap: 'wrap', justifyContent: 'space-between', alignItems: 'center', gap: 8, color: 'var(--color-ink-muted)', fontSize: 13 }}>
              <span>{TYPE_LABELS[exam.type] || exam.type} · {new Date(exam.assessDate).toLocaleDateString('zh-CN')} · 满分 {fullScore}</span>
              <span>均分 {stats.average === null ? '—' : stats.average.toFixed(1)} · 最高 {stats.maximum ?? '—'} · 最低 {stats.minimum ?? '—'}</span>
            </div>

            <Card styles={{ body: { padding: 0 } }} style={{ borderRadius: 14, overflow: 'hidden' }}>
              {students.map((student, index) => {
                const isAbsent = Boolean(absent[student.id])
                const invalid = isInvalid(scores[student.id])
                return (
                  <div
                    key={student.id}
                    style={{
                      display: 'flex', alignItems: 'center', gap: 10, minHeight: 62,
                      padding: isMobile ? '9px 12px' : '10px 16px',
                      borderBottom: index === students.length - 1 ? 'none' : '1px solid var(--color-hairline-tertiary)',
                      opacity: isAbsent ? 0.58 : 1,
                    }}
                  >
                    <span style={{ width: 22, color: 'var(--color-ink-subtle)', fontSize: 13, textAlign: 'right', flex: '0 0 22px' }}>{index + 1}</span>
                    <Typography.Text strong style={{ flex: 1, minWidth: 0, fontSize: 16, overflowWrap: 'anywhere' }}>{student.name}</Typography.Text>
                    <a
                      href={`/student-archive?studentId=${student.id}`}
                      target="_blank"
                      rel="noreferrer"
                      style={{
                        fontSize: 12,
                        color: '#14574D',
                        background: '#E8F2F0',
                        border: '1px solid rgba(20,87,77,0.2)',
                        padding: '4px 8px',
                        borderRadius: 6,
                        textDecoration: 'none',
                        whiteSpace: 'nowrap',
                        marginRight: 4,
                      }}
                      title="查看该学员学情档案"
                    >
                      档案
                    </a>
                    <Button
                      aria-pressed={isAbsent}
                      type={isAbsent ? 'primary' : 'default'}
                      danger={isAbsent}
                      onClick={() => setAbsent((previous) => ({ ...previous, [student.id]: !isAbsent }))}
                      style={{ minHeight: 44, flex: '0 0 auto', paddingInline: 10 }}
                    >缺考</Button>
                    <Input
                      ref={(element) => { inputRefs.current[student.id] = element }}
                      disabled={isAbsent}
                      size="large"
                      status={invalid ? 'error' : undefined}
                      value={scores[student.id] ?? ''}
                      onChange={(event) => setScores((previous) => ({ ...previous, [student.id]: event.target.value }))}
                      onPressEnter={() => focusNext(index)}
                      inputMode="decimal"
                      enterKeyHint={index === students.length - 1 ? 'done' : 'next'}
                      placeholder="分数"
                      suffix={<span style={{ color: 'var(--color-ink-subtle)', fontSize: 12 }}>/{fullScore}</span>}
                      aria-label={`${student.name}成绩`}
                      style={{ width: isMobile ? 108 : 128, minHeight: 44, flex: '0 0 auto' }}
                    />
                  </div>
                )
              })}
              {!students.length && <div style={{ padding: 24 }}><Empty description="当前班级没有在班学生" /></div>}
            </Card>

            {hasInvalid && <div role="alert" style={{ padding: '8px 4px', color: 'var(--color-semantic-error)', fontSize: 13 }}>标红的成绩不在 0–{fullScore} 范围内</div>}

            <div style={{ display: 'flex', justifyContent: 'flex-end', paddingTop: 8 }}>
              <Button icon={<DownloadOutlined />} loading={exporting} onClick={() => void exportGrades()}>导出成绩单</Button>
            </div>
          </>
        )}

        {exam && <div style={{ position: 'sticky', bottom: 0, zIndex: 20, marginTop: 10, background: 'var(--color-surface-1)', border: '1px solid var(--color-hairline)', borderRadius: 14, padding: '10px 12px calc(10px + env(safe-area-inset-bottom, 0px))', boxShadow: '0 -5px 18px rgba(26,18,1,.06)', display: 'flex', alignItems: 'center', gap: 8 }}>
          <span style={{ flex: 1, minWidth: 0, color: 'var(--color-ink-muted)', fontSize: 13 }}>已录入 {doneCount}/{students.length}</span>
          <Button style={{ minHeight: 44 }} loading={saving} onClick={() => void save(false)}>保存</Button>
          <Button type="primary" style={{ minHeight: 44 }} loading={saving} disabled={doneCount < students.length || hasInvalid || students.length === 0} onClick={() => void save(true)}>保存并通知家长</Button>
        </div>}
      </div>

      <Modal title="新建测评" open={createOpen} confirmLoading={creating} onOk={() => void createAssessment()} onCancel={() => setCreateOpen(false)} okText="创建测评" cancelText="取消" destroyOnHidden>
        <Form form={form} layout="vertical" initialValues={{ type: 'STAGE', date: localDateInput(), fullScore: 100 }}>
          <Form.Item name="name" label="测评名称" rules={[{ required: true, whitespace: true, message: '请输入测评名称' }, { max: 120, message: '测评名称不能超过 120 字' }]}>
            <Input placeholder="如：11月阶段测评" maxLength={120} />
          </Form.Item>
          <Form.Item name="type" label="类型" rules={[{ required: true, message: '请选择测评类型' }]}>
            <Select options={EXAM_TYPES} />
          </Form.Item>
          <Form.Item name="date" label="日期" rules={[{ required: true, message: '请选择测评日期' }]}>
            <Input type="date" />
          </Form.Item>
          <Form.Item name="fullScore" label="满分" rules={[{ required: true, message: '请输入满分' }]}>
            <InputNumber min={1} max={1000} precision={2} style={{ width: '100%' }} />
          </Form.Item>
        </Form>
      </Modal>
    </PageLayout>
  )
}

'use client'

import { useCallback, useEffect, useMemo, useState } from 'react'
import NextImage from 'next/image'
import {
  Button, Form, Input, Popconfirm, Segmented, Select, Space,
  Switch, Table, Tag, Upload, message, Tooltip,
} from 'antd'
import { BrandModal } from '@/components/Common/BrandModal'
import {
  DeleteOutlined,
  DownloadOutlined,
  EyeOutlined,
  FilePdfOutlined,
  FileWordOutlined,
  FileExcelOutlined,
  FilePptOutlined,
  FileImageOutlined,
  FileTextOutlined,
  PlusOutlined,
  UploadOutlined,
  SearchOutlined,
  ReloadOutlined,
  CloudServerOutlined,
  CheckCircleOutlined,
  UserOutlined,
  TeamOutlined,
  FolderOpenOutlined,
  AppstoreOutlined,
} from '@ant-design/icons'
import type { ColumnsType } from 'antd/es/table'
import type { UploadFile } from 'antd/es/upload/interface'
import { GRADE_SUBJECTS, GRADES, SUBJECT_COLORS } from '@/data/subjects'
import {
  materialAudienceLabel,
  materialFileLabel,
  materialSourceLabel,
  materialStatusLabel,
} from '@/lib/material-format'

const { TextArea } = Input

interface Material {
  id: string
  title: string
  grade: string
  subject: string
  fileName: string
  fileSize: number
  fileType: string
  materialType: string
  description: string | null
  downloads: number
  audience: string
  source: string
  status: string
  tags: string[]
  isPinned: boolean
  storageDriver: string | null
  createdAt: string
  uploader?: { name: string | null }
  teacher?: { id: string; name: string } | null
}

const OSS_DOC_EXTS = ['.pdf', '.doc', '.docx', '.xls', '.xlsx', '.ppt', '.pptx']
const OSS_MAX_SIZE = 200 * 1024 * 1024 // 200MB
const LOCAL_MAX_SIZE = 50 * 1024 * 1024 // 50MB
const LOCAL_EXTS = ['.pdf', '.jpg', '.jpeg', '.png', '.gif', '.webp', '.doc', '.docx', '.xls', '.xlsx', '.ppt', '.pptx', '.zip', '.rar', '.7z']
const MATERIAL_TYPE_NAMES: Record<string, string> = {
  TEXTBOOK: '课本',
  HANDOUT: '讲义',
  EXERCISE: '题库',
  EXAM: '试卷',
  ANSWER: '答案',
  REFERENCE: '参考',
}

function getFileIcon(type: string) {
  switch (type?.toLowerCase()) {
    case 'pdf':
      return <FilePdfOutlined style={{ color: '#E03131' }} />
    case 'word':
    case 'doc':
    case 'docx':
      return <FileWordOutlined style={{ color: '#1971C2' }} />
    case 'excel':
    case 'xls':
    case 'xlsx':
      return <FileExcelOutlined style={{ color: '#2F9E44' }} />
    case 'ppt':
    case 'pptx':
      return <FilePptOutlined style={{ color: '#D9480F' }} />
    case 'image':
    case 'png':
    case 'jpg':
    case 'jpeg':
      return <FileImageOutlined style={{ color: '#9C36B5' }} />
    default:
      return <FileTextOutlined style={{ color: '#14574D' }} />
  }
}

function formatBytes(bytes?: number) {
  if (!bytes || bytes <= 0) return ''
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

async function readApiError(res: Response, fallback: string) {
  const data = await res.json().catch(() => ({}))
  const error = typeof data.error === 'string' ? data.error : fallback
  const code = typeof data.code === 'string' ? data.code : undefined
  return { error, code }
}

function uploadFailureMessage(error: string, code?: string) {
  if (code === 'OSS_SDK_MISSING') {
    return '资料上传失败：OSS 依赖未安装，请联系管理员在服务器安装 ali-oss 并重启服务。'
  }
  if (code === 'OSS_CONFIG_MISSING') {
    return `资料上传失败：${error}，请联系管理员配置 OSS。`
  }
  return `资料上传失败：${error}`
}

export default function MaterialsPage() {
  const [materials, setMaterials] = useState<Material[]>([])
  const [loading, setLoading] = useState(true)
  const [uploading, setUploading] = useState(false)
  const [uploadOpen, setUploadOpen] = useState(false)
  const [previewUrl, setPreviewUrl] = useState<string | null>(null)
  const [previewType, setPreviewType] = useState<'pdf' | 'image' | 'word'>('pdf')
  const [searchKeyword, setSearchKeyword] = useState('')
  const [filterGrade, setFilterGrade] = useState('')
  const [filterSubject, setFilterSubject] = useState('')
  const [filterAudience, setFilterAudience] = useState('')
  const [filterTeacherId, setFilterTeacherId] = useState('')
  const [ossEnabled, setOssEnabled] = useState(false)
  const [form] = Form.useForm()
  const selectedGrade = Form.useWatch('grade', form)
  const [fileList, setFileList] = useState<UploadFile[]>([])

  const fetchMaterials = useCallback(async () => {
    setLoading(true)
    const params = new URLSearchParams()
    if (filterGrade) params.set('grade', filterGrade)
    if (filterSubject) params.set('subject', filterSubject)
    if (filterAudience) params.set('audience', filterAudience)
    if (filterTeacherId) params.set('teacherId', filterTeacherId)
    const res = await fetch(`/api/materials?${params}`)
    const data = await res.json()
    setMaterials(data.materials || [])
    setLoading(false)
  }, [filterGrade, filterSubject, filterAudience, filterTeacherId])

  useEffect(() => {
    const params = new URLSearchParams(window.location.search)
    setFilterTeacherId(params.get('teacherId') || '')
    fetch('/api/materials/oss-signature')
      .then(r => r.json())
      .then(d => setOssEnabled(!!d.enabled))
      .catch(() => setOssEnabled(false))
  }, [])

  useEffect(() => {
    fetchMaterials()
  }, [fetchMaterials])

  const subjectOptions = useMemo(() => {
    const source = filterGrade ? GRADE_SUBJECTS[filterGrade] || [] : Array.from(new Set(Object.values(GRADE_SUBJECTS).flat()))
    return source.map((subject) => ({ label: subject, value: subject }))
  }, [filterGrade])

  const uploadSubjectOptions = (selectedGrade ? GRADE_SUBJECTS[selectedGrade] || [] : []).map((subject) => ({ label: subject, value: subject }))

  // 前端关键字过滤
  const filteredMaterials = useMemo(() => {
    if (!searchKeyword.trim()) return materials
    const kw = searchKeyword.trim().toLowerCase()
    return materials.filter(m =>
      m.title.toLowerCase().includes(kw) ||
      m.fileName?.toLowerCase().includes(kw) ||
      m.teacher?.name?.toLowerCase().includes(kw) ||
      m.uploader?.name?.toLowerCase().includes(kw) ||
      m.subject?.toLowerCase().includes(kw),
    )
  }, [materials, searchKeyword])

  const handleUpload = async () => {
    const values = await form.validateFields()
    const file = fileList[0]?.originFileObj as File | undefined
    if (!file) {
      message.warning('请选择文件')
      return
    }

    const ext = file.name.slice(file.name.lastIndexOf('.')).toLowerCase()
    if (ossEnabled) {
      if (!OSS_DOC_EXTS.includes(ext)) {
        message.error('仅支持 PDF、Word、Excel、PPT 文档格式')
        return
      }
      if (file.size > OSS_MAX_SIZE) {
        message.error('文件大小不能超过 200MB')
        return
      }
    } else {
      if (!LOCAL_EXTS.includes(ext)) {
        message.error('仅支持 PDF、Word、Excel、PPT、图片和压缩包格式')
        return
      }
      if (file.size > LOCAL_MAX_SIZE) {
        message.error('文件大小不能超过 50MB')
        return
      }
    }

    setUploading(true)
    try {
      if (ossEnabled) {
        const sigRes = await fetch('/api/materials/oss-signature', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ fileName: file.name, contentType: file.type }),
        })
        if (!sigRes.ok) {
          const err = await readApiError(sigRes, '获取上传签名失败')
          message.error(uploadFailureMessage(err.error, err.code))
          setUploading(false)
          return
        }
        const sig = await sigRes.json()

        const ossForm = new FormData()
        ossForm.append('key', sig.key)
        ossForm.append('policy', sig.policy)
        ossForm.append('signature', sig.signature)
        ossForm.append('OSSAccessKeyId', sig.accessKeyId)
        ossForm.append('success_action_status', '200')
        ossForm.append('file', file)

        const ossRes = await fetch(`https://${sig.host}`, { method: 'POST', body: ossForm })
        if (!ossRes.ok) {
          const errText = await ossRes.text().catch(() => '')
          message.error('资料上传失败：OSS 上传失败，' + (errText || ossRes.statusText))
          setUploading(false)
          return
        }

        const metaRes = await fetch('/api/materials/upload', {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            key: sig.key,
            fileName: file.name,
            fileSize: file.size,
            contentType: file.type,
            title: values.title,
            grade: values.grade,
            subject: values.subject,
            audience: values.audience,
            materialType: values.materialType,
            status: 'PUBLISHED',
            isPinned: Boolean(values.isPinned),
            description: values.description || undefined,
            tags: values.tags || undefined,
          }),
        })
        if (!metaRes.ok) {
          const err = await readApiError(metaRes, '保存资料信息失败')
          message.error(uploadFailureMessage(err.error, err.code))
          setUploading(false)
          return
        }
      } else {
        const formData = new FormData()
        formData.append('file', file)
        formData.append('title', values.title)
        formData.append('grade', values.grade)
        formData.append('subject', values.subject)
        formData.append('audience', values.audience)
        formData.append('materialType', values.materialType)
        formData.append('status', 'PUBLISHED')
        formData.append('isPinned', String(Boolean(values.isPinned)))
        if (values.description) formData.append('description', values.description)
        if (values.tags) formData.append('tags', values.tags)

        const res = await fetch('/api/materials/upload', { method: 'POST', body: formData })
        if (!res.ok) {
          const err = await readApiError(res, '上传失败')
          message.error(uploadFailureMessage(err.error, err.code))
          setUploading(false)
          return
        }
      }

      message.success('资料上传成功')
      setUploadOpen(false)
      form.resetFields()
      setFileList([])
      fetchMaterials()
    } finally {
      setUploading(false)
    }
  }

  const handleDelete = async (id: string) => {
    const res = await fetch(`/api/materials?id=${id}`, { method: 'DELETE' })
    if (res.ok) {
      message.success('资料已删除')
      fetchMaterials()
    } else {
      message.error('删除失败')
    }
  }

  const handlePreview = async (material: Material) => {
    if (material.fileType === 'word') {
      const res = await fetch(`/api/materials/${material.id}/view`)
      const data = await res.json()
      if (data.viewerUrl) {
        setPreviewType('word')
        setPreviewUrl(data.viewerUrl)
      }
      return
    }
    if (['pdf', 'image'].includes(material.fileType)) {
      const url = `/api/materials/${material.id}/view`
      if (material.storageDriver === 'aliyun-oss') {
        const res = await fetch(url)
        const data = await res.json()
        if (data.url) {
          setPreviewType(material.fileType as 'pdf' | 'image')
          setPreviewUrl(data.url)
        }
        return
      }
      setPreviewType(material.fileType as 'pdf' | 'image')
      setPreviewUrl(url)
      return
    }
    window.open(`/api/materials/${material.id}/view?download=1`, '_blank')
  }

  const columns: ColumnsType<Material> = [
    {
      title: '资料名称',
      dataIndex: 'title',
      render: (title: string, row) => (
        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 10, minWidth: 260 }}>
          <div style={{ fontSize: 20, paddingTop: 2 }}>
            {getFileIcon(row.fileType)}
          </div>
          <div style={{ minWidth: 0, flex: 1 }}>
            <div style={{ fontWeight: 700, fontSize: 14, color: '#17352F', lineHeight: 1.35 }}>{title}</div>
            <div style={{ fontSize: 11.5, color: '#8A7E6B', marginTop: 2 }}>
              {row.fileName} {row.fileSize ? `· ${formatBytes(row.fileSize)}` : ''}
            </div>
            {row.description && <div style={{ fontSize: 12, color: '#999', marginTop: 3 }}>{row.description}</div>}
          </div>
        </div>
      ),
    },
    {
      title: '学段学科',
      width: 140,
      render: (_, row) => (
        <Space size={4}>
          <Tag color="default">{row.grade}</Tag>
          <Tag color={SUBJECT_COLORS[row.subject] || 'default'}>{row.subject}</Tag>
        </Space>
      ),
    },
    {
      title: '分类 / 受众',
      width: 160,
      render: (_, row) => (
        <Space size={4}>
          <Tag color="cyan">{MATERIAL_TYPE_NAMES[row.materialType] || '讲义'}</Tag>
          <Tag color={row.audience === 'TEACHER' ? 'orange' : row.audience === 'BOTH' ? 'blue' : 'green'}>
            {materialAudienceLabel(row.audience)}
          </Tag>
        </Space>
      ),
    },
    {
      title: '上传人 / 时间',
      width: 160,
      render: (_, row) => (
        <div style={{ fontSize: 12 }}>
          <div style={{ color: '#17352F', fontWeight: 600 }}>{row.teacher?.name || row.uploader?.name || '管理员'}</div>
          <div style={{ color: '#999' }}>{new Date(row.createdAt).toLocaleDateString('zh-CN')}</div>
        </div>
      ),
    },
    {
      title: '下载次数',
      dataIndex: 'downloads',
      width: 90,
      align: 'center',
      render: (v) => <span style={{ fontWeight: 700, color: '#14574D' }}>{v || 0}</span>,
    },
    {
      title: '操作',
      width: 160,
      fixed: 'right',
      render: (_value, row) => (
        <Space orientation="horizontal" size={8}>
          <Button size="small" type="link" icon={<EyeOutlined />} onClick={() => handlePreview(row)}>
            预览
          </Button>
          <Button size="small" type="link" icon={<DownloadOutlined />} onClick={() => window.open(`/api/materials/${row.id}/view?download=1`, '_blank')}>
            下载
          </Button>
          <Popconfirm title="删除后家长端和教师端都不可见，确认删除？" onConfirm={() => handleDelete(row.id)}>
            <Button size="small" type="link" danger icon={<DeleteOutlined />}>
              删除
            </Button>
          </Popconfirm>
        </Space>
      ),
    },
  ]

  const studentCount = materials.filter((item) => item.audience === 'STUDENT').length
  const teacherCount = materials.filter((item) => item.audience === 'TEACHER').length
  const bothCount = materials.filter((item) => item.audience === 'BOTH').length
  const hasFilter = Boolean(filterGrade || filterSubject || filterAudience || filterTeacherId || searchKeyword)

  return (
    <div className="admin-materials-view">
      {/* 
        【顶部 Header 与状态栏】
      */}
      <div className="admin-header-card">
        <div className="admin-header-left">
          <div className="title-row">
            <h1 className="admin-page-title">学习资料管理</h1>
            <span className="driver-pill">
              <CloudServerOutlined /> {ossEnabled ? '阿里云 OSS 存储' : '本地安全存储'}
            </span>
          </div>
          <p className="admin-page-subtitle">
            全校教学资料统一中台 · 涵盖学生同步课本、章节讲义、单元试卷与教师备课包
          </p>
        </div>

        <div className="admin-header-right">
          <Button
            type="primary"
            icon={<PlusOutlined />}
            className="upload-hero-btn"
            onClick={() => setUploadOpen(true)}
          >
            上传学习资料
          </Button>
        </div>
      </div>

      {/* 
        【指标看板：微拟物紧凑一体化条】
        告别原先 4 个傻大方块，采用单行连贯卡片，可点击快速筛选
      */}
      <div className="stats-strip">
        <div
          className={`stat-cell ${filterAudience === '' ? 'active' : ''}`}
          onClick={() => setFilterAudience('')}
        >
          <div className="stat-icon-wrap" style={{ background: 'rgba(20, 87, 77, 0.1)', color: '#14574D' }}>
            <FolderOpenOutlined />
          </div>
          <div className="stat-text-box">
            <span className="stat-label">全部学习资料</span>
            <span className="stat-number">{materials.length}</span>
          </div>
        </div>

        <div
          className={`stat-cell ${filterAudience === 'STUDENT' ? 'active' : ''}`}
          onClick={() => setFilterAudience('STUDENT')}
        >
          <div className="stat-icon-wrap" style={{ background: 'rgba(47, 158, 68, 0.1)', color: '#2F9E44' }}>
            <UserOutlined />
          </div>
          <div className="stat-text-box">
            <span className="stat-label">学生版 · 家长可见</span>
            <span className="stat-number">{studentCount}</span>
          </div>
        </div>

        <div
          className={`stat-cell ${filterAudience === 'TEACHER' ? 'active' : ''}`}
          onClick={() => setFilterAudience('TEACHER')}
        >
          <div className="stat-icon-wrap" style={{ background: 'rgba(245, 159, 0, 0.1)', color: '#F59F00' }}>
            <TeamOutlined />
          </div>
          <div className="stat-text-box">
            <span className="stat-label">教师版 · 内部备课</span>
            <span className="stat-number">{teacherCount}</span>
          </div>
        </div>

        <div
          className={`stat-cell ${filterAudience === 'BOTH' ? 'active' : ''}`}
          onClick={() => setFilterAudience('BOTH')}
        >
          <div className="stat-icon-wrap" style={{ background: 'rgba(25, 113, 194, 0.1)', color: '#1971C2' }}>
            <AppstoreOutlined />
          </div>
          <div className="stat-text-box">
            <span className="stat-label">通用版 · 全员共享</span>
            <span className="stat-number">{bothCount}</span>
          </div>
        </div>
      </div>

      {/* 
        【一体化工作台筛选栏】
        搜索、年级、科目、受众紧凑整合，告别松散多排堆叠
      */}
      <div className="filter-work-bar">
        <div className="filter-inputs">
          <Input
            prefix={<SearchOutlined style={{ color: '#A09580' }} />}
            placeholder="搜索资料名称 / 上传老师..."
            allowClear
            className="search-input"
            value={searchKeyword}
            onChange={(e) => setSearchKeyword(e.target.value)}
          />

          <Select
            placeholder="全部年级"
            allowClear
            className="filter-select"
            value={filterGrade || undefined}
            onChange={(value) => {
              setFilterGrade(value || '')
              setFilterSubject('')
            }}
            options={GRADES.map((grade) => ({ label: grade, value: grade }))}
          />

          <Select
            placeholder="全部科目"
            allowClear
            className="filter-select"
            value={filterSubject || undefined}
            onChange={(value) => setFilterSubject(value || '')}
            options={subjectOptions}
          />
        </div>

        <div className="filter-audience-wrap">
          <Segmented
            aria-label="资料受众"
            value={filterAudience || 'all'}
            onChange={(val) => setFilterAudience(val === 'all' ? '' : String(val))}
            options={[
              { label: '全部', value: 'all' },
              { label: '学生版', value: 'STUDENT' },
              { label: '教师版', value: 'TEACHER' },
              { label: '通用版', value: 'BOTH' },
            ]}
          />

          {hasFilter && (
            <button
              type="button"
              className="clear-btn"
              onClick={() => {
                setFilterGrade('')
                setFilterSubject('')
                setFilterAudience('')
                setFilterTeacherId('')
                setSearchKeyword('')
              }}
            >
              <ReloadOutlined /> 重置
            </button>
          )}
        </div>
      </div>

      {/* 
        【桌面端：现代化 Table 呈现】
      */}
      <div className="desktop-table-container">
        <Table
          columns={columns}
          dataSource={filteredMaterials}
          loading={loading}
          rowKey="id"
          pagination={{ pageSize: 15, showTotal: (t) => `共 ${t} 份资料` }}
          scroll={{ x: 1080 }}
          className="admin-clean-table"
        />
      </div>

      {/* 
        【移动端：全新精致卡片列表】
        杜绝原来的 3 个粗苯大按钮，采用清晰层级与紧凑操作
      */}
      <div className="mobile-cards-container">
        {filteredMaterials.length === 0 ? (
          <div className="mobile-empty">
            <p>未找到符合条件的学习资料</p>
          </div>
        ) : (
          filteredMaterials.map((material) => (
            <div key={material.id} className="mobile-material-card">
              <div className="card-top-row">
                <div className="doc-type-icon">
                  {getFileIcon(material.fileType)}
                </div>
                <div className="doc-main-info">
                  <h3 className="doc-title">{material.title}</h3>
                  <div className="doc-file-meta">
                    {material.fileName} {material.fileSize ? `· ${formatBytes(material.fileSize)}` : ''}
                  </div>
                </div>
              </div>

