'use client'

import { useCallback, useEffect, useMemo, useState } from 'react'
import {
  Alert, Button, Card, Col, DatePicker, Form, Input, Row, Statistic, Switch,
  Table, Tabs, Tag, Typography, Upload, message,
} from 'antd'
import { BrandModal } from '@/components/Common/BrandModal'
import {
  DownOutlined, DownloadOutlined, EditOutlined, InboxOutlined, ReloadOutlined, UpOutlined,
} from '@ant-design/icons'
import dayjs, { Dayjs } from 'dayjs'
import { useIsMobile } from '@/hooks/useIsMobile'
import { useDivision } from '@/contexts/DivisionContext'
import { PageLayout } from '@/components/Layout/PageLayout'
import { StudentMealLedger } from './StudentMealLedger'

const { Title, Text } = Typography
const WEEKDAYS = ['周一', '周二', '周三', '周四', '周五', '周六']

type MealTemplate = {
  id: string
  weekday: number
  title: string | null
  breakfast: string | null
  lunch: string | null
  dinner: string | null
  snack: string | null
  note: string | null
  image: string | null
  description: string | null
  allowDouble?: boolean
  startDate?: string | null
  endDate?: string | null
}

type MealReport = {
  id: string
  teacher: { id: string; name: string }
  submittedAt: string
  totalCount: number
  riceSingle: number
  riceDouble: number
  details: Array<{ studentId: string; studentName: string; portion: 'single' | 'double'; groupName?: string; appended?: boolean }>
}

type TeacherSummary = { id?: string; name?: string; groupName?: string }

type MealSummary = {
  totalCount: number
  singleCount: number
  doubleCount: number
  lateAddedCount?: number
  unreportedTeachers: TeacherSummary[]
  parentStats?: {
    eating: number
    notEating: number
    unselected: number
  }
}

function mondayOf(value: Dayjs) {
  const offset = value.day() === 0 ? 6 : value.day() - 1
  return value.startOf('day').subtract(offset, 'day')
}

/** 菜品图片上传组件：支持预览、替换、删除，上传到 /api/upload（meal-image 类型，家长可见） */
function MealImageUpload({
  value, onChange,
}: {
  value?: string | null
  onChange?: (v: string | null) => void
}) {
  const [uploading, setUploading] = useState(false)

  const handleUpload = async (file: File) => {
    if (!file.type.startsWith('image/')) {
      message.error('请选择图片文件')
      return
    }
    if (file.size > 5 * 1024 * 1024) {
      message.error('图片不能超过 5MB')
      return
    }
    setUploading(true)
    try {
      const fd = new FormData()
      fd.append('file', file)
      fd.append('uploadType', 'meal-image')
      const res = await fetch('/api/upload', { method: 'POST', body: fd })
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || '上传失败')
      // 优先用缩略图，列表加载更快
      onChange?.(data.url)
      message.success('图片已上传')
    } catch (e) {
      message.error(e instanceof Error ? e.message : '上传失败')
    } finally {
      setUploading(false)
    }
  }

  if (value) {
    return (
      <div>
        <div style={{
          borderRadius: 12, overflow: 'hidden', border: '1px solid #EEE7E1',
        }}>
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={value}
            alt="菜品照片"
            style={{ width: '100%', maxHeight: 200, objectFit: 'cover', display: 'block' }}
          />
        </div>
        <div style={{ display: 'flex', gap: 8, marginTop: 8 }}>
          <Upload
            showUploadList={false}
            accept="image/*"
            beforeUpload={(f) => { void handleUpload(f); return false }}
          >
            <Button size="small" icon={<EditOutlined />} loading={uploading}>替换图片</Button>
          </Upload>
          <Button size="small" danger onClick={() => onChange?.(null)}>删除</Button>
        </div>
      </div>
    )
  }

  return (
    <Upload.Dragger
      showUploadList={false}
      accept="image/*"
      disabled={uploading}
      beforeUpload={(f) => { void handleUpload(f); return false }}
      style={{ borderRadius: 12 }}
    >
      <p className="ant-upload-drag-icon">
        <InboxOutlined style={{ color: uploading ? '#bbb' : '#2E6B50' }} />
      </p>
      <p className="ant-upload-text" style={{ fontSize: 13 }}>
        {uploading ? '上传中…' : '点击或拖拽上传菜品照片'}
      </p>
      <p className="ant-upload-hint" style={{ fontSize: 11 }}>
        支持 JPG / PNG / WebP，建议不超过 5MB
      </p>
    </Upload.Dragger>
  )
}

export default function MealsPage() {
  const isMobile = useIsMobile() ?? false
  const { division } = useDivision()
  const [historyWeek, setHistoryWeek] = useState(() => mondayOf(dayjs()))
  const [templates, setTemplates] = useState<MealTemplate[]>([])
  const [reports, setReports] = useState<MealReport[]>([])
  const [historyReports, setHistoryReports] = useState<MealReport[]>([])
  const [summary, setSummary] = useState<MealSummary>({ totalCount: 0, singleCount: 0, doubleCount: 0, unreportedTeachers: [] })
  const [templateEditing, setTemplateEditing] = useState<{ weekday: number; template?: MealTemplate } | null>(null)
  const [saving, setSaving] = useState(false)
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set())
  const [showUnreported, setShowUnreported] = useState(false)
  const [activeTab, setActiveTab] = useState('student-ledger')
  const [refreshingToday, setRefreshingToday] = useState(false)
  const [lastRefreshedAt, setLastRefreshedAt] = useState<Dayjs | null>(null)
  const [refreshError, setRefreshError] = useState('')
  const [templateForm] = Form.useForm()
  const today = dayjs().format('YYYY-MM-DD')

  const fetchTemplates = useCallback(async () => {
    const res = await fetch(`/api/admin/meal-templates?division=${division}`)
    const data = await res.json()
    setTemplates(data.templates || [])
  }, [division])

  const fetchToday = useCallback(async () => {
    setRefreshingToday(true)
    try {
      const cacheBuster = Date.now()
      const [reportRes, summaryRes] = await Promise.all([
        fetch(`/api/meals/report?date=${today}&_=${cacheBuster}`, { cache: 'no-store' }),
        fetch(`/api/meals/summary?date=${today}&_=${cacheBuster}`, { cache: 'no-store' }),
      ])
      const reportData = await reportRes.json().catch(() => ({}))
      const summaryData = await summaryRes.json().catch(() => ({}))
      if (!reportRes.ok || !summaryRes.ok) {
        throw new Error(reportData.error || summaryData.error || '就餐记录刷新失败')
      }
      setReports(reportData.reports || [])
      setSummary(summaryData || {})
      setLastRefreshedAt(dayjs())
      setRefreshError('')
    } catch (error) {
      setRefreshError(error instanceof Error ? error.message : '就餐记录刷新失败')
    } finally {
      setRefreshingToday(false)
    }
  }, [today])

  const fetchHistory = useCallback(async () => {
    const payloads = await Promise.all(Array.from({ length: 6 }, (_, index) =>
      fetch(`/api/meals/report?date=${historyWeek.add(index, 'day').format('YYYY-MM-DD')}`).then((res) => res.json())
    ))
    setHistoryReports(payloads.flatMap((payload) => payload.reports || []))
  }, [historyWeek])

  useEffect(() => { fetchTemplates() }, [fetchTemplates])
  useEffect(() => {
    void fetchToday()
    const timer = window.setInterval(() => void fetchToday(), 15000)
    const refreshOnVisible = () => { if (document.visibilityState === 'visible') void fetchToday() }
    const refreshOnReturn = () => void fetchToday()
    document.addEventListener('visibilitychange', refreshOnVisible)
    window.addEventListener('focus', refreshOnReturn)
    window.addEventListener('pageshow', refreshOnReturn)
    return () => {
      window.clearInterval(timer)
      document.removeEventListener('visibilitychange', refreshOnVisible)
      window.removeEventListener('focus', refreshOnReturn)
      window.removeEventListener('pageshow', refreshOnReturn)
    }
  }, [fetchToday])
  useEffect(() => { fetchHistory() }, [fetchHistory])

  const templateMap = useMemo(() => new Map(templates.map((template) => [template.weekday, template])), [templates])

  const groupedMealDetails = useMemo(() => {
    const groups = new Map<string, Array<MealReport['details'][number] & { teacherName: string; submittedAt: string }>>()
    const seen = new Set<string>()
    reports.forEach((report) => {
      report.details?.forEach((detail) => {
        const groupName = detail.groupName?.trim() || `${report.teacher.name}上报`
        const key = `${groupName}:${detail.studentId}`
        if (seen.has(key)) return
        seen.add(key)
        groups.set(groupName, [
          ...(groups.get(groupName) || []),
          { ...detail, groupName, teacherName: report.teacher.name, submittedAt: report.submittedAt },
        ])
      })
    })
    return [...groups.entries()].map(([groupName, details]) => ({ groupName, details }))
  }, [reports])

  const groupedTotal = useMemo(
    () => groupedMealDetails.reduce((sum, group) => sum + group.details.length, 0),
    [groupedMealDetails],
  )

  const openTemplateEditor = (weekday: number, template?: MealTemplate) => {
    setTemplateEditing({ weekday, template })
    templateForm.setFieldsValue({
      lunch: template?.lunch,
      allowDouble: template?.allowDouble !== false,
      note: template?.note,
      description: template?.description,
      imageUrl: template?.image || null,
      dateRange: template?.startDate || template?.endDate
        ? [template.startDate ? dayjs(template.startDate) : null, template.endDate ? dayjs(template.endDate) : null]
        : null,
    })
  }

  const saveTemplate = async () => {
    const values = await templateForm.validateFields()
    setSaving(true)
    try {
      const res = await fetch(templateEditing?.template ? `/api/admin/meal-templates/${templateEditing.template.id}` : '/api/admin/meal-templates', {
        method: templateEditing?.template ? 'PUT' : 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          weekday: templateEditing?.weekday,
          lunch: values.lunch,
          allowDouble: values.allowDouble,
          note: values.note || null,
          description: values.description || null,
          image: values.imageUrl || null,
          startDate: values.dateRange?.[0] ? values.dateRange[0].format('YYYY-MM-DD') : null,
          endDate: values.dateRange?.[1] ? values.dateRange[1].format('YYYY-MM-DD') : null,
        }),
      })
      if (!res.ok) throw new Error('save failed')
      message.success('周期菜单已保存')
      setTemplateEditing(null)
      templateForm.resetFields()
      fetchTemplates()
    } catch {
      message.error('周期菜单保存失败')
    } finally {
      setSaving(false)
    }
  }

  const exportToday = () => {
    const csvCell = (value: string | number) => `"${String(value).replaceAll('"', '""')}"`
    const rows = [
      ['班级', '学员姓名', '份数', '上报来源', '教师', '上报时间'],
      ...groupedMealDetails.flatMap((group) => group.details.map((detail) => [
        group.groupName,
        detail.studentName,
        detail.portion === 'double' ? '双份' : '单份',
        detail.appended ? '后续课次追加' : '系统第一课节上报',
        detail.teacherName,
        dayjs(detail.submittedAt).format('YYYY-MM-DD HH:mm'),
      ])),
      ['合计', '', groupedTotal, '', '', ''],
    ]
    const csvLines = rows.map((row) => row.map(csvCell).join(','))
    const blob = new Blob([`\uFEFF${csvLines.join('\r\n')}`], {
      type: 'text/csv;charset=utf-8',
    })
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    link.download = `牧哲学堂_就餐汇总-${today}.csv`
    link.click()
    URL.revokeObjectURL(url)
  }

  const reportColumns = [
    { title: '教师姓名', dataIndex: ['teacher', 'name'], key: 'teacher' },
    { title: '上报时间', dataIndex: 'submittedAt', key: 'submittedAt', render: (value: string) => dayjs(value).format('MM-DD HH:mm') },
    { title: '就餐人数', dataIndex: 'totalCount', key: 'totalCount' },
    { title: '双份人数', dataIndex: 'riceDouble', key: 'riceDouble' },
  ]

  return (
    <PageLayout
      title="就餐管理"
      subtitle="周期菜单维护 · 教师每日就餐上报统计 · 学生就餐台账"
    >
      <Tabs
        activeKey={activeTab}
        onChange={(key) => {
          setActiveTab(key)
          if (key === 'reports') void fetchToday()
        }}
        items={[
        {
          key: 'student-ledger',
          label: '学生就餐台账',
          children: <StudentMealLedger />,
        },
        {
          key: 'templates',
          label: '周期菜单',
          children: (
            <div>
              <div style={{
                display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 8,
                marginBottom: 12, padding: '10px 12px', borderRadius: 10,
                background: 'var(--color-primary-bg)', border: '1px solid var(--color-hairline)',
              }}>
                <Text strong>当前运营批次：{division === 'SENIOR' ? '高中' : '初中'}</Text>
                <Text type="secondary" style={{ fontSize: 12 }}>
                  周期菜单按生效日期展示；如显示的不是当季菜品，请编辑该日模板并设置生效起止日期。
                </Text>
              </div>
              <div style={{
                display: 'grid',
                gridTemplateColumns: isMobile ? 'repeat(2, minmax(0, 1fr))' : 'repeat(4, minmax(0, 1fr))',
                gap: 12,
              }}>
              {WEEKDAYS.map((weekday, index) => {
                const dayOfWeek = index + 1
                const template = templateMap.get(dayOfWeek)
                return (
                  <Card
                    key={weekday}
                    hoverable
                    onClick={() => !template && openTemplateEditor(dayOfWeek)}
                    style={{
                      borderRadius: 10,
                      minHeight: template ? 116 : 76,
                      border: template ? '1px solid #EEE7E1' : '1px dashed #E8D8CA',
                      background: template ? '#fff' : '#FCFBF9',
                    }}
                    styles={{ body: { padding: isMobile ? 10 : 12 } }}
                  >
                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8, marginBottom: template ? 8 : 0 }}>
                      <Text strong style={{ fontSize: 14, color: '#1F2329' }}>{weekday}</Text>
                      {template && (
                        <Button
                          size="small"
                          type="text"
                          icon={<EditOutlined />}
                          onClick={(event) => { event.stopPropagation(); openTemplateEditor(dayOfWeek, template) }}
                        >
                          编辑
                        </Button>
                      )}
                    </div>
                    {template ? (
                      <div style={{ display: 'grid', gap: 6 }}>
                        <Text strong style={{ fontSize: 15, color: '#1F2329', lineHeight: 1.35 }}>{template.lunch || '未设置米饭配菜'}</Text>
                        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, alignItems: 'center' }}>
                          <Tag color={template.allowDouble !== false ? 'green' : 'default'} style={{ margin: 0 }}>
                            {template.allowDouble !== false ? '可双倍米饭' : '不可双倍'}
                          </Tag>
                          {template.note && <Text type="secondary" style={{ fontSize: 12 }}>{template.note}</Text>}
                          {(template.startDate || template.endDate) && (
                            <Text type="secondary" style={{ fontSize: 11, display: 'block' }}>
                              生效：{template.startDate ? dayjs(template.startDate).format('MM-DD') : '不限'} 至 {template.endDate ? dayjs(template.endDate).format('MM-DD') : '不限'}
                            </Text>
                          )}
                        </div>
                      </div>
                    ) : (
                      <Button type="link" size="small" style={{ padding: 0, height: 24 }} onClick={(event) => { event.stopPropagation(); openTemplateEditor(dayOfWeek) }}>
                        点击设置
                      </Button>
                    )}
                  </Card>
                )
              })}
            </div>
            </div>
          ),
        },
        {
          key: 'reports',
          label: '教师上报',
          children: (
            <>
              <div style={{
                display: 'flex', flexWrap: 'wrap', alignItems: 'center', justifyContent: 'space-between',
                gap: 8, marginBottom: 12, padding: '10px 12px', borderRadius: 10,
                background: 'var(--color-primary-bg)', border: '1px solid var(--color-hairline)',
              }}>
                <div>
                  <Text strong style={{ display: 'block' }}>今日 {today} · 自动刷新已开启</Text>
                  <Text type="secondary" style={{ fontSize: 12 }}>
                    每15秒刷新，重新进入页面也会立即刷新
                    {lastRefreshedAt ? ` · 上次 ${lastRefreshedAt.format('HH:mm:ss')}` : ''}
                  </Text>
                </div>
                <Button
                  icon={<ReloadOutlined />}
                  loading={refreshingToday}
                  onClick={() => void fetchToday()}
                >
                  立即刷新
                </Button>
              </div>
              {refreshError && (
                <Alert
                  type="error"
                  showIcon
                  message="教师就餐记录刷新失败"
                  description={refreshError}
                  style={{ marginBottom: 12 }}
                />
              )}
              <div className="meal-report-stat-grid">
                <Card className="meal-report-stat-card"><Statistic title="总就餐人数" value={summary.totalCount || groupedTotal} suffix="人" /></Card>
                <Card className="meal-report-stat-card"><Statistic title="后续追加就餐" value={summary.lateAddedCount || 0} suffix="人" /></Card>
                <Card className="meal-report-stat-card"><Statistic title="未上报教师" value={summary.unreportedTeachers?.length || 0} suffix="位" /></Card>
              </div>
              {summary?.parentStats && (
                <Card title="家长自主选餐" style={{ marginTop: 12, marginBottom: 16, borderRadius: 10 }}>
                  <Row gutter={16}>
                    <Col span={8}>
                      <Statistic title="选择用餐" value={summary.parentStats.eating} valueStyle={{ color: '#27a644' }} />
                    </Col>
                    <Col span={8}>
                      <Statistic title="选择不用餐" value={summary.parentStats.notEating} valueStyle={{ color: '#9a8e7a' }} />
                    </Col>
                    <Col span={8}>
                      <Statistic title="未选择" value={summary.parentStats.unselected} valueStyle={{ color: '#f5a623' }} />
                    </Col>
                  </Row>
                </Card>
              )}
              <div className="meal-report-section-heading">
                <div>
                  <Text strong>按班级分组</Text>
                  <Text type="secondary"> 展开查看具体学员与份数</Text>
                </div>
              </div>
              <div className="meal-report-group-list">
                {groupedMealDetails.map((group) => {
                  const expanded = expandedGroups.has(group.groupName)
                  return (
                    <section className="meal-report-class-group" key={group.groupName}>
                      <button
                        type="button"
                        className="meal-report-class-trigger"
                        aria-expanded={expanded}
                        onClick={() => setExpandedGroups((current) => {
                          const next = new Set(current)
                          if (next.has(group.groupName)) next.delete(group.groupName)
                          else next.add(group.groupName)
                          return next
                        })}
                      >
                        <span><strong>{group.groupName}</strong><small>{group.details.length} 人就餐</small></span>
                        {expanded ? <UpOutlined /> : <DownOutlined />}
                      </button>
                      {expanded && (
                        <div className="meal-report-class-details">
                          {group.details.map((detail) => (
                            <div key={`${group.groupName}-${detail.studentId}`}>
                              <span>{detail.studentName}{detail.appended ? <Tag color="green" style={{ marginLeft: 6 }}>后续追加</Tag> : null}</span>
                              <span>{detail.portion === 'double' ? '双份' : '单份'} · {detail.teacherName}</span>
                            </div>
                          ))}
                        </div>
                      )}
                    </section>
                  )
                })}
                {!groupedMealDetails.length && <Card><Text type="secondary">今日暂无教师上报明细</Text></Card>}
              </div>
              <div className="meal-report-total-row"><span>今日总计</span><strong>{groupedTotal} 人</strong></div>
              <button type="button" className="meal-report-unreported" onClick={() => setShowUnreported((value) => !value)}>
                <span>还有 {summary.unreportedTeachers?.length || 0} 位教师未上报</span>
                {showUnreported ? <UpOutlined /> : <DownOutlined />}
              </button>
              {showUnreported && !!summary.unreportedTeachers?.length && (
                <div className="meal-report-unreported-list">
                  {summary.unreportedTeachers.map((teacher, index) => (
                    <Tag key={teacher.id || `${teacher.name}-${index}`}>{teacher.name || '未命名教师'}{teacher.groupName ? ` · ${teacher.groupName}` : ''}</Tag>
                  ))}
                </div>
              )}
              <Button className="meal-report-export" type="primary" icon={<DownloadOutlined />} onClick={exportToday}>导出 CSV</Button>
            </>
          ),
        },
        {
          key: 'history',
          label: '历史记录',
          children: (
            <>
              <DatePicker picker="week" value={historyWeek} onChange={(value) => value && setHistoryWeek(mondayOf(value))} style={{ marginBottom: 12 }} />
              <Table
                rowKey="id"
                dataSource={historyReports}
                columns={[
                  ...reportColumns,
                  { title: '上报日期', dataIndex: 'reportDate', key: 'reportDate', render: (value: string) => dayjs(value).format('YYYY-MM-DD') },
                  { title: '明细', key: 'details', render: (_value: unknown, report: MealReport) => <Tag>{report.details?.length || 0} 名学员</Tag> },
                ]}
                scroll={isMobile ? { x: 680 } : undefined}
              />
            </>
          ),
        },
      ]} />

      <BrandModal title="设置周期菜单" open={!!templateEditing} onCancel={() => setTemplateEditing(null)} onOk={saveTemplate} confirmLoading={saving} width={isMobile ? 340 : 480}>
        <Form form={templateForm} layout="vertical">
          <Form.Item name="lunch" label="午餐菜品（如：红烧肉）" rules={[{ required: true, message: '请填写午餐' }]}>
            <Input placeholder="填写今日菜品" />
          </Form.Item>

          {/* 菜品照片上传 */}
          <Form.Item name="imageUrl" label="菜品照片（家长端可查看）">
            <MealImageUpload />
          </Form.Item>

          {/* 菜品详细介绍 */}
          <Form.Item name="description" label="菜品详细介绍">
            <Input.TextArea
              rows={3}
              placeholder="可填写食材搭配、营养说明，例如：新鲜五花肉搭配土豆，荤素均衡，主食米饭管够"
            />
          </Form.Item>

          <Form.Item name="allowDouble" label="是否允许双倍米饭" valuePropName="checked">
            <Switch checkedChildren="允许" unCheckedChildren="不允许" />
          </Form.Item>
          <Form.Item name="note" label="备注">
            <Input.TextArea rows={2} placeholder="可选备注" />
          </Form.Item>
          <Form.Item name="dateRange" label="生效日期（可选，留空则一直生效）">
            <DatePicker.RangePicker style={{ width: '100%' }} />
          </Form.Item>
        </Form>
      </BrandModal>
    </PageLayout>
  )
}

'use client'

import { useEffect, useState } from 'react'
import useSWR from 'swr'
import { useRouter, useSearchParams } from 'next/navigation'
import {
  Avatar,
  Button,
  Card,
  Col,
  Drawer,
  Empty,
  Input,
  Pagination,
  Radio,
  Row,
  Segmented,
  Space,
  Spin,
  Tag,
  Typography,
  message,
} from 'antd'
import {
  AlertOutlined,
  CheckCircleOutlined,
  ClockCircleOutlined,
  CommentOutlined,
  EditOutlined,
  ReloadOutlined,
  UserOutlined,
} from '@ant-design/icons'
import { PageLayout } from '@/components/Layout/PageLayout'
import { useIsMobile } from '@/hooks/useIsMobile'
import { useDivision } from '@/contexts/DivisionContext'

const { Title, Text, Paragraph } = Typography

type ReviewStatus = 'PENDING' | 'IN_PROGRESS' | 'RESOLVED'
type ReviewItem = {
  id: string
  feedbackId: string
  satisfied: boolean
  reason: string | null
  createdAt: string
  reviewStatus: ReviewStatus
  reviewNote: string | null
  reviewedAt: string | null
  reviewedBy: { id: string; name: string } | null
  parent: { id: string; name: string }
  teacher: { id: string; name: string }
  studentNames: string[]
  courseName: string | null
  className: string | null
  subject: string
  lessonDate: string
  lessonStartTime: string | null
}
type ReviewList = {
  items: ReviewItem[]
  total: number
  page: number
  pageSize: number
  statusCounts: Record<ReviewStatus, number>
}

const fetcher = async (url: string): Promise<ReviewList> => {
  const response = await fetch(url, { cache: 'no-store' })
  const payload = await response.json().catch(() => ({}))
  if (!response.ok) throw new Error(payload.error || '家长评价加载失败')
  return payload
}

function statusLabel(status: ReviewStatus, satisfied: boolean) {
  if (status === 'PENDING') return satisfied ? '待记录奖励' : '待跟进'
  if (status === 'IN_PROGRESS') return satisfied ? '奖励评估中' : '跟进中'
  return satisfied ? '奖励已记录' : '已跟进'
}

function formatDate(value: string) {
  return new Date(value).toLocaleString('zh-CN', {
    year: 'numeric',
    month: 'numeric',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  })
}

export default function ParentFeedbackReviewsPage() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const isMobile = useIsMobile() ?? false
  const { division } = useDivision()
  const requestedEvaluationId = searchParams.get('evaluationId') || ''
  const [statusFilter, setStatusFilter] = useState('PENDING')
  const [ratingFilter, setRatingFilter] = useState('ALL')
  const [page, setPage] = useState(1)
  const [selected, setSelected] = useState<ReviewItem | null>(null)
  const [reviewStatus, setReviewStatus] = useState<ReviewStatus>('PENDING')
  const [reviewNote, setReviewNote] = useState('')
  const [saving, setSaving] = useState(false)

  const params = new URLSearchParams({
    division,
    status: requestedEvaluationId ? 'ALL' : statusFilter,
    rating: ratingFilter,
    page: String(page),
  })
  if (requestedEvaluationId) params.set('evaluationId', requestedEvaluationId)

  const { data, error, isLoading, mutate } = useSWR<ReviewList>(
    `/api/admin/parent-feedback-reviews?${params.toString()}`,
    fetcher,
    { refreshInterval: 5000, revalidateOnFocus: true, revalidateOnReconnect: true },
  )

  useEffect(() => {
    if (!requestedEvaluationId || !data?.items) return
    const requested = data.items.find((item) => item.id === requestedEvaluationId)
    if (requested) setSelected(requested)
  }, [data, requestedEvaluationId])

  useEffect(() => {
    if (!selected) return
    setReviewStatus(selected.reviewStatus)
    setReviewNote(selected.reviewNote || '')
  }, [selected])

  const closeDetail = () => {
    setSelected(null)
    if (requestedEvaluationId) router.replace('/parent-feedback-reviews', { scroll: false })
  }

  const saveFollowup = async () => {
    if (!selected) return
    if (reviewStatus === 'RESOLVED' && reviewNote.trim().length < 5) {
      message.error('标记已完成前，请至少记录 5 个字的处理结果')
      return
    }
    setSaving(true)
    try {
      const response = await fetch(
        `/api/admin/parent-feedback-reviews/${encodeURIComponent(selected.id)}?division=${encodeURIComponent(division)}`,
        {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ reviewStatus, reviewNote }),
        },
      )
      const payload = await response.json().catch(() => ({}))
      if (!response.ok) throw new Error(payload.error || '保存跟进记录失败')
      const updated = payload.item as Pick<
        ReviewItem,
        'id' | 'reviewStatus' | 'reviewNote' | 'reviewedAt' | 'reviewedBy'
      >
      setSelected((current) => (current ? { ...current, ...updated } : current))
      await mutate()
      message.success('跟进状态已保存')
    } catch (saveError) {
      message.error(saveError instanceof Error ? saveError.message : '保存跟进记录失败')
    } finally {
      setSaving(false)
    }
  }

  const statusCounts = data?.statusCounts || { PENDING: 0, IN_PROGRESS: 0, RESOLVED: 0 }
  const selectedRating = selected?.satisfied ? '满意' : '不满意'

  return (
    <PageLayout
      title="家长教学评价"
      subtitle="家长提交的教学评价与跟进台账，支持记录跟进沟通与奖励评估"
      actions={
        <Button icon={<ReloadOutlined />} onClick={() => void mutate()} loading={isLoading}>
          刷新
        </Button>
      }
    >
      <div style={{ width: '100%', maxWidth: 1000, margin: '0 auto', paddingBottom: 24 }}>
        {/* 3 KPI Overview Cards: Equal 3 Columns on both Mobile and Desktop */}
        <Row gutter={[10, 10]} style={{ marginBottom: 14 }}>
          <Col xs={8} sm={8}>
            <Card
              className="pressable"
              bordered={false}
              style={{
                borderRadius: 12,
                border: statusFilter === 'PENDING' ? '2px solid #E8784A' : '1px solid #EEE7E1',
                background: '#FFF9F5',
                cursor: 'pointer',
                textAlign: 'center',
              }}
              styles={{ body: { padding: isMobile ? '10px 4px' : '12px 14px' } }}
              onClick={() => {
                setStatusFilter(statusFilter === 'PENDING' ? 'ALL' : 'PENDING')
                setPage(1)
              }}
            >
              <div
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  gap: 4,
                  fontSize: 12,
                  color: '#8D806F',
                }}
              >
                <AlertOutlined style={{ color: '#E8784A', fontSize: 13 }} />
                <span>待跟进</span>
              </div>
              <div
                style={{
                  fontSize: isMobile ? 22 : 26,
                  fontWeight: 800,
                  color: '#E8784A',
                  marginTop: 2,
                }}
              >
                {statusCounts.PENDING}
              </div>
            </Card>
          </Col>

          <Col xs={8} sm={8}>
            <Card
              className="pressable"
              bordered={false}
              style={{
                borderRadius: 12,
                border: statusFilter === 'IN_PROGRESS' ? '2px solid #2563EB' : '1px solid #EEE7E1',
                background: '#EFF6FF',
                cursor: 'pointer',
                textAlign: 'center',
              }}
              styles={{ body: { padding: isMobile ? '10px 4px' : '12px 14px' } }}
              onClick={() => {
                setStatusFilter(statusFilter === 'IN_PROGRESS' ? 'ALL' : 'IN_PROGRESS')
                setPage(1)
              }}
            >
              <div
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  gap: 4,
                  fontSize: 12,
                  color: '#8D806F',
                }}
              >
                <ClockCircleOutlined style={{ color: '#2563EB', fontSize: 13 }} />
                <span>处理中</span>
              </div>
              <div
                style={{
                  fontSize: isMobile ? 22 : 26,
                  fontWeight: 800,
                  color: '#2563EB',
                  marginTop: 2,
                }}
              >
                {statusCounts.IN_PROGRESS}
              </div>
            </Card>
          </Col>

          <Col xs={8} sm={8}>
            <Card
              className="pressable"
              bordered={false}
              style={{
                borderRadius: 12,
                border: statusFilter === 'RESOLVED' ? '2px solid #27A644' : '1px solid #EEE7E1',
                background: '#F0FDF4',
                cursor: 'pointer',
                textAlign: 'center',
              }}
              styles={{ body: { padding: isMobile ? '10px 4px' : '12px 14px' } }}
              onClick={() => {
                setStatusFilter(statusFilter === 'RESOLVED' ? 'ALL' : 'RESOLVED')
                setPage(1)
              }}
            >
              <div
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  gap: 4,
                  fontSize: 12,
                  color: '#8D806F',
                }}
              >
                <CheckCircleOutlined style={{ color: '#27A644', fontSize: 13 }} />
                <span>已完成</span>
              </div>
              <div
                style={{
                  fontSize: isMobile ? 22 : 26,
                  fontWeight: 800,
                  color: '#27A644',
                  marginTop: 2,
                }}
              >
                {statusCounts.RESOLVED}
              </div>
            </Card>
          </Col>
        </Row>

        {/* Filter Controls: Non-truncating concise Segmented */}
        <Card
          bordered={false}
          style={{ borderRadius: 12, border: '1px solid #EEE7E1', marginBottom: 14 }}
          styles={{ body: { padding: isMobile ? '10px 10px' : '12px 14px' } }}
        >
          <div
            style={{
              display: 'flex',
              flexDirection: isMobile ? 'column' : 'row',
              gap: 10,
              alignItems: isMobile ? 'stretch' : 'center',
              justifyContent: 'space-between',
            }}
          >
            <Segmented
              aria-label="跟进状态筛选"
              size="middle"
              value={statusFilter}
              onChange={(value) => {
                setStatusFilter(String(value))
                setPage(1)
              }}
              block={isMobile}
              options={[
                { value: 'PENDING', label: '待跟进' },
                { value: 'IN_PROGRESS', label: '处理中' },
                { value: 'RESOLVED', label: '已完成' },
                { value: 'ALL', label: '全部状态' },
              ]}
            />

            <Segmented
              aria-label="评价结果筛选"
              size="middle"
              value={ratingFilter}
              onChange={(value) => {
                setRatingFilter(String(value))
                setPage(1)
              }}
              block={isMobile}
              options={[
                { value: 'ALL', label: '全部' },
                { value: 'UNSATISFIED', label: '不满意' },
                { value: 'SATISFIED', label: '满意' },
              ]}
            />
          </div>
        </Card>

        {error && (
          <div
            role="alert"
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 8,
              minHeight: 36,
              marginBottom: 12,
            }}
          >
            <Text type="secondary">
              {data ? '刷新失败，当前显示上次结果' : '评价暂时无法加载'}
            </Text>
            <Button
              type="link"
              size="small"
              onClick={() => void mutate()}
              loading={isLoading}
              style={{ paddingInline: 4 }}
            >
              重试
            </Button>
          </div>
        )}

        {isLoading && !data && !error ? (
          <div style={{ display: 'grid', placeItems: 'center', padding: 48 }}>
            <Spin />
          </div>
        ) : null}

        {!isLoading && !error && data?.items.length === 0 && (
          <Card style={{ borderRadius: 14, border: '1px solid #EEE7E1' }}>
            <Empty
              description={
                statusFilter === 'PENDING' && ratingFilter !== 'SATISFIED'
                  ? '目前没有待跟进评价'
                  : '暂无符合条件的家长评价'
              }
            />
          </Card>
        )}

        {/* Evaluation Card List */}
        <div style={{ display: 'grid', gap: 12 }}>
          {data?.items.map((item) => {
            // Deduplicate course and class names if identical
            const courseDetails = [
              item.courseName && item.className && item.courseName === item.className
                ? item.courseName
                : [item.courseName, item.className].filter(Boolean).join(' · '),
              item.subject,
              item.parent.name ? `家长：${item.parent.name}` : null,
            ]
              .filter(Boolean)
              .join(' · ')

            return (
              <Card
                key={item.id}
                style={{
                  borderRadius: 14,
                  border: '1px solid #EEE7E1',
                  boxShadow: '0 2px 8px rgba(0,0,0,0.02)',
                }}
                styles={{ body: { padding: isMobile ? 12 : 16 } }}
              >
                {/* Header row: tags, teacher, student, time */}
                <div
                  style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'flex-start',
                    gap: 8,
                    marginBottom: 8,
                  }}
                >
                  <Space size={8}>
                    <Avatar
                      icon={<UserOutlined />}
                      size={isMobile ? 36 : 40}
                      style={{
                        backgroundColor: item.satisfied ? '#E8F5E9' : '#FFF3E0',
                        color: item.satisfied ? '#2E7D32' : '#E65100',
                        fontWeight: 700,
                        flexShrink: 0,
                      }}
                    />
                    <div>
                      <div style={{ fontWeight: 700, fontSize: 16, color: '#1F2329' }}>
                        {item.teacher.name} · {item.studentNames.join('、') || '学员'}
                      </div>
                      <div style={{ fontSize: 12, color: '#8D806F', marginTop: 1 }}>
                        {formatDate(item.createdAt)}
                      </div>
                    </div>
                  </Space>

                  <Space size={4}>
                    <Tag
                      color={item.satisfied ? 'success' : 'error'}
                      style={{ borderRadius: 6, margin: 0, fontWeight: 600 }}
                    >
                      {item.satisfied ? '满意' : '不满意'}
                    </Tag>
                    <Tag
                      color={
                        item.reviewStatus === 'RESOLVED'
                          ? 'success'
                          : item.reviewStatus === 'IN_PROGRESS'
                            ? 'processing'
                            : 'warning'
                      }
                      style={{ borderRadius: 6, margin: 0 }}
                    >
                      {statusLabel(item.reviewStatus, item.satisfied)}
                    </Tag>
                  </Space>
                </div>

                {/* Course & parent context */}
                {courseDetails && (
                  <div
                    style={{
                      fontSize: 12,
                      color: '#8D806F',
                      marginBottom: 10,
                      paddingLeft: isMobile ? 0 : 48,
                    }}
                  >
                    {courseDetails}
                  </div>
                )}

                {/* Parent's written feedback reason box */}
                <div
                  style={{
                    marginLeft: isMobile ? 0 : 48,
                    padding: '10px 12px',
                    borderRadius: 10,
                    background: item.satisfied ? '#F6FAF7' : '#FFF9F5',
                    border: item.satisfied ? '1px solid #D1E7DD' : '1px solid #FFE4D6',
                    marginBottom: 10,
                  }}
                >
                  <div
                    style={{
                      fontSize: 12,
                      color: item.satisfied ? '#2E7D32' : '#C2410C',
                      fontWeight: 600,
                      marginBottom: 4,
                      display: 'flex',
                      alignItems: 'center',
                      gap: 4,
                    }}
                  >
                    <CommentOutlined />
                    <span>{item.satisfied ? '家长评价反馈' : '家长具体说明'}</span>
                  </div>
                  <Paragraph
                    style={{
                      margin: 0,
                      color: '#1F2329',
                      fontSize: 14,
                      lineHeight: 1.6,
                      whiteSpace: 'pre-wrap',
                    }}
                  >
                    {item.reason || (item.satisfied ? '家长认可本节课教学效果。' : '未填写具体原因。')}
                  </Paragraph>
                </div>

                {/* Admin/Staff follow-up record if exists */}
                {item.reviewNote && (
                  <div
                    style={{
                      marginLeft: isMobile ? 0 : 48,
                      padding: '8px 12px',
                      borderRadius: 8,
                      background: '#F0F9FF',
                      border: '1px solid #BAE6FD',
                      marginBottom: 10,
                      fontSize: 13,
                      color: '#0369A1',
                    }}
                  >
                    <span style={{ fontWeight: 600 }}>跟进记录：</span>
                    {item.reviewNote}
                  </div>
                )}

                {/* Action button */}
                <div
                  style={{
                    display: 'flex',
                    justifyContent: 'flex-end',
                    marginTop: 6,
                  }}
                >
                  <Button
                    type="primary"
                    icon={<EditOutlined />}
                    onClick={() => setSelected(item)}
                    style={{
                      borderRadius: 8,
                      background: 'var(--color-primary, #14574D)',
                      borderColor: 'var(--color-primary, #14574D)',
                      height: 36,
                      fontSize: 14,
                    }}
                  >
                    查看并跟进
                  </Button>
                </div>
              </Card>
            )
          })}
        </div>

        {!!data?.total && !requestedEvaluationId && (
          <div style={{ display: 'flex', justifyContent: 'center', marginTop: 18 }}>
            <Pagination
              current={page}
              pageSize={data.pageSize}
              total={data.total}
              onChange={setPage}
              showSizeChanger={false}
            />
          </div>
        )}
      </div>

      {/* Follow-up Drawer */}
      <Drawer
        open={Boolean(selected)}
        onClose={closeDetail}
        title={selected ? `${selectedRating}评价 · ${selected.teacher.name}` : '家长教学评价'}
        width={isMobile ? '100%' : 540}
        destroyOnClose
      >
        {selected && (
          <div style={{ display: 'grid', gap: 16 }}>
            <Space wrap>
              <Tag color={selected.satisfied ? 'success' : 'error'}>{selectedRating}</Tag>
              <Text type="secondary">
                {formatDate(selected.lessonDate)}
                {selected.lessonStartTime ? ` · ${selected.lessonStartTime}` : ''}
              </Text>
            </Space>

            <Card size="small" style={{ borderRadius: 10, background: '#FAF8F5' }}>
              <Text strong style={{ display: 'block', marginBottom: 4 }}>
                课堂基本信息
              </Text>
              <Paragraph style={{ margin: '0 0 4px', fontSize: 13 }}>
                {[
                  selected.teacher.name,
                  selected.studentNames.join('、') || '学员信息不可用',
                  selected.courseName,
                  selected.className,
                  selected.subject,
                ]
                  .filter(Boolean)
                  .join(' · ')}
              </Paragraph>
              <Text type="secondary" style={{ fontSize: 12 }}>
                家长姓名：{selected.parent.name}
              </Text>
            </Card>

            <div>
              <Text strong style={{ display: 'block', marginBottom: 6 }}>
                {selected.satisfied ? '家长认可' : '家长具体说明'}
              </Text>
              <div
                style={{
                  padding: '10px 12px',
                  borderRadius: 10,
                  background: selected.satisfied ? '#F6FAF7' : '#FFF9F5',
                  border: selected.satisfied ? '1px solid #D1E7DD' : '1px solid #FFE4D6',
                  whiteSpace: 'pre-wrap',
                  lineHeight: 1.6,
                }}
              >
                {selected.reason || '家长认可本节课的教学内容。'}
              </div>
            </div>

            <div>
              <Text strong style={{ display: 'block', marginBottom: 6 }}>
                管理跟进处理
              </Text>
              <Radio.Group
                aria-label="管理跟进状态"
                size="middle"
                value={reviewStatus}
                onChange={(event) => setReviewStatus(event.target.value as ReviewStatus)}
                optionType="button"
                buttonStyle="solid"
                style={{ display: 'flex', flexWrap: 'wrap', marginBottom: 10 }}
                options={[
                  { value: 'PENDING', label: selected.satisfied ? '待记录奖励' : '待跟进' },
                  { value: 'IN_PROGRESS', label: selected.satisfied ? '奖励评估中' : '跟进中' },
                  { value: 'RESOLVED', label: selected.satisfied ? '奖励已记录' : '已跟进' },
                ]}
              />
              <Input.TextArea
                value={reviewNote}
                onChange={(event) => setReviewNote(event.target.value)}
                placeholder={
                  selected.satisfied
                    ? '记录奖励评估或表扬处理情况...'
                    : '记录与家长沟通结果、教学改进方案或后续复查情况...'
                }
                maxLength={1000}
                showCount
                rows={4}
                style={{ borderRadius: 8 }}
              />
              {selected.reviewedBy && selected.reviewedAt && (
                <Text type="secondary" style={{ display: 'block', marginTop: 6, fontSize: 12 }}>
                  最近更新：{selected.reviewedBy.name} · {formatDate(selected.reviewedAt)}
                </Text>
              )}
            </div>

            <Button
              type="primary"
              loading={saving}
              onClick={() => void saveFollowup()}
              style={{
                height: 42,
                borderRadius: 8,
                background: 'var(--color-primary, #14574D)',
                borderColor: 'var(--color-primary, #14574D)',
                fontSize: 15,
                fontWeight: 600,
              }}
            >
              保存跟进记录
            </Button>
          </div>
        )}
      </Drawer>
    </PageLayout>
  )
}

'use client'
import { AdaptiveSelect } from '@/components/AdaptiveSelect';

import { useState, useRef, useEffect, useMemo } from 'react'
import { Avatar, Badge, Button, Empty, Input, Segmented, Tag, Typography } from 'antd'
import { BrandModal } from '@/components/Common/BrandModal'
import {
  CheckCircleOutlined, SendOutlined, SearchOutlined, BellOutlined,
  CloseOutlined, PictureOutlined, SmileOutlined, UserOutlined,
} from '@ant-design/icons'
import { toast } from 'sonner'
import { usePausableSWR } from '@/lib/use-pausable-swr'
import { format, formatDistanceToNow } from 'date-fns'
import { zhCN } from 'date-fns/locale'
import { useIsMobile } from '@/hooks/useIsMobile'
import { SUBJECT_COLORS } from '@/constants/subjects'
import { STICKER_MARK, stickerPreview } from '@/constants/stickers'
import { StickerPanel } from '@/components/Parent/StickerPanel'
import { StickerMessageContent } from '@/components/Parent/StickerMessageContent'
import { StudentAvatar } from '@/components/Common/StudentAvatar'
import { getTeacherAvatarUrl } from '@/lib/teacher-avatars'
import { uploadMessageImage } from '@/lib/client-image-upload'

const { Text, Title } = Typography
const { TextArea } = Input
const fetcher = async (url: string) => {
  const response = await fetch(url)
  if (!response.ok) throw new Error(`加载失败（${response.status}）`)
  return response.json()
}

const ADMIN = 'var(--color-brand-purple)'
const PARENT = 'var(--color-primary)'
const TEACHER = 'var(--color-success)'

type Reply = {
  id: string
  authorName: string
  role: string
  content: string
  isReadByTeacher: boolean
  isReadByParent: boolean
  createdAt: string
  attachments?: Array<{ url: string; name?: string; type?: string }> | null
}
type Message = {
  id: string; title: string; subject: string | null; status: string
  parent: { id: string; name: string }
  teacher: { id: string; name: string; avatar?: string | null; gender?: string | null } | null
  student: { id: string; name: string; grade?: string | null; gender?: string | null } | null
  replies: Reply[]; updatedAt: string
  workflow?: {
    pendingTeacherReply: boolean
    pendingParentRead: boolean
    unreadForTeacher: number
    unreadForParent: number
    waitingMinutes: number
    overdue: boolean
    parentMessageViewedByTeacher: boolean
    staffReplyViewedByParent: boolean
    parentFollowUpCount: number
  }
  reminder?: { count: number; lastRemindedAt: string | null }
}

const unreadCount = (m: Message) => m.replies.filter(r => !r.isReadByTeacher && r.role === 'parent').length
const isPendingTeacherReply = (m: Message) => m.workflow?.pendingTeacherReply ?? (
  m.status !== 'CLOSED' && m.replies[m.replies.length - 1]?.role === 'parent'
)
const isPendingParentRead = (m: Message) => m.workflow?.pendingParentRead ?? (
  m.replies.some((reply) => reply.role !== 'parent' && !reply.isReadByParent)
)
const formatWaitingTime = (minutes = 0) => {
  if (minutes < 60) return `等待 ${Math.max(1, minutes)} 分钟`
  if (minutes < 24 * 60) return `等待 ${Math.floor(minutes / 60)} 小时`
  return `等待 ${Math.floor(minutes / 1440)} 天`
}

function ChatBubble({ reply }: { reply: Reply }) {
  const isParent = reply.role === 'parent'
  const color = reply.role === 'parent' ? PARENT : reply.role === 'teacher' ? TEACHER : ADMIN
  const roleLabel = reply.role === 'admin' ? '管理员' : reply.role === 'teacher' ? '老师' : '家长'
  return (
    <div style={{ display: 'flex', flexDirection: isParent ? 'row' : 'row-reverse', gap: 8, alignItems: 'flex-end', marginBottom: 16 }}>
      <Avatar size={30} icon={<UserOutlined />} style={{ flexShrink: 0, background: color, color: 'var(--color-on-primary)' }} />
      <div style={{ maxWidth: '72%' }}>
        <div style={{ fontSize: 11, color: 'var(--color-ink-subtle)', marginBottom: 4, textAlign: isParent ? 'left' : 'right' }}>
          {reply.authorName}（{roleLabel}） · {format(new Date(reply.createdAt), 'MM-dd HH:mm')}
        </div>
        <div style={{
          background: isParent ? 'var(--color-surface-1)' : color,
          color: isParent ? 'var(--color-ink)' : 'var(--color-on-primary)',
          border: isParent ? '1px solid rgba(0,0,0,.08)' : 'none',
          borderRadius: isParent ? '4px 16px 16px 16px' : '16px 4px 16px 16px',
          padding: '10px 14px', fontSize: 14, lineHeight: 1.6,
          boxShadow: '0 2px 8px rgba(0,0,0,.05)', whiteSpace: 'pre-wrap', wordBreak: 'break-word',
        }}>
          <StickerMessageContent
            content={reply.content}
            animated
            style={{ width: 150, maxWidth: '100%', borderRadius: 12 }}
          />
          {reply.attachments?.length ? (
            <div style={{ display: 'grid', gap: 6, marginTop: reply.content ? 8 : 0 }}>
              {reply.attachments.map((attachment, index) => (
                <a key={`${attachment.url}-${index}`} href={attachment.url} target="_blank" rel="noreferrer" aria-label="打开聊天图片">
                  <img
                    src={attachment.url}
                    alt={attachment.name || '聊天图片'}
                    loading="lazy"
                    style={{ display: 'block', width: '100%', maxWidth: 280, maxHeight: 240, objectFit: 'cover', borderRadius: 10 }}
                  />
                </a>
              ))}
            </div>
          ) : null}
        </div>
        <div style={{
          marginTop: 4,
          fontSize: 10,
          color: 'var(--color-ink-subtle)',
          textAlign: isParent ? 'left' : 'right',
        }}>
          {isParent
            ? (reply.isReadByTeacher ? '教师已查看' : '教师未查看')
            : (reply.isReadByParent ? '家长已查看' : '家长未查看')}
        </div>
      </div>
    </div>
  )
}

function ConversationItem({ msg, onClick, active }: { msg: Message; onClick: () => void; active: boolean }) {
  const unread = unreadCount(msg)
  const last = msg.replies[msg.replies.length - 1]
  const sc = msg.subject ? SUBJECT_COLORS[msg.subject] : null
  const studentName = msg.student?.name || '学员信息待完善'
  const pendingTeacher = isPendingTeacherReply(msg)
  const pendingParent = isPendingParentRead(msg)
  return (
    <button type="button" aria-pressed={active} onClick={onClick} style={{
      display: 'flex', width: '100%', minWidth: 0, minHeight: 158, gap: 14, alignItems: 'flex-start',
      textAlign: 'left', color: 'var(--color-ink)', font: 'inherit',
      background: active ? 'var(--color-primary-bg)' : 'var(--color-surface-1)',
      border: `1px solid ${active ? 'rgba(232,120,74,.35)' : 'var(--color-hairline)'}`,
      borderRadius: 16, padding: 16, cursor: 'pointer',
      boxShadow: active ? '0 8px 22px rgba(119,67,40,.10)' : '0 3px 12px rgba(37,29,20,.045)',
      transition: 'background .16s ease, box-shadow .16s ease, transform .16s ease',
    }}>
      <div style={{ position: 'relative', flexShrink: 0, paddingTop: 2 }}>
        <StudentAvatar photoUrl={null} gender={msg.student?.gender} name={studentName} size={56} />
        {unread > 0 && (
          <span style={{
            position: 'absolute', right: -5, top: -5, minWidth: 20, height: 20, padding: '0 5px',
            display: 'grid', placeItems: 'center', borderRadius: 999, border: '2px solid var(--color-surface-1)',
            background: 'var(--color-error)', color: 'var(--color-on-primary)', fontSize: 10, fontWeight: 700,
          }}>{unread}</span>
        )}
      </div>
      <div style={{ minWidth: 0, flex: 1 }}>
        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 8 }}>
          <div style={{ minWidth: 0, flex: 1 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 7, flexWrap: 'wrap' }}>
              <Text strong style={{ fontSize: 15, color: 'var(--color-ink)' }} ellipsis>{studentName}</Text>
              {msg.student?.grade && (
                <span style={{ padding: '2px 7px', borderRadius: 999, background: 'var(--color-surface-3)', color: 'var(--color-ink-muted)', fontSize: 10, lineHeight: 1.5 }}>
                  {msg.student.grade}
                </span>
              )}
            </div>
            <div style={{ color: 'var(--color-ink-muted)', fontSize: 12, marginTop: 3 }}>
              {msg.parent.name} · 家长
            </div>
          </div>
          <span style={{ color: 'var(--color-ink-subtle)', fontSize: 11, whiteSpace: 'nowrap', flexShrink: 0 }}>
            {formatDistanceToNow(new Date(msg.updatedAt), { addSuffix: true, locale: zhCN })}
          </span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 7, flexWrap: 'wrap', marginTop: 11 }}>
          {pendingTeacher && msg.status !== 'CLOSED' && (
            <span style={{ padding: '3px 8px', borderRadius: 999, background: msg.workflow?.overdue ? 'var(--color-error-bg)' : 'var(--color-primary-bg)', color: msg.workflow?.overdue ? 'var(--color-error)' : 'var(--color-primary-focus)', fontSize: 10, fontWeight: 650 }}>
              {msg.workflow?.overdue ? '回复超时' : formatWaitingTime(msg.workflow?.waitingMinutes)}
            </span>
          )}
          {pendingParent && msg.status !== 'CLOSED' && (
            <span style={{ padding: '3px 8px', borderRadius: 999, background: 'var(--color-success-bg)', color: 'var(--color-success)', fontSize: 10, fontWeight: 650 }}>待家长查看</span>
          )}
          {msg.status === 'CLOSED' && (
            <span style={{ padding: '3px 8px', borderRadius: 999, background: 'var(--color-surface-3)', color: 'var(--color-ink-muted)', fontSize: 10 }}>已关闭</span>
          )}
          {msg.subject && sc && (
            <span style={{ padding: '3px 8px', borderRadius: 999, background: sc.bg, color: sc.color, fontSize: 10, fontWeight: 650 }}>{msg.subject}</span>
          )}
          {!!msg.reminder?.count && (
            <span style={{ padding: '3px 8px', borderRadius: 999, background: 'var(--color-surface-3)', color: ADMIN, fontSize: 10 }}>已督促 {msg.reminder.count} 次</span>
          )}
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 7, marginTop: 11, minWidth: 0 }}>
          <Avatar
            size={25}
            src={msg.teacher ? getTeacherAvatarUrl(msg.teacher.avatar, msg.teacher.gender, msg.teacher.id) : undefined}
            style={{ background: 'var(--color-surface-3)', color: 'var(--color-ink-muted)', flexShrink: 0, fontSize: 11 }}
          />
          <span style={{ color: 'var(--color-ink-caption)', fontSize: 12, whiteSpace: 'nowrap' }}>沟通老师</span>
          <Text strong style={{ color: 'var(--color-ink)', fontSize: 12 }} ellipsis>{msg.teacher ? `${msg.teacher.name}老师` : '待分配'}</Text>
        </div>
        <div style={{ marginTop: 9, paddingTop: 9, borderTop: '1px solid var(--color-hairline-tertiary)', minWidth: 0 }}>
          <Text style={{ color: 'var(--color-ink-muted)', fontSize: 12 }} ellipsis>
            {last ? `${last.authorName}：${stickerPreview(last.content)}` : msg.title}
          </Text>
        </div>
      </div>
    </button>
  )
}

export function AdminMessagesClient({ embedded = false }: { embedded?: boolean } = {}) {
  const isMobile = useIsMobile() ?? false
  const [activeId, setActiveId] = useState<string | null>(null)
  const [filter, setFilter] = useState<'ALL' | 'PENDING_TEACHER' | 'PENDING_PARENT' | 'CLOSED'>('ALL')
  const [teacherFilter, setTeacherFilter] = useState('')
  const [search, setSearch] = useState('')
  const [replyText, setReplyText] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [closing, setClosing] = useState(false)
  const [reminding, setReminding] = useState(false)
  const [showSticker, setShowSticker] = useState(false)
  const [showEmoji, setShowEmoji] = useState(false)
  const [pendingImage, setPendingImage] = useState<string | null>(null)
  const [uploading, setUploading] = useState(false)
  const bottomRef = useRef<HTMLDivElement>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const { data, mutate } = usePausableSWR('/api/messages', fetcher, {
    refreshInterval: 5_000, revalidateOnFocus: true, revalidateOnReconnect: true,
  })
  const { data: workflowSummary, mutate: mutateWorkflowSummary } = usePausableSWR(
    '/api/messages/unread-count',
    fetcher,
    { refreshInterval: 30_000, revalidateOnFocus: true, revalidateOnReconnect: true },
  )
  const allMessages = useMemo<Message[]>(() => data?.messages || [], [data])

  const teacherOptions = useMemo(() => {
    const map = new Map<string, string>()
    allMessages.forEach(m => { if (m.teacher) map.set(m.teacher.id, m.teacher.name) })
    return Array.from(map.entries()).map(([value, label]) => ({ value, label }))
  }, [allMessages])

  const stats = useMemo(() => ({
    total: Number(data?.total ?? allMessages.length),
    pendingTeacher: Number(
      workflowSummary?.pendingTeacherReplies
      ?? allMessages.filter(isPendingTeacherReply).length,
    ),
    pendingParent: Number(
      workflowSummary?.pendingParentReads
      ?? allMessages.filter(isPendingParentRead).length,
    ),
    overdue: Number(
      workflowSummary?.overdueTeacherReplies
      ?? allMessages.filter(message => message.workflow?.overdue).length,
    ),
  }), [allMessages, data?.total, workflowSummary])

  const serviceMetrics = useMemo(() => {
    const responseMinutes: number[] = []
    let parentFollowUps = 0
    const pendingByTeacher = new Map<string, { name: string; count: number }>()

    allMessages.forEach((message) => {
      parentFollowUps += message.workflow?.parentFollowUpCount || 0
      if (isPendingTeacherReply(message) && message.teacher) {
        const current = pendingByTeacher.get(message.teacher.id)
        pendingByTeacher.set(message.teacher.id, {
          name: message.teacher.name,
          count: (current?.count || 0) + 1,
        })
      }
      message.replies.forEach((reply, index) => {
        if (reply.role !== 'parent') return
        const replyAt = new Date(reply.createdAt).getTime()
        const staffReply = message.replies
          .slice(index + 1)
          .find(candidate => candidate.role === 'teacher')
        if (staffReply) {
          responseMinutes.push(Math.max(0, (new Date(staffReply.createdAt).getTime() - replyAt) / 60_000))
        }
      })
    })

    const averageMinutes = responseMinutes.length
      ? Math.round(responseMinutes.reduce((sum, value) => sum + value, 0) / responseMinutes.length)
      : 0
    const within24Hours = responseMinutes.filter(value => value <= 24 * 60).length
    return {
      averageMinutes: Number(workflowSummary?.averageReplyMinutes ?? averageMinutes),
      replyRate24h: Number(workflowSummary?.replyRate24h ?? (
        responseMinutes.length ? Math.round(within24Hours / responseMinutes.length * 100) : 100
      )),
      parentFollowUps: Number(workflowSummary?.parentFollowUps ?? parentFollowUps),
      pendingByTeacher: Array.isArray(workflowSummary?.pendingByTeacher)
        ? workflowSummary.pendingByTeacher
        : [...pendingByTeacher.values()].sort((a, b) => b.count - a.count),
    }
  }, [allMessages, workflowSummary])

  const messages = useMemo(() => {
    const kw = search.trim()
    return allMessages
      .filter(m => (
        filter === 'ALL'
        || (filter === 'PENDING_TEACHER' && isPendingTeacherReply(m))
        || (filter === 'PENDING_PARENT' && isPendingParentRead(m))
        || (filter === 'CLOSED' && m.status === 'CLOSED')
      ))
      .filter(m => !teacherFilter || m.teacher?.id === teacherFilter)
      .filter(m => !kw || `${m.title} ${m.parent.name} ${m.teacher?.name || ''} ${m.student?.name || ''} ${m.subject || ''}`.includes(kw) || m.replies.some(r => r.content.includes(kw)))
      .sort((a, b) => {
        const pa = isPendingTeacherReply(a) ? 1 : 0
        const pb = isPendingTeacherReply(b) ? 1 : 0
        if (pa !== pb) return pb - pa
        return new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()
      })
  }, [allMessages, filter, teacherFilter, search])

  const active = allMessages.find(m => m.id === activeId) || null

  useEffect(() => {
    if (!activeId) return
    const timer = window.setTimeout(() => bottomRef.current?.scrollIntoView({ behavior: 'smooth' }), 100)
    return () => window.clearTimeout(timer)
  }, [activeId, active?.replies.length])

  const handleSelect = async (id: string) => {
    setActiveId(id)
    setShowSticker(false)
    setShowEmoji(false)
    const response = await fetch(`/api/messages/${id}`)
    if (!response.ok) {
      toast.error('会话状态更新失败，请稍后重试')
      return
    }
    mutate()
    void mutateWorkflowSummary()
  }

  const handleUploadImage = async (file: File) => {
    const studentId = active?.student?.id
    if (!studentId) {
      toast.error('当前会话未关联学生，无法上传图片')
      return
    }
    setUploading(true)
    try {
      setPendingImage(await uploadMessageImage(file, studentId))
    } catch (error) {
      toast.error(error instanceof Error ? error.message : '图片上传失败，请稍后重试')
    } finally {
      setUploading(false)
    }
  }

  const handleReply = async (contentOverride?: string) => {
    const content = contentOverride ?? replyText.trim()
    if (!activeId || (!content && !pendingImage)) return
    setSubmitting(true)
    try {
      const res = await fetch(`/api/messages/${activeId}/reply`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          content,
          attachments: pendingImage ? [{ url: pendingImage, type: 'image' }] : [],
        }),
      })
      if (!res.ok) {
        const result = await res.json().catch(() => null)
        toast.error(result?.error || '发送失败，请稍后重试')
        return
      }
      if (contentOverride === undefined) setReplyText('')
      setPendingImage(null)
      setShowEmoji(false)
      setShowSticker(false)
      toast.success('回复已发送，家长端将显示新回复提示')
      void mutate()
      void mutateWorkflowSummary()
    } catch { toast.error('网络错误') } finally { setSubmitting(false) }
  }

  const handleClose = async () => {
    if (!activeId) return
    setClosing(true)
    try {
      const response = await fetch(`/api/messages/${activeId}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'CLOSED' }),
      })
      if (!response.ok) { toast.error('关闭失败，请稍后重试'); return }
      toast.success('已关闭'); void mutate(); void mutateWorkflowSummary()
    } catch { toast.error('操作失败') } finally { setClosing(false) }
  }

  const handleRemindTeacher = async () => {
    if (!activeId) return
    setReminding(true)
    try {
      const res = await fetch(`/api/messages/${activeId}/remind`, { method: 'POST' })
      const result = await res.json()
      if (!res.ok) {
        toast.error(result.error || '提醒失败')
        return
      }
      toast.success(result.reminded ? '已提醒教师及时回复' : result.message)
    } catch {
      toast.error('网络错误，请稍后重试')
    } finally {
      setReminding(false)
    }
  }

  const statCards = (
    <div style={{ display: 'grid', gridTemplateColumns: isMobile ? 'repeat(2,minmax(0,1fr))' : 'repeat(4,minmax(0,1fr))', gap: 10, marginBottom: 12 }}>
      {[
        { label: '全部沟通', value: stats.total, color: 'var(--color-ink)', bg: 'var(--color-surface-1)' },
        { label: '待教师回复', value: stats.pendingTeacher, color: 'var(--color-primary-focus)', bg: 'var(--color-primary-bg)' },
        { label: '待家长查看', value: stats.pendingParent, color: 'var(--color-success)', bg: 'var(--color-success-bg)' },
        { label: '超时未回复', value: stats.overdue, color: 'var(--color-error)', bg: 'var(--color-error-bg)' },
      ].map(c => (
        <div key={c.label} style={{ background: c.bg, borderRadius: 14, padding: '11px 14px', border: '1px solid var(--color-hairline-tertiary)' }}>
          <div style={{ fontSize: 11, color: 'var(--color-ink-muted)', marginBottom: 3 }}>{c.label}</div>
          <div style={{ fontSize: 22, lineHeight: 1.15, fontWeight: 750, color: c.color, fontVariantNumeric: 'tabular-nums' }}>{c.value}</div>
        </div>
      ))}
    </div>
  )

  const servicePanel = (
    <div style={{
      display: 'grid',
      gridTemplateColumns: 'repeat(3,minmax(0,1fr))',
      gap: isMobile ? 8 : 16,
      marginBottom: 16,
      padding: isMobile ? '12px 10px' : '13px 18px',
      borderRadius: 14,
      border: '1px solid var(--color-hairline)',
      background: 'var(--color-surface-1)',
    }}>
      <div>
        <Text style={{ color: 'var(--color-ink-muted)', fontSize: 11 }}>平均回复时间</Text>
        <div style={{ marginTop: 3, fontSize: 16, fontWeight: 750, color: 'var(--color-ink)' }}>
          {formatWaitingTime(serviceMetrics.averageMinutes).replace('等待 ', '')}
        </div>
      </div>
      <div>
        <Text style={{ color: 'var(--color-ink-muted)', fontSize: 11 }}>24小时回复率</Text>
        <div style={{ marginTop: 3, fontSize: 16, fontWeight: 750, color: 'var(--color-success)' }}>
          {serviceMetrics.replyRate24h}%
        </div>
      </div>
      <div>
        <Text style={{ color: 'var(--color-ink-muted)', fontSize: 11 }}>家长重复追问</Text>
        <div style={{ marginTop: 3, fontSize: 16, fontWeight: 750, color: 'var(--color-primary)' }}>
          {serviceMetrics.parentFollowUps} 次
        </div>
      </div>
      {serviceMetrics.pendingByTeacher.length > 0 && (
        <div style={{ gridColumn: '1 / -1', display: 'flex', flexWrap: 'wrap', gap: 6, paddingTop: 4 }}>
          {serviceMetrics.pendingByTeacher.slice(0, 8).map((item: { name: string; count: number }) => (
          <Tag key={item.name} style={{ margin: 0, borderRadius: 9999, border: 0, background: 'var(--color-primary-bg)', color: 'var(--color-warning-text)' }}>
              {item.name}待回复 {item.count}
            </Tag>
          ))}
        </div>
      )}
    </div>
  )

  const filterBar = (
    <div style={{ display: 'grid', gridTemplateColumns: isMobile ? 'repeat(2,minmax(0,1fr))' : 'minmax(220px,1fr) 170px 160px', gap: 8, marginBottom: 10 }}>
      <Input prefix={<SearchOutlined style={{ color: 'var(--color-ink-subtle)' }} />} placeholder="搜索家长/老师/学员/内容"
        value={search} onChange={e => setSearch(e.target.value)} allowClear
        style={{ gridColumn: isMobile ? '1 / -1' : undefined, minWidth: 0, height: 42, borderRadius: 10 }} />
      <AdaptiveSelect allowClear placeholder="按老师" value={teacherFilter || undefined}
        onChange={v => setTeacherFilter(v || '')} options={teacherOptions} style={{ width: '100%', height: 42 }}
        showSearch filterOption={(i, o) => String(o?.label || '').includes(i)} />
      <Segmented
        block
        value={filter}
        onChange={(value) => setFilter(value as typeof filter)}
        style={{ width: '100%', height: 42, gridColumn: isMobile ? '1 / -1' : undefined }}
        options={[
          { value: 'ALL', label: '全部' },
          { value: 'PENDING_TEACHER', label: '待教师回复' },
          { value: 'PENDING_PARENT', label: '待家长查看' },
          { value: 'CLOSED', label: '已关闭' },
        ]}
      />
    </div>
  )

  const conversationList = (
    <div style={{ display: 'grid', gridTemplateColumns: isMobile ? 'minmax(0,1fr)' : 'repeat(2,minmax(0,1fr))', gap: 10 }}>
      {messages.length === 0 ? (
        <div style={{ gridColumn: '1 / -1', background: 'var(--color-surface-1)', border: '1px solid var(--color-hairline)', borderRadius: 16, padding: '36px 16px' }}>
          <Empty description={search || teacherFilter ? '没有匹配的会话' : '暂无留言'} image={Empty.PRESENTED_IMAGE_SIMPLE} />
        </div>
      ) : messages.map(m => (
        <ConversationItem key={m.id} msg={m} active={m.id === activeId} onClick={() => handleSelect(m.id)} />
      ))}
    </div>
  )

  const clearChatState = () => {
    setActiveId(null)
    setShowSticker(false)
    setShowEmoji(false)
    setPendingImage(null)
    setReplyText('')
  }

  const emojiOptions = ['😀', '😄', '😊', '🥰', '😅', '🤔', '👍', '🙏', '❤️', '✨', '🎉', '💪', '📚', '✅', '💡']
  const activeSubjectColor = active?.subject ? SUBJECT_COLORS[active.subject] : null

  const chatPanel = active ? (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0, background: 'var(--color-surface-1)' }}>
      <div style={{
        padding: isMobile ? 'max(12px, env(safe-area-inset-top)) 14px 12px' : '15px 20px',
        borderBottom: '1px solid var(--color-hairline)',
        display: 'flex',
        flexDirection: isMobile ? 'column' : 'row',
        alignItems: isMobile ? 'stretch' : 'center',
        gap: isMobile ? 10 : 11,
        flexShrink: 0,
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 11, minWidth: 0 }}>
        <StudentAvatar photoUrl={null} gender={active.student?.gender} name={active.student?.name || active.parent.name} size={isMobile ? 42 : 48} />
        <div style={{ flex: 1, minWidth: 0 }}>
          <Text strong style={{ display: 'block', fontSize: 15, color: 'var(--color-ink)' }} ellipsis>
            {active.student?.name || active.parent.name}
          </Text>
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap', marginTop: 3 }}>
            <span style={{ fontSize: 11, color: 'var(--color-ink-muted)' }}>{active.parent.name} · 家长</span>
            <span style={{ width: 3, height: 3, borderRadius: '50%', background: 'var(--color-ink-subtle)' }} />
            <Avatar
              size={20}
              src={active.teacher ? getTeacherAvatarUrl(active.teacher.avatar, active.teacher.gender, active.teacher.id) : undefined}
              style={{ background: 'var(--color-surface-3)', color: 'var(--color-ink-muted)', fontSize: 10 }}
            />
            <span style={{ color: 'var(--color-ink-muted)', fontSize: 11 }}>{active.teacher ? `${active.teacher.name}老师` : '待分配教师'}</span>
            {active.subject && activeSubjectColor && (
              <span style={{ padding: '2px 7px', borderRadius: 999, background: activeSubjectColor.bg, color: activeSubjectColor.color, fontSize: 10 }}>{active.subject}</span>
            )}
          </div>
        </div>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 5, flexShrink: 0, justifyContent: isMobile ? 'flex-end' : 'initial' }}>
          {active.teacher && isPendingTeacherReply(active) && active.status !== 'CLOSED' && (
            <Button size="small" icon={<BellOutlined />} onClick={handleRemindTeacher} loading={reminding} style={{ borderRadius: 9, color: 'var(--color-primary-focus)', borderColor: 'var(--color-primary)' }}>
              提醒老师
            </Button>
          )}
          {active.status !== 'CLOSED' && (
            <Button size="small" onClick={handleClose} loading={closing} style={{ borderRadius: 9, color: 'var(--color-ink-muted)' }}>
              结束会话
            </Button>
          )}
          <Button type="text" icon={<CloseOutlined />} aria-label="关闭聊天" onClick={clearChatState} style={{ color: 'var(--color-ink-muted)' }} />
        </div>
      </div>

      <div style={{ padding: '8px 18px', background: 'var(--color-primary-bg)', borderBottom: '1px solid var(--color-hairline)', color: 'var(--color-ink-caption)', fontSize: 11, lineHeight: 1.5, flexShrink: 0 }}>
        请通过平台沟通，便于家长与任课老师持续查看完整记录。
      </div>

      <div style={{ flex: 1, minHeight: 0, overflowY: 'auto', padding: isMobile ? '16px 12px' : '22px 24px', background: 'var(--color-canvas)' }}>
        {active.replies.length ? active.replies.map(reply => <ChatBubble key={reply.id} reply={reply} />) : (
          <div style={{ minHeight: 180, display: 'grid', placeItems: 'center', color: 'var(--color-ink-subtle)', fontSize: 13 }}>
            还没有对话内容
          </div>
        )}
        <div ref={bottomRef} />
      </div>

      {active.status !== 'CLOSED' ? (
        <div style={{ borderTop: '1px solid var(--color-hairline)', padding: isMobile ? '10px 10px max(10px, env(safe-area-inset-bottom))' : '12px 16px', background: 'var(--color-surface-1)', flexShrink: 0, position: 'relative' }}>
          {pendingImage && (
            <div style={{ display: 'flex', alignItems: 'center', gap: 9, marginBottom: 9, padding: 7, borderRadius: 11, background: 'var(--color-surface-2)', border: '1px solid var(--color-hairline)' }}>
              <img src={pendingImage} alt="待发送图片预览" style={{ width: 48, height: 48, objectFit: 'cover', borderRadius: 8 }} />
              <span style={{ fontSize: 12, color: 'var(--color-ink-muted)' }}>图片已上传，发送后家长可查看</span>
              <Button type="text" size="small" aria-label="移除图片" icon={<CloseOutlined />} onClick={() => setPendingImage(null)} style={{ marginLeft: 'auto' }} />
            </div>
          )}
          {(showSticker || showEmoji) && (
            <div style={{ position: 'absolute', right: isMobile ? 8 : 16, bottom: 'calc(100% + 8px)', zIndex: 30, maxWidth: 'calc(100vw - 32px)' }}>
              {showSticker ? (
                <StickerPanel compact onPick={sticker => { void handleReply(STICKER_MARK(sticker.id)) }} />
              ) : (
                <div style={{ width: 260, display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: 4, padding: 9, border: '1px solid var(--color-hairline-strong)', borderRadius: 14, background: 'var(--color-surface-1)', boxShadow: 'var(--shadow-overlay)' }}>
                  {emojiOptions.map(emoji => (
                    <button key={emoji} type="button" aria-label={`插入表情 ${emoji}`} onClick={() => { setReplyText(text => text + emoji); setShowEmoji(false) }} style={{ border: 0, borderRadius: 8, background: 'transparent', padding: 5, fontSize: 21, cursor: 'pointer' }}>{emoji}</button>
                  ))}
                </div>
              )}
            </div>
          )}
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            aria-label="上传图片"
            style={{ display: 'none' }}
            onChange={event => {
              const file = event.currentTarget.files?.[0]
              if (file) void handleUploadImage(file)
              event.currentTarget.value = ''
            }}
          />
          <div style={{ display: 'flex', gap: 7, alignItems: 'flex-end' }}>
            <Button aria-label="上传图片" icon={<PictureOutlined />} loading={uploading} disabled={uploading} onClick={() => fileInputRef.current?.click()} style={{ width: 38, height: 38, flexShrink: 0, borderRadius: 10 }} />
            <Button aria-label="选择表情" icon={<SmileOutlined />} onClick={() => { setShowEmoji(value => !value); setShowSticker(false) }} style={{ width: 38, height: 38, flexShrink: 0, borderRadius: 10, background: showEmoji ? 'var(--color-primary-bg)' : undefined, color: showEmoji ? 'var(--color-primary)' : undefined }} />
            <Button aria-label="发送小羊表情包" onClick={() => { setShowSticker(value => !value); setShowEmoji(false) }} style={{ width: 38, height: 38, flexShrink: 0, borderRadius: 10, padding: 0, background: showSticker ? 'var(--color-primary-bg)' : undefined }}>🐑</Button>
            <TextArea
              value={replyText}
              onChange={event => setReplyText(event.target.value)}
              placeholder="以管理员身份回复…"
              autoSize={{ minRows: 1, maxRows: 4 }}
              onKeyDown={event => { if (event.key === 'Enter' && !event.shiftKey) { event.preventDefault(); void handleReply() } }}
              style={{ borderRadius: 10, flex: 1, minWidth: 0, resize: 'none' }}
            />
            <Button type="primary" aria-label="发送消息" icon={<SendOutlined />} loading={submitting} disabled={!replyText.trim() && !pendingImage} onClick={() => void handleReply()} style={{ width: 40, height: 38, flexShrink: 0, borderRadius: 10, background: 'var(--color-primary)' }} />
          </div>
        </div>
      ) : (
        <div style={{ padding: '12px 16px', background: 'var(--color-surface-2)', borderTop: '1px solid var(--color-hairline)', textAlign: 'center', flexShrink: 0 }}>
          <Text style={{ color: 'var(--color-ink-muted)', fontSize: 13 }}><CheckCircleOutlined style={{ marginRight: 6, color: 'var(--color-success)' }} />该会话已结束</Text>
        </div>
      )}
    </div>
  ) : null

  return (
    <div style={{ paddingBottom: 20 }}>
      {!embedded && (
        <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 12, marginBottom: 14 }}>
          <div>
            <Title level={4} style={{ margin: '0 0 3px', color: 'var(--color-ink)' }}>家长沟通</Title>
            <Text style={{ color: 'var(--color-ink-muted)', fontSize: 13 }}>查看家长、学生与任课老师的完整留言往来</Text>
          </div>
          <Tag style={{ margin: 2, border: 0, borderRadius: 999, background: 'var(--color-success-bg)', color: 'var(--color-success)', fontSize: 11, whiteSpace: 'nowrap' }}>
            <span style={{ display: 'inline-block', width: 6, height: 6, marginRight: 6, borderRadius: '50%', background: 'var(--color-success)', verticalAlign: 'middle' }} />实时同步
          </Tag>
        </div>
      )}

      {statCards}
      {servicePanel}

      <div style={{ marginBottom: 10 }}>
        {filterBar}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8, padding: '2px 2px 10px' }}>
          <div>
            <Text strong style={{ fontSize: 15, color: 'var(--color-ink)' }}>沟通记录</Text>
            <Text style={{ color: 'var(--color-ink-muted)', fontSize: 12, marginLeft: 8 }}>{messages.length} 个会话</Text>
          </div>
          {stats.pendingTeacher > 0 && <Badge count={stats.pendingTeacher} overflowCount={99} color="var(--color-primary)" title={`${stats.pendingTeacher} 条待教师回复`} />}
        </div>
      </div>

      {conversationList}

      <BrandModal
        open={Boolean(activeId)}
        onCancel={clearChatState}
        getContainer={() => document.body}
        className="communication-chat-fullscreen"
        footer={null}
        title={null}
        closable={false}
        mobileFullHeight
        width="100vw"
        style={{ top: 0, maxWidth: 'none', paddingBottom: 0, margin: 0, width: '100vw' }}
        styles={{
          mask: { background: 'rgba(26,18,1,.46)' },
          content: { padding: 0, borderRadius: 0, overflow: 'hidden', background: 'var(--color-surface-1)', height: '100dvh', maxHeight: '100dvh', display: 'flex', flexDirection: 'column' },
          body: { padding: 0, flex: 1, minHeight: 0, maxHeight: 'none', display: 'flex', flexDirection: 'column' },
        }}
      >
        {chatPanel}
      </BrandModal>
    </div>
  )
}

'use client'

import { useMemo, useState } from 'react'
import useSWR from 'swr'
import {
  Alert,
  Avatar,
  Button,
  Card,
  Col,
  DatePicker,
  Empty,
  Input,
  Row,
  Segmented,
  Select,
  Space,
  Table,
  Tag,
  Typography,
  message,
} from 'antd'
import type { ColumnsType } from 'antd/es/table'
import {
  AlertOutlined,
  CalendarOutlined,
  CheckCircleOutlined,
  ClockCircleOutlined,
  ReloadOutlined,
  SaveOutlined,
  SearchOutlined,
  UserOutlined,
} from '@ant-design/icons'
import dayjs from 'dayjs'
import { PageLayout } from '@/components/Layout/PageLayout'
import { useDivision } from '@/contexts/DivisionContext'
import { useIsMobile } from '@/hooks/useIsMobile'

const { Text } = Typography

type RowData = {
  student: {
    id: string
    name: string
    grade: string | null
    remainHours: number
    division: string
  }
  term: {
    id: string
    name: string
    endDate: string
  }
  daysRemaining: number
  trigger: string[]
  followUp: {
    id: string
    status: string
    note: string | null
    nextFollowUpAt: string | null
  } | null
}

type RenewalsData = {
  renewals: RowData[]
  lowHoursWarn: number
}

const fetcher = async (url: string) => {
  const r = await fetch(url)
  const d = await r.json()
  if (!r.ok) throw new Error(d.error || '加载续费跟进失败')
  return d
}

const STATUS_LABELS: Record<string, string> = {
  OPEN: '待联系',
  CONTACTED: '已联系',
  RENEWED: '已续费',
  NOT_RENEWING: '暂不续费',
}

const STATUS_COLORS: Record<string, string> = {
  OPEN: 'orange',
  CONTACTED: 'blue',
  RENEWED: 'success',
  NOT_RENEWING: 'default',
}

export default function RenewalsPage() {
  const { division } = useDivision()
  const isMobile = useIsMobile() ?? false
  const { data, error, mutate, isLoading } = useSWR<RenewalsData>(
    `/api/renewals?division=${division}`,
    fetcher,
  )

  const [search, setSearch] = useState('')
  const [statusFilter, setStatusFilter] = useState<string>('ALL')
  const [form, setForm] = useState<
    Record<string, { status: string; note: string; nextFollowUpAt: string }>
  >({})
  const [savingId, setSavingId] = useState<string | null>(null)

  const allList = useMemo(() => data?.renewals || [], [data])

  // KPI Statistics
  const stats = useMemo(() => {
    let pendingCount = 0
    let lowHoursCount = 0
    let termEndingCount = 0
    let renewedCount = 0

    allList.forEach((r) => {
      const currentStatus = form[r.student.id]?.status ?? r.followUp?.status ?? 'OPEN'
      if (currentStatus === 'OPEN') pendingCount++
      if (currentStatus === 'RENEWED') renewedCount++
      if (r.trigger.includes('LOW_HOURS')) lowHoursCount++
      if (r.trigger.some((t) => t.includes('TERM') || t.includes('END'))) termEndingCount++
    })

    return {
      total: allList.length,
      pending: pendingCount,
      lowHours: lowHoursCount,
      termEnding: termEndingCount,
      renewed: renewedCount,
    }
  }, [allList, form])

  // Filtered list
  const filteredList = useMemo(() => {
    return allList.filter((r) => {
      const currentStatus = form[r.student.id]?.status ?? r.followUp?.status ?? 'OPEN'
      if (statusFilter !== 'ALL' && currentStatus !== statusFilter) return false

      if (search.trim()) {
        const q = search.trim().toLowerCase()
        const nameMatch = r.student.name.toLowerCase().includes(q)
        const gradeMatch = r.student.grade?.toLowerCase().includes(q)
        const termMatch = r.term.name.toLowerCase().includes(q)
        if (!nameMatch && !gradeMatch && !termMatch) return false
      }

      return true
    })
  }, [allList, statusFilter, search, form])

  const save = async (row: RowData) => {
    const f = form[row.student.id] || {
      status: row.followUp?.status || 'OPEN',
      note: row.followUp?.note || '',
      nextFollowUpAt: row.followUp?.nextFollowUpAt?.slice(0, 10) || '',
    }
    setSavingId(row.student.id)
    try {
      const r = await fetch(`/api/renewals?division=${row.student.division}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          studentId: row.student.id,
          termId: row.term.id,
          status: f.status,
          note: f.note,
          nextFollowUpAt: f.nextFollowUpAt || null,
        }),
      })
      const d = await r.json()
      if (!r.ok) throw new Error(d.error || '保存失败')
      await mutate()
      message.success(`${row.student.name} 的跟进记录已保存`)
    } catch (e) {
      message.error(e instanceof Error ? e.message : '保存失败')
    } finally {
      setSavingId(null)
    }
  }

  const columns: ColumnsType<RowData> = [
    {
      title: '学员',
      key: 'student',
      width: 140,
      render: (_, r) => (
        <Space size={8}>
          <Avatar
            icon={<UserOutlined />}
            style={{ backgroundColor: 'var(--color-primary, #14574D)', flexShrink: 0 }}
          />
          <div>
            <div style={{ fontWeight: 600, color: 'var(--color-ink, #1F2329)' }}>
              {r.student.name}
            </div>
            <div style={{ fontSize: 12, color: 'var(--color-ink-muted, #8D806F)' }}>
              {r.student.grade || '未填年级'}
            </div>
          </div>
        </Space>
      ),
    },
    {
      title: '剩余课时',
      dataIndex: ['student', 'remainHours'],
      key: 'remainHours',
      width: 110,
      render: (v: number) => (
        <Text strong style={{ color: v <= (data?.lowHoursWarn || 3) ? '#E8784A' : 'inherit' }}>
          {v} 节
        </Text>
      ),
    },
    {
      title: '提醒原因',
      key: 'reason',
      width: 180,
      render: (_, r) => (
        <Space wrap size={4}>
          {r.trigger.map((t) => (
            <Tag
              key={t}
              color={t === 'LOW_HOURS' ? 'orange' : 'blue'}
              style={{ borderRadius: 6, margin: 0 }}
            >
              {t === 'LOW_HOURS' ? `低于 ${data?.lowHoursWarn ?? 3} 课时` : `批次剩 ${r.daysRemaining} 天`}
            </Tag>
          ))}
        </Space>
      ),
    },
    {
      title: '所属批次',
      dataIndex: ['term', 'name'],
      key: 'term',
      width: 140,
      render: (name: string, r) => (
        <div>
          <div style={{ fontSize: 13, color: 'var(--color-ink, #1F2329)' }}>{name}</div>
          <div style={{ fontSize: 11, color: 'var(--color-ink-muted, #8D806F)' }}>
            截止 {r.term.endDate ? dayjs(r.term.endDate).format('YYYY-MM-DD') : '-'}
          </div>
        </div>
      ),
    },
    {
      title: '跟进状态',
      key: 'status',
      width: 130,
      render: (_, r) => {
        const f = form[r.student.id]
        const currentVal = f?.status || r.followUp?.status || 'OPEN'
        return (
          <Select
            value={currentVal}
            onChange={(status) =>
              setForm((prev) => ({
                ...prev,
                [r.student.id]: {
                  status,
                  note: f?.note ?? r.followUp?.note ?? '',
                  nextFollowUpAt: f?.nextFollowUpAt ?? r.followUp?.nextFollowUpAt?.slice(0, 10) ?? '',
                },
              }))
            }
            options={Object.entries(STATUS_LABELS).map(([value, label]) => ({
              value,
              label: (
                <Tag color={STATUS_COLORS[value]} style={{ margin: 0 }}>
                  {label}
                </Tag>
              ),
            }))}
            style={{ width: '100%' }}
          />
        )
      },
    },
    {
      title: '沟通记录',
      key: 'note',
      render: (_, r) => {
        const f = form[r.student.id]
        return (
          <Input.TextArea
            value={f?.note ?? r.followUp?.note ?? ''}
            rows={2}
            maxLength={1200}
            onChange={(e) =>
              setForm((prev) => ({
                ...prev,
                [r.student.id]: {
                  status: f?.status ?? r.followUp?.status ?? 'OPEN',
                  note: e.target.value,
                  nextFollowUpAt: f?.nextFollowUpAt ?? r.followUp?.nextFollowUpAt?.slice(0, 10) ?? '',
                },
              }))
            }
            placeholder="登记家长沟通意向、待续费科目与考量点..."
            style={{ borderRadius: 8, fontSize: 13 }}
          />
        )
      },
    },
    {
      title: '下次联系',
      key: 'next',
      width: 140,
      render: (_, r) => {
        const f = form[r.student.id]
        const dateVal = f?.nextFollowUpAt ?? r.followUp?.nextFollowUpAt?.slice(0, 10) ?? ''
        return (
          <DatePicker
            value={dateVal ? dayjs(dateVal) : null}
            onChange={(d) =>
              setForm((prev) => ({
                ...prev,
                [r.student.id]: {
                  status: f?.status ?? r.followUp?.status ?? 'OPEN',
                  note: f?.note ?? r.followUp?.note ?? '',
                  nextFollowUpAt: d ? d.format('YYYY-MM-DD') : '',
                },
              }))
            }
            placeholder="下次日期"
            style={{ width: '100%', borderRadius: 8 }}
          />
        )
      },
    },
    {
      title: '操作',
      key: 'action',
      width: 90,
      fixed: 'right',
      render: (_, r) => (
        <Button
          type="primary"
          icon={<SaveOutlined />}
          loading={savingId === r.student.id}
          onClick={() => void save(r)}
          style={{
            background: 'var(--color-primary, #14574D)',
            borderColor: 'var(--color-primary, #14574D)',
            borderRadius: 8,
          }}
        >
          保存
        </Button>
      ),
    },
  ]

  return (
    <PageLayout
      title="续费跟进"
      subtitle="课时告急预警与批次临期跟进台账，支持快速记录家长意向与下次跟进日程"
      actions={
        <Button icon={<ReloadOutlined />} onClick={() => mutate()} loading={isLoading}>
          刷新
        </Button>
      }
    >
      {error && (
        <Alert
          type="error"
          showIcon
          message={error instanceof Error ? error.message : '加载续费跟进失败'}
          style={{ marginBottom: 16, borderRadius: 10 }}
        />
      )}

      {/* 4 KPI Metrics */}
      <Row gutter={[12, 12]} style={{ marginBottom: 16 }}>
        <Col xs={12} sm={6}>
          <Card
            className="pressable"
            bordered={false}
            style={{
              borderRadius: 12,
              border: statusFilter === 'OPEN' ? '2px solid #E8784A' : '1px solid #EEE7E1',
              background: '#FFF9F5',
              cursor: 'pointer',
            }}
            styles={{ body: { padding: '14px 16px' } }}
            onClick={() => setStatusFilter(statusFilter === 'OPEN' ? 'ALL' : 'OPEN')}
          >
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <span style={{ fontSize: 12, color: '#8D806F' }}>待联系跟进</span>
              <AlertOutlined style={{ color: '#E8784A', fontSize: 15 }} />
            </div>
            <div style={{ fontSize: 28, fontWeight: 800, color: '#E8784A', marginTop: 4 }}>
              {stats.pending}
            </div>
          </Card>
        </Col>

        <Col xs={12} sm={6}>
          <Card
            className="pressable"
            bordered={false}
            style={{
              borderRadius: 12,
              border: '1px solid #EEE7E1',
              background: '#FEF2F2',
              cursor: 'default',
            }}
            styles={{ body: { padding: '14px 16px' } }}
          >
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <span style={{ fontSize: 12, color: '#8D806F' }}>课时告急</span>
              <ClockCircleOutlined style={{ color: '#DC2626', fontSize: 15 }} />
            </div>
            <div style={{ fontSize: 28, fontWeight: 800, color: '#DC2626', marginTop: 4 }}>
              {stats.lowHours}
            </div>
          </Card>
        </Col>

        <Col xs={12} sm={6}>
          <Card
            className="pressable"
            bordered={false}
            style={{
              borderRadius: 12,
              border: '1px solid #EEE7E1',
              background: '#EFF6FF',
              cursor: 'default',
            }}
            styles={{ body: { padding: '14px 16px' } }}
          >
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <span style={{ fontSize: 12, color: '#8D806F' }}>批次临期</span>
              <CalendarOutlined style={{ color: '#2563EB', fontSize: 15 }} />
            </div>
            <div style={{ fontSize: 28, fontWeight: 800, color: '#2563EB', marginTop: 4 }}>
              {stats.termEnding}
            </div>
          </Card>
        </Col>

        <Col xs={12} sm={6}>
          <Card
            className="pressable"
            bordered={false}
            style={{
              borderRadius: 12,
              border: statusFilter === 'RENEWED' ? '2px solid #27A644' : '1px solid #EEE7E1',
              background: '#F0FDF4',
              cursor: 'pointer',
            }}
            styles={{ body: { padding: '14px 16px' } }}
            onClick={() => setStatusFilter(statusFilter === 'RENEWED' ? 'ALL' : 'RENEWED')}
          >
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <span style={{ fontSize: 12, color: '#8D806F' }}>已续费</span>
              <CheckCircleOutlined style={{ color: '#27A644', fontSize: 15 }} />
            </div>
            <div style={{ fontSize: 28, fontWeight: 800, color: '#27A644', marginTop: 4 }}>
              {stats.renewed}
            </div>
          </Card>
        </Col>
      </Row>

      {/* Filter and Search Bar */}
      <Card
        bordered={false}
        style={{ borderRadius: 12, border: '1px solid #EEE7E1', marginBottom: 16 }}
        styles={{ body: { padding: 14 } }}
      >
        <Space wrap style={{ width: '100%', justifyContent: 'space-between' }}>
          <Segmented
            value={statusFilter}
            onChange={(val) => setStatusFilter(String(val))}
            options={[
              { label: `全部 (${allList.length})`, value: 'ALL' },
              { label: `待联系 (${stats.pending})`, value: 'OPEN' },
              { label: '已联系', value: 'CONTACTED' },
              { label: `已续费 (${stats.renewed})`, value: 'RENEWED' },
              { label: '暂不续费', value: 'NOT_RENEWING' },
            ]}
          />
          <Input
            prefix={<SearchOutlined style={{ color: '#8D806F' }} />}
            placeholder="搜索学员姓名、年级或批次..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            allowClear
            style={{ width: isMobile ? '100%' : 260, borderRadius: 8 }}
          />
        </Space>
      </Card>

      {/* Content Area: Mobile Cards or Desktop Table */}
      {isMobile ? (
        <div style={{ display: 'grid', gap: 12 }}>
          {filteredList.length === 0 ? (
            <Card style={{ borderRadius: 14 }}>
              <Empty description="暂无符合条件的续费跟进记录" />
            </Card>
          ) : (
            filteredList.map((r) => {
              const f = form[r.student.id]
              const currentStatus = f?.status || r.followUp?.status || 'OPEN'
              const dateVal = f?.nextFollowUpAt ?? r.followUp?.nextFollowUpAt?.slice(0, 10) ?? ''

              return (
                <Card
                  key={r.student.id}
                  style={{
                    borderRadius: 14,
                    border: '1px solid #EEE7E1',
                    boxShadow: '0 2px 8px rgba(0,0,0,0.03)',
                  }}
                  styles={{ body: { padding: 14 } }}
                >
                  <div
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'space-between',
                      marginBottom: 10,
                    }}
                  >
                    <Space size={8}>
                      <Avatar
                        icon={<UserOutlined />}
                        style={{ backgroundColor: 'var(--color-primary, #14574D)' }}
                      />
                      <div>
                        <div style={{ fontWeight: 700, fontSize: 16, color: '#1F2329' }}>
                          {r.student.name}
                        </div>
                        <div style={{ fontSize: 12, color: '#8D806F' }}>
                          {r.student.grade || '未填年级'} · 剩余{' '}
                          <span style={{ color: '#E8784A', fontWeight: 600 }}>
                            {r.student.remainHours}
                          </span>{' '}
                          节
                        </div>
                      </div>
                    </Space>
                    <Tag color={STATUS_COLORS[currentStatus]} style={{ margin: 0 }}>
                      {STATUS_LABELS[currentStatus]}
                    </Tag>
                  </div>

                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 12 }}>
                    {r.trigger.map((t) => (
                      <Tag
                        key={t}
                        color={t === 'LOW_HOURS' ? 'orange' : 'blue'}
                        style={{ borderRadius: 6, margin: 0 }}
                      >
                        {t === 'LOW_HOURS'
                          ? `低于 ${data?.lowHoursWarn ?? 3} 课时`
                          : `批次剩 ${r.daysRemaining} 天`}
                      </Tag>
                    ))}
                    <Tag style={{ borderRadius: 6, margin: 0 }}>{r.term.name}</Tag>
                  </div>

                  <div style={{ display: 'grid', gap: 8, marginTop: 10 }}>
                    <div style={{ display: 'flex', gap: 8 }}>
                      <Select
                        value={currentStatus}
                        onChange={(status) =>
                          setForm((prev) => ({
                            ...prev,
                            [r.student.id]: {
                              status,
                              note: f?.note ?? r.followUp?.note ?? '',
                              nextFollowUpAt: f?.nextFollowUpAt ?? r.followUp?.nextFollowUpAt?.slice(0, 10) ?? '',
                            },
                          }))
                        }
                        options={Object.entries(STATUS_LABELS).map(([value, label]) => ({
                          value,
                          label: STATUS_LABELS[value],
                        }))}
                        style={{ width: 120 }}
                      />
                      <DatePicker
                        value={dateVal ? dayjs(dateVal) : null}
                        onChange={(d) =>
                          setForm((prev) => ({
                            ...prev,
                            [r.student.id]: {
                              status: f?.status ?? r.followUp?.status ?? 'OPEN',
                              note: f?.note ?? r.followUp?.note ?? '',
                              nextFollowUpAt: d ? d.format('YYYY-MM-DD') : '',
                            },
                          }))
                        }
                        placeholder="下次跟进"
                        style={{ flex: 1, borderRadius: 8 }}
                      />
                    </div>

                    <Input.TextArea
                      value={f?.note ?? r.followUp?.note ?? ''}
                      rows={2}
                      maxLength={1200}
                      onChange={(e) =>
                        setForm((prev) => ({
                          ...prev,
                          [r.student.id]: {
                            status: f?.status ?? r.followUp?.status ?? 'OPEN',
                            note: e.target.value,
                            nextFollowUpAt: f?.nextFollowUpAt ?? r.followUp?.nextFollowUpAt?.slice(0, 10) ?? '',
                          },
                        }))
                      }
                      placeholder="登记家长沟通意向..."
                      style={{ borderRadius: 8, fontSize: 13 }}
                    />

                    <Button
                      type="primary"
                      icon={<SaveOutlined />}
                      block
                      loading={savingId === r.student.id}
                      onClick={() => void save(r)}
                      style={{
                        background: 'var(--color-primary, #14574D)',
                        borderColor: 'var(--color-primary, #14574D)',
                        borderRadius: 8,
                        marginTop: 4,
                      }}
                    >
                      保存记录
                    </Button>
                  </div>
                </Card>
              )
            })
          )}
        </div>
      ) : (
        <Card style={{ borderRadius: 14, border: '1px solid #EEE7E1' }}>
          {filteredList.length === 0 ? (
            <Empty description="暂无符合条件的续费跟进记录" />
          ) : (
            <Table
              rowKey={(r) => r.student.id}
              dataSource={filteredList}
              columns={columns}
              scroll={{ x: 1000 }}
              pagination={{ pageSize: 20, showTotal: (total) => `共 ${total} 位学员` }}
            />
          )}
        </Card>
      )}
    </PageLayout>
  )
}

'use client'
import { AdaptiveSelect } from '@/components/AdaptiveSelect';

import { useEffect, useMemo, useState } from 'react'
import { format } from 'date-fns'
import { zhCN } from 'date-fns/locale'
import { addDays, subDays } from 'date-fns'
import {
  Alert,
  Button,
  Card,
  Checkbox,
  Input,
  InputNumber,
  message,
  Radio,
  Spin,
  Tag,
  Typography,
} from 'antd'
import { BrandModal } from '@/components/Common/BrandModal'
import { PageLayout } from '@/components/Layout/PageLayout'
import { useRouter } from 'next/navigation'
import useSWR from 'swr'
import {
  CalendarOutlined,
  CheckOutlined,
  ClockCircleOutlined,
  CrownOutlined,
  EnvironmentOutlined,
  PlusOutlined,
  TeamOutlined,
} from '@ant-design/icons'
import { useDivision } from '@/contexts/DivisionContext'
import { MobileSelect } from '@/components/MobileSelect'
import { HOURLY_PERIODS } from '@/lib/schedule-periods'
import { getPersonalClassLimit } from '@/lib/schedule-class-type'
import { useIsMobile } from '@/hooks/useIsMobile'

const { Text } = Typography

const INTENSIVE_COLOR = '#534AB7'
const HOURLY_SLOTS = HOURLY_PERIODS
  .filter((period) => period.start < '22:00' && !['12:00', '13:00'].includes(period.start))
  .map((period) => ({ ...period, label: `${period.start}–${period.end}` }))

const TYPE_CONFIG: Record<string, { label: string; bg: string; color: string }> = {
  ONE_ON_ONE:   { label:'一对一',   bg:'#EEEDFE', color:'#3C3489' },
  ONE_ON_TWO:   { label:'一对二',   bg:'#FBEAF0', color:'#72243E' },
  ONE_ON_THREE: { label:'一对三',   bg:'#EEF5FC', color:'#185FA5' },
}

const SUBJECT_CONFIG: Array<{ match: string; bg: string; color: string }> = [
  { match: '数学', bg: '#F0EEFF', color: '#534AB7' },
  { match: '物理', bg: '#EAF3FB', color: '#185FA5' },
  { match: '化学', bg: '#E8F7F1', color: '#1D7D62' },
  { match: '英语', bg: '#FBEAF0', color: '#A43F68' },
  { match: '语文', bg: '#FDF0EA', color: '#C95F35' },
]

const subjectStyle = (subject: string) => (
  SUBJECT_CONFIG.find((item) => subject.includes(item.match))
  || { bg: '#F3F0EB', color: '#5A4E3A' }
)

type ScheduleLesson = {
  lessonId?: string
  teacherName?: string
  teacherId?: string
  courseName?: string
  subject?: string
  grade?: string
  courseType?: string
  headcount?: number
  startTime?: string
}

const fetcher = (url: string) => fetch(url).then(r => r.ok ? r.json() : Promise.reject('load error'))

type IntensiveCreateData = {
  roomId: string
  roomName: string
  startTime: string
  endTime: string
  date: string
  teacherId: string
  studentIds: string[]
  courseId: string
  teachingType: 'ONE_ON_ONE' | 'ONE_ON_TWO' | 'ONE_ON_THREE'
}

type HistoryStatus = 'PRESENT' | 'LEAVE' | 'ABSENT' | 'MAKEUP'

type IntensiveHistoryGroup = {
  id: string
  name: string
  teachingType: IntensiveCreateData['teachingType']
  expectedStudents: number
  courseName: string
  subject: string
  grade?: string | null
  teachers: Array<{ id: string; name: string; subject?: string | null }>
  students: Array<{
    id: string
    name: string
    grade?: string | null
    enrollmentStatus: string
    totalHours: number
    usedHours: number
    remainHours: number
  }>
}

type IntensiveHistoryDraft = {
  groupId: string
  teacherId: string
  lessonDate: string
  startTime: string
  endTime: string
  actualMinutes: number
  reason: string
  records: Array<{ studentId: string; status: HistoryStatus }>
}

type IntensiveReviewItem = {
  id: string
  lessonId: string
  revision: number
  teacherName: string
  groupName: string
  subject: string
  grade?: string | null
  lessonDate: string
  startTime: string
  endTime: string
  plannedMinutes?: number | null
  actualMinutes: number
  teacherNote?: string | null
  submittedAt: string
  students: Array<{
    id: string
    name: string
    grade?: string | null
    status: HistoryStatus
    remainHours: number
  }>
}

type IntensiveAppointmentItem = {
  id: string
  groupId: string
  groupName: string
  teachingType: string
  teachingTypeLabel: string
  teacherName: string
  subject: string
  grade?: string | null
  lessonDate: string
  startTime: string
  endTime: string
  note?: string | null
  isHistorical: boolean
  statusLabel: string
  students: Array<{ id: string; name: string; grade?: string | null }>
}

export default function IntensiveSchedulePage() {
  const router = useRouter()
  const isMobile = useIsMobile() ?? false
  const [selectedDate, setSelectedDate] = useState(new Date())
  const [createOpen, setCreateOpen] = useState(false)
  const [createData, setCreateData] = useState<IntensiveCreateData>({
    roomId: '', roomName: '', startTime: '', endTime: '', date: '', teacherId: '', studentIds: [], courseId: '', teachingType: 'ONE_ON_ONE',
  })
  const [saving, setSaving] = useState(false)
  const [conflictMsg, setConflictMsg] = useState('')
  const [historyOpen, setHistoryOpen] = useState(false)
  const [historySaving, setHistorySaving] = useState(false)
  const [historyConfirmed, setHistoryConfirmed] = useState(false)
  const [reviewingId, setReviewingId] = useState('')
  const [targetReviewLessonId, setTargetReviewLessonId] = useState('')
  const [targetAppointmentLessonId, setTargetAppointmentLessonId] = useState('')
  const [reviewNotes, setReviewNotes] = useState<Record<string, string>>({})
  const [historyDraft, setHistoryDraft] = useState<IntensiveHistoryDraft>({
    groupId: '',
    teacherId: '',
    lessonDate: format(new Date(), 'yyyy-MM-dd'),
    startTime: '18:00',
    endTime: '19:00',
    actualMinutes: 60,
    reason: '',
    records: [],
  })

  const { division } = useDivision()
  const dateStr = format(selectedDate, 'yyyy-MM-dd')
  const { data: daily, isLoading, mutate } = useSWR(`/api/schedules/daily?date=${dateStr}&courseType=SMALL&division=${division}`, fetcher, { refreshInterval: 180_000 })
  const { data: roomsData } = useSWR('/api/rooms', fetcher)
  const { data: teachersData } = useSWR(`/api/teachers/options?division=${division}`, fetcher)
  const { data: studentsData } = useSWR(`/api/students?limit=500&division=${division}`, fetcher)
  const { data: coursesData } = useSWR(`/api/courses?limit=200&division=${division}`, fetcher)
  const { data: historyData, mutate: mutateHistory } = useSWR(
    `/api/admin/intensive-history?division=${division}`,
    fetcher,
    { refreshInterval: 60_000 },
  )
  const { data: reviewData, mutate: mutateReviews } = useSWR(
    `/api/admin/intensive-reviews?division=${division}&status=PENDING`,
    fetcher,
    { refreshInterval: 30_000, revalidateOnFocus: true, revalidateOnReconnect: true },
  )
  const { data: appointmentData } = useSWR(
    `/api/admin/intensive-appointments?division=${division}`,
    fetcher,
    { refreshInterval: 60_000, revalidateOnFocus: true, revalidateOnReconnect: true },
  )

  const matrix = useMemo(() => (
    (daily?.matrix || {}) as Record<string, Record<string, ScheduleLesson[]>>
  ), [daily?.matrix])
  const allRooms: Record<string, unknown>[] = useMemo(() => (
    Array.isArray(roomsData) ? roomsData : []
  ), [roomsData])
  const teacherList: Record<string, unknown>[] = Array.isArray(teachersData?.teachers) ? teachersData.teachers : Array.isArray(teachersData) ? teachersData : []
  const studentList: Record<string, unknown>[] = Array.isArray(studentsData?.students) ? studentsData.students : Array.isArray(studentsData) ? studentsData : []
  const courseList: Record<string, unknown>[] = Array.isArray(coursesData) ? coursesData : []
  const historyGroups: IntensiveHistoryGroup[] = Array.isArray(historyData?.groups) ? historyData.groups : []
  const selectedHistoryGroup = historyGroups.find((group) => group.id === historyDraft.groupId)
  const pendingReviews: IntensiveReviewItem[] = useMemo(() => (
    Array.isArray(reviewData?.reviews) ? reviewData.reviews : []
  ), [reviewData])
  const pendingAppointments: IntensiveAppointmentItem[] = useMemo(() => (
    Array.isArray(appointmentData?.appointments) ? appointmentData.appointments : []
  ), [appointmentData])

  useEffect(() => {
    const params = new URLSearchParams(window.location.search)
    setTargetReviewLessonId(params.get('reviewLessonId') || '')
    setTargetAppointmentLessonId(params.get('appointmentLessonId') || '')
    if (params.get('section') === 'appointments') {
      window.setTimeout(() => {
        document.getElementById('intensive-appointments')?.scrollIntoView({
          behavior: 'smooth',
          block: 'start',
        })
      }, 100)
    }
    if (params.get('review') === 'pending' || params.get('section') === 'reviews') {
      window.setTimeout(() => {
        document.getElementById('intensive-reviews')?.scrollIntoView({
          behavior: 'smooth',
          block: 'start',
        })
      }, 100)
    }
  }, [])

  useEffect(() => {
    if (!targetReviewLessonId || !pendingReviews.some((review) => review.lessonId === targetReviewLessonId)) return
    const timer = window.setTimeout(() => {
      document.getElementById(`review-lesson-${targetReviewLessonId}`)?.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      })
    }, 100)
    return () => window.clearTimeout(timer)
  }, [pendingReviews, targetReviewLessonId])

  useEffect(() => {
    if (
      !targetAppointmentLessonId
      || !pendingAppointments.some((appointment) => appointment.id === targetAppointmentLessonId)
    ) return
    const timer = window.setTimeout(() => {
      document.getElementById(`appointment-lesson-${targetAppointmentLessonId}`)?.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      })
    }, 100)
    return () => window.clearTimeout(timer)
  }, [pendingAppointments, targetAppointmentLessonId])

  // Only ONE_ON_ONE rooms (desks/spots)
  const spots = useMemo(() => allRooms.filter(r => {
    const t = (r.type as string || '').toLowerCase()
    const u = (r.usageType as string || '').toLowerCase()
    return t.includes('一对一') || t.includes('one_on_one')
      || u.includes('one_on_one') || u.includes('一对一')
  }), [allRooms])

  // Build spot × hour grid
  const grid = useMemo(() => {
    const g: Record<string, Record<string, ScheduleLesson[]>> = {}
    spots.forEach(s => { g[s.id as string] = {} })
    Object.entries(matrix).forEach(([roomId, periods]) => {
      if (!spots.find(s => s.id === roomId)) return
      Object.entries(periods).forEach(([periodId, lessons]) => {
        // Daily matrix may contain standard-period ids or hourly ids. Prefer the
        // lesson's real start time so evening appointments are never dropped.
        const firstLesson = lessons[0]
        const hourSlot = HOURLY_SLOTS.find(h => h.id === periodId)
          || HOURLY_SLOTS.find(h => h.start === firstLesson?.startTime)
        if (hourSlot) {
          if (!g[roomId]) g[roomId] = {}
          if (!g[roomId][hourSlot.id]) g[roomId][hourSlot.id] = []
          for (const lesson of lessons) {
            if (!g[roomId][hourSlot.id].some((item) => item.lessonId === lesson.lessonId)) {
              g[roomId][hourSlot.id].push(lesson)
            }
          }
        }
      })
    })
    return g
  }, [matrix, spots])

  // Count intensive lessons
  const intensiveCount = useMemo(() => {
    let count = 0
    Object.values(grid).forEach(hours => {
      Object.values(hours).forEach((lessons) => { count += lessons.length })
    })
    return count
  }, [grid])

  // 当日个性化课程时间线（替代桌位×小时矩阵课表）
  const todayLessons = useMemo(() => {
    const list: Array<{ spot: string; slotStart: string; slotEnd: string; lesson: ScheduleLesson }> = []
    Object.entries(grid).forEach(([roomId, hours]) => {
      const spot = spots.find((s) => s.id === roomId)
      Object.entries(hours).forEach(([slotId, lessons]) => {
        const slot = HOURLY_SLOTS.find((h) => h.id === slotId)
        lessons.forEach((lesson) => {
          list.push({
            spot: (spot?.name as string) || '未分配桌位',
            slotStart: slot?.start || lesson.startTime || '',
            slotEnd: slot?.end || '',
            lesson,
          })
        })
      })
    })
    return list.sort((a, b) => a.slotStart.localeCompare(b.slotStart))
  }, [grid, spots])

  const openCreate = () => {
    setCreateData({
      roomId: '',
      roomName: '',
      startTime: '',
      endTime: '',
      date: dateStr,
      teacherId: '',
      studentIds: [],
      courseId: '',
      teachingType: 'ONE_ON_ONE',
    })
    setConflictMsg('')
    setCreateOpen(true)
  }

  const handleCreate = async () => {
    const expectedStudents = getPersonalClassLimit(createData.teachingType)
    if (!createData.roomId) {
      message.warning('请选择桌位')
      return
    }
    if (!createData.startTime || !createData.endTime) {
      message.warning('请填写开始与结束时间')
      return
    }
    if (createData.endTime <= createData.startTime) {
      message.warning('结束时间必须晚于开始时间')
      return
    }
    if (!createData.teacherId || !createData.courseId || createData.studentIds.length !== expectedStudents) {
      message.warning(`请选择老师、课程和${expectedStudents}名学员`)
      return
    }
    setSaving(true)
    setConflictMsg('')
    try {
      const selectedCourse = courseList.find((course) => course.id === createData.courseId)
      const res = await fetch('/api/schedules', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: `${selectedCourse?.subject || selectedCourse?.name || '突击全能班'}${TYPE_CONFIG[createData.teachingType].label}`,
          courseId: createData.courseId,
          teacherId: createData.teacherId,
          studentIds: createData.studentIds,
          classType: createData.teachingType,
          startDate: createData.date,
          startTimeVal: createData.startTime,
          endTimeVal: createData.endTime,
          roomId: createData.roomId,
          division,
        }),
      })
      const payload = await res.json().catch(() => ({}))
      if (!res.ok) {
        if (payload.conflicts?.length) {
          setConflictMsg(payload.conflicts.map((c: Record<string, unknown>) => c.detail || c.message).join('；'))
        } else {
          setConflictMsg(payload.error || '创建失败')
        }
        return
      }
      message.success('突击全能班排课成功')
      setCreateOpen(false)
      await mutate()
    } catch {
      message.error('网络错误')
    } finally { setSaving(false) }
  }

  const selectHistoryGroup = (groupId: string) => {
    const group = historyGroups.find((item) => item.id === groupId)
    const records = (group?.students || [])
      .slice(0, group?.expectedStudents || 1)
      .map((student) => ({ studentId: student.id, status: 'PRESENT' as HistoryStatus }))
    setHistoryDraft((current) => ({
      ...current,
      groupId,
      teacherId: group?.teachers[0]?.id || '',
      actualMinutes: 60,
      records,
    }))
    setHistoryConfirmed(false)
  }

  const openHistory = () => {
    const group = historyGroups[0]
    const records = (group?.students || [])
      .slice(0, group?.expectedStudents || 1)
      .map((student) => ({ studentId: student.id, status: 'PRESENT' as HistoryStatus }))
    setHistoryDraft({
      groupId: group?.id || '',
      teacherId: group?.teachers[0]?.id || '',
      lessonDate: format(
        selectedDate.getTime() <= Date.now() ? selectedDate : new Date(),
        'yyyy-MM-dd',
      ),
      startTime: '18:00',
      endTime: '19:00',
      actualMinutes: 60,
      reason: '',
      records,
    })
    setHistoryConfirmed(false)
    setHistoryOpen(true)
  }

  const submitHistory = async () => {
    if (!selectedHistoryGroup) return message.warning('请选择需要补录的突击全能班')
    if (historyDraft.records.length !== selectedHistoryGroup.expectedStudents) {
      return message.warning(`该班型必须选择${selectedHistoryGroup.expectedStudents}名学生`)
    }
    if (!historyDraft.teacherId || !historyDraft.lessonDate || !historyDraft.startTime || !historyDraft.endTime) {
      return message.warning('请完整填写教师、日期和时间')
    }
    if (historyDraft.reason.trim().length < 4) return message.warning('请填写至少4个字的补录原因')
    if (!historyConfirmed) return message.warning('请确认本次补录会同步课时与工资')

    setHistorySaving(true)
    try {
      const response = await fetch(`/api/admin/intensive-history?division=${division}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(historyDraft),
      })
      const payload = await response.json().catch(() => ({}))
      if (!response.ok) throw new Error(payload.error || '历史补录失败')
      const deducted = Array.isArray(payload.deductions)
        ? payload.deductions
            .filter((item: { hours?: number }) => Number(item.hours) > 0)
            .map((item: { studentName?: string; hours?: number }) => `${item.studentName}${item.hours}小时`)
            .join('、')
        : ''
      message.success(
        `历史课次补录成功${deducted ? `，已扣：${deducted}` : ''}，工资￥${Number(payload.salaryAmount || 0).toFixed(2)}`,
      )
      setHistoryOpen(false)
      await Promise.all([mutateHistory(), mutate()])
    } catch (error) {
      message.error(error instanceof Error ? error.message : '历史补录失败')
    } finally {
      setHistorySaving(false)
    }
  }

  const handleReview = async (review: IntensiveReviewItem, action: 'APPROVE' | 'REJECT') => {
    const reviewNote = (reviewNotes[review.id] || '').trim()
    if (action === 'REJECT' && reviewNote.length < 2) {
      return message.warning('驳回时请填写原因，方便教师修改后重新提交')
    }
    setReviewingId(review.id)
    try {
      const response = await fetch(`/api/admin/intensive-reviews/${review.id}?division=${division}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action, reviewNote }),
      })
      const payload = await response.json().catch(() => ({}))
      if (!response.ok) throw new Error(payload.error || '审核失败')
      if (action === 'APPROVE') {
        const uncovered = Number(payload.uncoveredHours || 0)
        message.success(
          `已审核通过，计入${(review.actualMinutes / 60).toFixed(2)}小时，工资￥${Number(payload.salaryAmount || 0).toFixed(2)}`
          + (uncovered > 0 ? `；其中${uncovered.toFixed(2)}学生课时未被余额覆盖` : ''),
        )
      } else {
        message.success('已驳回，教师可以修改后重新提交')
      }
      setReviewNotes((current) => {
        const next = { ...current }
        delete next[review.id]
        return next
      })
      await Promise.all([mutateReviews(), mutateHistory(), mutate()])
    } catch (error) {
      message.error(error instanceof Error ? error.message : '审核失败')
    } finally {
      setReviewingId('')
    }
  }

  return (
    <PageLayout
      title="个性化排课"
      subtitle="突击全能班 · 1对1 / 1对2 / 1对3 约课 · 授课审核 · 课时与工资自动结算"
    >
      <div>
        {/* Hero：个性化排课驾驶舱（深墨绿鎏金 · 贵宾服务） */}
      <div style={{
        borderRadius: 18, overflow: 'hidden', marginBottom: 16,
        border: '1px solid #C9A45C',
        boxShadow: '0 10px 26px rgba(18,60,53,.25)',
        background: 'linear-gradient(150deg,#17352F 0%,#0E5E4E 55%,#0B4B40 100%)',
        padding: 16, color: '#F5F1E8',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8, flexWrap: 'wrap' }}>
          <span style={{
            display: 'inline-flex', alignItems: 'center', gap: 5,
            fontSize: 11, fontWeight: 700, letterSpacing: 1,
            color: '#F2E3B6', background: 'rgba(201,164,92,.16)',
            border: '1px solid rgba(201,164,92,.5)',
            padding: '3px 10px', borderRadius: 999, whiteSpace: 'nowrap',
          }}>
            <CrownOutlined /> 个性化排课 · 贵宾服务
          </span>
          <Button
            onClick={openHistory}
            style={{
              minHeight: 34, borderRadius: 999, fontSize: 12.5, fontWeight: 600,
              color: '#F2E3B6', background: 'rgba(201,164,92,.12)',
              border: '1px solid rgba(201,164,92,.55)',
            }}
          >
            <CalendarOutlined /> 历史课程补录
          </Button>
        </div>
        <div style={{ marginTop: 12, fontSize: 17, fontWeight: 800, color: '#F5F1E8', lineHeight: 1.4 }}>
          突击全能班 · 一对一 / 一对二 / 一对三
        </div>
        <div style={{ marginTop: 4, fontSize: 11.5, color: 'rgba(245,241,232,.72)', lineHeight: 1.6 }}>
          教师灵活约课 · 授课审核闭环 · 课时与工资自动结算
        </div>
        <div style={{ marginTop: 14, display: 'grid', gridTemplateColumns: 'repeat(4, minmax(0, 1fr))', gap: 8 }}>
          {[
            { label: '今日已排', value: intensiveCount, unit: '节' },
            { label: '待上课约课', value: pendingAppointments.length, unit: '节', highlight: pendingAppointments.length > 0 },
            { label: '待审核', value: pendingReviews.length, unit: '条', highlight: pendingReviews.length > 0 },
            { label: '可用桌位', value: spots.length, unit: '个' },
          ].map((it) => (
            <div key={it.label} style={{
              textAlign: 'center', padding: '9px 2px', borderRadius: 12,
              background: it.highlight ? 'linear-gradient(135deg,#F2E3B6,#D8BC7C)' : 'rgba(255,255,255,.08)',
              border: it.highlight ? '1px solid rgba(242,227,182,.7)' : '1px solid rgba(242,227,182,.18)',
            }}>
              <div style={{ fontSize: 18, fontWeight: 800, color: it.highlight ? '#123C35' : '#F5F1E8', fontVariantNumeric: 'tabular-nums' }}>
                {it.value}<span style={{ fontSize: 10.5, fontWeight: 600 }}> {it.unit}</span>
              </div>
              <div style={{ marginTop: 2, fontSize: 10, color: it.highlight ? 'rgba(18,60,53,.7)' : 'rgba(245,241,232,.6)' }}>{it.label}</div>
            </div>
          ))}
        </div>
      </div>

      <Card
        id="intensive-appointments"
        title={(
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10 }}>
            <span style={{ display: 'flex', alignItems: 'center', gap: 7, color: '#2B2110', fontWeight: 700 }}>
              <span style={{
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                width: 26, height: 26, borderRadius: 8,
                background: 'linear-gradient(155deg,#FFB84D,#E8784A)', color: '#fff', fontSize: 13,
              }}><CalendarOutlined /></span>
              教师约课记录
            </span>
            <Tag color={pendingAppointments.length ? 'orange' : 'green'} style={{ borderRadius: 999, margin: 0 }}>
              {pendingAppointments.length ? `${appointmentData?.total || pendingAppointments.length}节待上课/考勤` : '暂无待跟进约课'}
            </Tag>
          </div>
        )}
        style={{ marginBottom: 16, borderRadius: 16, border: '1px solid rgba(232,120,74,.14)', boxShadow: '0 2px 8px rgba(58,50,39,.05)' }}
        styles={{ body: { padding: isMobile ? 12 : 16 } }}
      >
        {!pendingAppointments.length ? (
          <div style={{
            borderRadius: 14, padding: '26px 18px', textAlign: 'center',
            background: 'linear-gradient(150deg,#FFFDF7,#FBF3E4)',
            border: '1px dashed rgba(201,164,92,.5)',
          }}>
            <div style={{
              width: 46, height: 46, margin: '0 auto 10px', borderRadius: 999,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              background: 'linear-gradient(135deg,#F2E3B6,#D8BC7C)', color: '#123C35', fontSize: 20,
            }}>
              <CrownOutlined />
            </div>
            <div style={{ color: '#2B2110', fontSize: 14, fontWeight: 700 }}>暂无教师新约的个性化课程</div>
            <div style={{ marginTop: 6, color: '#9A8E7A', fontSize: 12, lineHeight: 1.7, maxWidth: 320, margin: '6px auto 0' }}>
              教师发起约课后会第一时间出现在这里；如需补录历史课次，使用右上角「历史课程补录」。
            </div>
          </div>
        ) : (
          <div style={{
            display: 'grid',
            gridTemplateColumns: isMobile ? '1fr' : 'repeat(2, minmax(0, 1fr))',
            gap: 12,
          }}>
            {pendingAppointments.map((appointment) => {
              const highlighted = targetAppointmentLessonId === appointment.id
              return (
                <div
                  key={appointment.id}
                  id={`appointment-lesson-${appointment.id}`}
                  style={{
                    minWidth: 0,
                    borderRadius: 14,
                    padding: isMobile ? 12 : 14,
                    background: highlighted
                      ? 'linear-gradient(150deg,#123C35,#0E5E4E)'
                      : 'linear-gradient(150deg,#FFFDF7,#FDF6E9)',
                    border: highlighted ? '1px solid #C9A45C' : '1px solid rgba(201,164,92,.35)',
                    boxShadow: highlighted ? '0 6px 16px rgba(18,60,53,.2)' : '0 2px 8px rgba(58,50,39,.05)',
                    color: highlighted ? '#F5F1E8' : '#2B2110',
                  }}
                >
                  <div style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'flex-start',
                    gap: 10,
                  }}>
                    <div style={{ minWidth: 0 }}>
                      <Text strong style={{ display: 'block', overflowWrap: 'anywhere', fontSize: 15, color: highlighted ? '#F5F1E8' : '#2B2110' }}>
                        {appointment.groupName}
                      </Text>
                      <Text style={{ color: highlighted ? 'rgba(245,241,232,.75)' : '#9A8E7A', fontSize: 13 }}>
                        {appointment.teacherName} · {appointment.subject || '学科待确认'}
                      </Text>
                    </div>
                    <Tag
                      color={appointment.statusLabel === '待补交考勤' ? 'orange' : 'gold'}
                      style={{ borderRadius: 999, margin: 0, flexShrink: 0 }}
                    >
                      {appointment.statusLabel}
                    </Tag>
                  </div>
                  <div style={{
                    marginTop: 12,
                    padding: 12,
                    borderRadius: 10,
                    background: highlighted ? 'rgba(255,255,255,.07)' : 'rgba(232,120,74,.06)',
                    border: highlighted ? '1px solid rgba(242,227,182,.25)' : '1px solid rgba(232,120,74,.14)',
                    display: 'grid',
                    gridTemplateColumns: isMobile ? '1fr' : '1fr 1fr',
                    gap: 8,
                    fontSize: 13,
                  }}>
                    <div>
                      <Text type="secondary" style={{ color: highlighted ? 'rgba(245,241,232,.6)' : undefined }}>上课时间</Text>
                      <div style={{ fontWeight: 700, color: highlighted ? '#F2E3B6' : undefined }}>
                        {format(new Date(appointment.lessonDate), 'M月d日')} {appointment.startTime}-{appointment.endTime}
                      </div>
                    </div>
                    <div>
                      <Text type="secondary" style={{ color: highlighted ? 'rgba(245,241,232,.6)' : undefined }}>班型与学生</Text>
                      <div style={{ fontWeight: 700, color: highlighted ? '#F5F1E8' : undefined }}>
                        {appointment.teachingTypeLabel} · {appointment.students.map((student) => student.name).join('、') || '待确认'}
                      </div>
                    </div>
                  </div>
                  {appointment.note && (
                    <Text style={{ display: 'block', marginTop: 10, color: highlighted ? 'rgba(242,227,182,.75)' : '#9A8E7A', overflowWrap: 'anywhere' }}>
                      约课说明：{appointment.note}
                    </Text>
                  )}
                </div>
              )
            })}
          </div>
        )}
      </Card>

      <Card
        id="intensive-reviews"
        title={(
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10 }}>
            <span style={{ display: 'flex', alignItems: 'center', gap: 7, color: '#2B2110', fontWeight: 700 }}>
              <span style={{
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                width: 26, height: 26, borderRadius: 8,
                background: 'linear-gradient(155deg,#4CB782,#2E8E66)', color: '#fff', fontSize: 13,
              }}><CheckOutlined /></span>
              待审核授课记录
            </span>
            <Tag color={pendingReviews.length ? 'orange' : 'green'} style={{ borderRadius: 999, margin: 0 }}>
              {pendingReviews.length ? `${pendingReviews.length}条待处理` : '全部处理完成'}
            </Tag>
          </div>
        )}
        style={{ marginBottom: 16, borderRadius: 16, border: '1px solid rgba(62,142,110,.16)', boxShadow: '0 2px 8px rgba(58,50,39,.05)' }}
        styles={{ body: { padding: isMobile ? 12 : 16 } }}
      >
        {!pendingReviews.length ? (
          <div style={{
            borderRadius: 14, padding: '24px 18px', textAlign: 'center',
            background: 'linear-gradient(150deg,#F4FAF6,#EBF4EE)',
            border: '1px dashed rgba(62,142,110,.45)',
          }}>
            <div style={{
              width: 44, height: 44, margin: '0 auto 10px', borderRadius: 999,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              background: 'linear-gradient(135deg,#4CB782,#2E8E66)', color: '#fff', fontSize: 20,
            }}>
              <CheckOutlined />
            </div>
            <div style={{ color: '#285247', fontSize: 14, fontWeight: 700 }}>全部处理完成</div>
            <div style={{ marginTop: 6, color: '#7A8F83', fontSize: 12, lineHeight: 1.7, maxWidth: 320, margin: '6px auto 0' }}>
              教师完成个性化课程并提交考勤后，授课记录会进入这里，审核通过即累计课时并结算教师工资。
            </div>
          </div>
        ) : (
          <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : 'repeat(2, minmax(0, 1fr))', gap: 12 }}>
            {pendingReviews.map((review) => (
              <div
                key={review.id}
                id={`review-lesson-${review.lessonId}`}
                style={{
                  minWidth: 0,
                  borderRadius: 14,
                  padding: isMobile ? 12 : 14,
                  background: targetReviewLessonId === review.lessonId
                    ? 'linear-gradient(150deg,#FFF7EE,#FDF0DF)'
                    : '#FFFFFF',
                  border: targetReviewLessonId === review.lessonId
                    ? '1px solid rgba(232,120,74,.6)'
                    : '1px solid rgba(232,120,74,.2)',
                  boxShadow: '0 2px 8px rgba(58,50,39,.04)',
                }}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', gap: 10, alignItems: 'flex-start' }}>
                  <div style={{ minWidth: 0 }}>
                    <Text strong style={{ display: 'block', overflowWrap: 'anywhere', fontSize: 15, color: '#2B2110' }}>
                      {review.groupName}
                    </Text>
                    <Text style={{ color: '#9A8E7A', fontSize: 13 }}>
                      {review.subject} · {review.teacherName}
                    </Text>
                  </div>
                  <Tag color="orange" style={{ borderRadius: 999, margin: 0, flexShrink: 0 }}>待审核</Tag>
                </div>

                <div style={{
                  marginTop: 12,
                  padding: 12,
                  borderRadius: 10,
                  background: '#FFF8F4',
                  border: '1px solid rgba(232,120,74,.12)',
                  display: 'grid',
                  gridTemplateColumns: '1fr 1fr',
                  gap: 8,
                  fontSize: 13,
                }}>
                  <div>
                    <Text type="secondary">上课时间</Text>
                    <div style={{ fontWeight: 700 }}>{format(new Date(review.lessonDate), 'M月d日')} {review.startTime}-{review.endTime}</div>
                  </div>
                  <div>
                    <Text type="secondary">教师申报</Text>
                    <div style={{ fontWeight: 700 }}>{review.actualMinutes}分钟（{(review.actualMinutes / 60).toFixed(2)}小时）</div>
                  </div>
                </div>

                <div style={{ marginTop: 10, display: 'flex', gap: 6, flexWrap: 'wrap' }}>
                  {review.students.map((student) => (
                    <Tag key={student.id} style={{ borderRadius: 999, margin: 0 }}>
                      {student.name} · {student.status === 'PRESENT' ? '出勤' : student.status === 'LEAVE' ? '请假' : student.status === 'ABSENT' ? '缺勤' : '补课'}
                    </Tag>
                  ))}
                </div>

                {review.teacherNote && (
                  <Text style={{ display: 'block', marginTop: 10, color: '#9A8E7A', overflowWrap: 'anywhere' }}>
                    教师说明：{review.teacherNote}
                  </Text>
                )}

                <Input.TextArea
                  value={reviewNotes[review.id] || ''}
                  onChange={(event) => setReviewNotes((current) => ({
                    ...current,
                    [review.id]: event.target.value,
                  }))}
                  placeholder="审核备注（驳回时必填）"
                  rows={2}
                  maxLength={500}
                  style={{ marginTop: 12, resize: 'none', borderRadius: 10 }}
                />
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginTop: 10 }}>
                  <Button
                    danger
                    disabled={Boolean(reviewingId)}
                    onClick={() => handleReview(review, 'REJECT')}
                    style={{ minHeight: 42, borderRadius: 10 }}
                  >
                    驳回修改
                  </Button>
                  <Button
                    type="primary"
                    loading={reviewingId === review.id}
                    disabled={Boolean(reviewingId) && reviewingId !== review.id}
                    onClick={() => handleReview(review, 'APPROVE')}
                    style={{ minHeight: 42, borderRadius: 10, background: 'linear-gradient(135deg,#4CB782,#2E8E66)', border: 'none' }}
                  >
                    核对无误并通过
                  </Button>
                </div>
              </div>
            ))}
          </div>
        )}
      </Card>

      {/* Date navigation */}
      <div style={{ display: 'flex', alignItems: 'center', flexWrap: 'wrap', gap: 8, marginBottom: 12 }}>
        <button onClick={() => setSelectedDate(subDays(selectedDate, 1))}
          style={{ border: '1px solid rgba(201,164,92,.4)', borderRadius: 8, background: '#FFFDF7', padding: '5px 12px', cursor: 'pointer', fontSize: 14, color: '#A06E0B' }}>←</button>
        <div style={{ padding: '0 14px', height: 34, display: 'flex', alignItems: 'center', gap: 8,
          background: 'linear-gradient(135deg,#123C35,#0E5E4E)', border: '1px solid rgba(201,164,92,.5)', borderRadius: 10, fontSize: 14, fontWeight: 600, color: '#F5F1E8' }}>
          <CalendarOutlined style={{ color: '#F2E3B6' }} />
          {format(selectedDate, 'M月d日 EEEE', { locale: zhCN })}
        </div>
        <button onClick={() => setSelectedDate(addDays(selectedDate, 1))}
          style={{ border: '1px solid rgba(201,164,92,.4)', borderRadius: 8, background: '#FFFDF7', padding: '5px 12px', cursor: 'pointer', fontSize: 14, color: '#A06E0B' }}>→</button>
        <button onClick={() => setSelectedDate(new Date())}
          style={{ border: '1px solid rgba(201,164,92,.4)', borderRadius: 8, background: '#FFFDF7', padding: '5px 12px', cursor: 'pointer', fontSize: 12, color: '#A06E0B' }}>今天</button>
        <div style={{ marginLeft: 'auto', fontSize: 12, color: '#A06E0B', fontWeight: 700 }}>
          今日已排 <span style={{ fontSize: 15 }}>{intensiveCount}</span> 课时
        </div>
      </div>

      {/* 当日个性化课程时间线（替代桌位×小时矩阵课表） */}
      <Card
        title={(
          <span style={{ display: 'flex', alignItems: 'center', gap: 7, color: '#2B2110', fontWeight: 700 }}>
            <span style={{
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              width: 26, height: 26, borderRadius: 8,
              background: 'linear-gradient(155deg,#123C35,#0E5E4E)', color: '#F2E3B6', fontSize: 13,
            }}><ClockCircleOutlined /></span>
            当日个性化课程
          </span>
        )}
        extra={(
          <Button
            icon={<PlusOutlined />}
            onClick={openCreate}
            style={{ minHeight: 32, borderRadius: 999, fontSize: 12, fontWeight: 600, color: '#F2E3B6', background: 'linear-gradient(135deg,#123C35,#0E5E4E)', border: '1px solid rgba(201,164,92,.55)' }}
          >
            快捷排课
          </Button>
        )}
        style={{ marginBottom: 16, borderRadius: 16, border: '1px solid rgba(201,164,92,.2)', boxShadow: '0 2px 8px rgba(58,50,39,.05)' }}
        styles={{ body: { padding: isMobile ? 12 : 16 } }}
      >
        {isLoading ? (
          <div style={{ textAlign: 'center', padding: 60 }}><Spin size="large" /></div>
        ) : todayLessons.length === 0 ? (
          <div style={{
            borderRadius: 14, padding: '26px 18px', textAlign: 'center',
            background: 'linear-gradient(150deg,#FFFDF7,#FBF3E4)',
            border: '1px dashed rgba(201,164,92,.5)',
          }}>
            <div style={{
              width: 46, height: 46, margin: '0 auto 10px', borderRadius: 999,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              background: 'linear-gradient(135deg,#F2E3B6,#D8BC7C)', color: '#123C35', fontSize: 20,
            }}>
              <ClockCircleOutlined />
            </div>
            <div style={{ color: '#2B2110', fontSize: 14, fontWeight: 700 }}>今日暂无个性化课程排课</div>
            <div style={{ marginTop: 6, color: '#9A8E7A', fontSize: 12, lineHeight: 1.7, maxWidth: 320, margin: '6px auto 0' }}>
              点击右上角「快捷排课」选择桌位与时段，为学员安排一对一 / 一对二 / 一对三课程。
            </div>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            {todayLessons.map((item, index) => {
              const lesson = item.lesson
              const courseType = lesson.courseType || 'ONE_ON_ONE'
              const typeConfig = TYPE_CONFIG[courseType] || TYPE_CONFIG.ONE_ON_ONE
              const subject = lesson.subject || '其他学科'
              const palette = subjectStyle(subject)
              const startHM = item.slotStart.slice(0, 5)
              const endHM = item.slotEnd.slice(0, 5)
              return (
                <div key={lesson.lessonId || `${item.slotStart}-${index}`} style={{
                  display: 'flex', gap: 10, alignItems: 'stretch',
                  padding: '10px 12px', borderRadius: 14,
                  background: 'linear-gradient(150deg,#FFFDF7,#FDF6E9)',
                  border: '1px solid rgba(201,164,92,.35)',
                  boxShadow: '0 2px 8px rgba(58,50,39,.05)',
                }}>
                  <div style={{
                    width: 58, flexShrink: 0, borderRadius: 10,
                    background: 'linear-gradient(155deg,#123C35,#0E5E4E)',
                    border: '1px solid rgba(201,164,92,.55)',
                    display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
                    padding: '6px 0',
                  }}>
                    <div style={{ fontSize: 14, fontWeight: 800, color: '#F2E3B6', fontVariantNumeric: 'tabular-nums' }}>{startHM}</div>
                    <div style={{ fontSize: 9.5, color: 'rgba(242,227,182,.7)', marginTop: 1 }}>至 {endHM}</div>
                  </div>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 5, flexWrap: 'wrap' }}>
                      <span style={{ fontSize: 13.5, fontWeight: 700, color: '#2B2110', overflowWrap: 'anywhere' }}>
                        {lesson.courseName || '个性化课程'}
                      </span>
                      <span style={{
                        fontSize: 9.5, fontWeight: 700, color: typeConfig.color,
                        background: typeConfig.bg, padding: '1px 6px', borderRadius: 999, whiteSpace: 'nowrap',
                      }}>{typeConfig.label}</span>
                      <span style={{ fontSize: 9.5, fontWeight: 700, color: palette.color, background: palette.bg, padding: '1px 6px', borderRadius: 999, whiteSpace: 'nowrap' }}>{subject}</span>
                    </div>
                    <div style={{ marginTop: 5, display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap', color: '#5C4F3F', fontSize: 12 }}>
                      <span><TeamOutlined style={{ marginRight: 3, color: '#A06E0B' }} />{lesson.teacherName || '未分配教师'}</span>
                      <span><EnvironmentOutlined style={{ marginRight: 3, color: '#A06E0B' }} />{item.spot}</span>
                      <span style={{ color: '#9A8E7A' }}>{lesson.grade || '未填年级'} · {lesson.headcount || 1}人</span>
                    </div>
                  </div>
                </div>
              )
            })}
          </div>
        )}
      </Card>

      <BrandModal
        title="历史课程补录"
        open={historyOpen}
        onCancel={() => setHistoryOpen(false)}
        footer={null}
        width={isMobile ? '100%' : 620}
        style={isMobile ? { top: 0, margin: 0, padding: 0, maxWidth: '100vw' } : undefined}
        styles={{
          body: {
            maxHeight: isMobile ? 'calc(100dvh - 58px)' : '72vh',
            overflowY: 'auto',
            padding: isMobile ? '12px 14px calc(18px + env(safe-area-inset-bottom))' : 20,
          },
        }}
        destroyOnClose
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
          <Alert
            type="warning"
            showIcon
            message="历史补录属于财务操作"
            description="提交后会同时生成课次、考勤、课时扣减和教师工资，并记录管理员、补录时间与原因。不会自动生成课堂反馈或反馈奖励。"
            style={{ borderRadius: 10 }}
          />

          <div>
            <Text strong style={{ display: 'block', marginBottom: 5 }}>突击全能班 *</Text>
            <AdaptiveSelect
              showSearch
              optionFilterProp="label"
              value={historyDraft.groupId || undefined}
              onChange={selectHistoryGroup}
              options={historyGroups.map((group) => ({
                value: group.id,
                label: `${group.name} · ${TYPE_CONFIG[group.teachingType]?.label || group.teachingType}`,
              }))}
              placeholder={historyGroups.length ? '选择已有突击全能班' : '暂无可补录的突击全能班'}
              style={{ width: '100%', minHeight: 42 }}
              getPopupContainer={(trigger) => trigger.parentElement || document.body}
            />
          </div>

          {selectedHistoryGroup && (
            <>
              <div style={{
                display: 'grid',
                gridTemplateColumns: isMobile ? '1fr' : '1fr 1fr',
                gap: 12,
              }}>
                <div>
                  <Text strong style={{ display: 'block', marginBottom: 5 }}>授课教师 *</Text>
                  <AdaptiveSelect
                    value={historyDraft.teacherId || undefined}
                    onChange={(teacherId) => {
                      setHistoryDraft((current) => ({ ...current, teacherId }))
                      setHistoryConfirmed(false)
                    }}
                    options={selectedHistoryGroup.teachers.map((teacher) => ({
                      value: teacher.id,
                      label: `${teacher.name}${teacher.subject ? ` · ${teacher.subject}` : ''}`,
                    }))}
                    style={{ width: '100%' }}
                    getPopupContainer={(trigger) => trigger.parentElement || document.body}
                  />
                </div>
                <div>
                  <Text strong style={{ display: 'block', marginBottom: 5 }}>历史上课日期 *</Text>
                  <Input
                    type="date"
                    max={format(new Date(), 'yyyy-MM-dd')}
                    value={historyDraft.lessonDate}
                    onChange={(event) => {
                      setHistoryDraft((current) => ({
                        ...current,
                        lessonDate: event.target.value,
                      }))
                      setHistoryConfirmed(false)
                    }}
                    style={{ minHeight: 42 }}
                  />
                </div>
              </div>

              <div style={{
                display: 'grid',
                gridTemplateColumns: isMobile ? '1fr 1fr' : '1fr 1fr 1fr',
                gap: 10,
              }}>
                <div>
                  <Text strong style={{ display: 'block', marginBottom: 5 }}>开始时间 *</Text>
                  <Input
                    type="time"
                    value={historyDraft.startTime}
                    onChange={(event) => {
                      setHistoryDraft((current) => ({
                        ...current,
                        startTime: event.target.value,
                      }))
                      setHistoryConfirmed(false)
                    }}
                    style={{ minHeight: 42 }}
                  />
                </div>
                <div>
                  <Text strong style={{ display: 'block', marginBottom: 5 }}>结束时间 *</Text>
                  <Input
                    type="time"
                    value={historyDraft.endTime}
                    onChange={(event) => {
                      setHistoryDraft((current) => ({
                        ...current,
                        endTime: event.target.value,
                      }))
                      setHistoryConfirmed(false)
                    }}
                    style={{ minHeight: 42 }}
                  />
                </div>
                <div style={{ gridColumn: isMobile ? '1 / -1' : undefined }}>
                  <Text strong style={{ display: 'block', marginBottom: 5 }}>实际授课 *</Text>
                  <InputNumber
                    min={15}
                    max={600}
                    step={5}
                    addonAfter="分钟"
                    value={historyDraft.actualMinutes}
                    onChange={(actualMinutes) => {
                      setHistoryDraft((current) => ({
                        ...current,
                        actualMinutes: Number(actualMinutes) || 60,
                      }))
                      setHistoryConfirmed(false)
                    }}
                    style={{ width: '100%', minHeight: 42 }}
                  />
                </div>
              </div>

              <div>
                <Text strong style={{ display: 'block', marginBottom: 5 }}>
                  上课学生（必须选择{selectedHistoryGroup.expectedStudents}人）*
                </Text>
                <AdaptiveSelect
                  mode="multiple"
                  value={historyDraft.records.map((record) => record.studentId)}
                  onChange={(studentIds: string[]) => {
                    if (studentIds.length > selectedHistoryGroup.expectedStudents) {
                      message.warning(`最多选择${selectedHistoryGroup.expectedStudents}名学生`)
                      return
                    }
                    setHistoryDraft((current) => ({
                      ...current,
                      records: studentIds.map((studentId) => ({
                        studentId,
                        status: current.records.find((record) => record.studentId === studentId)?.status || 'PRESENT',
                      })),
                    }))
                    setHistoryConfirmed(false)
                  }}
                  options={selectedHistoryGroup.students.map((student) => ({
                    value: student.id,
                    label: `${student.name}（剩余${student.remainHours.toFixed(2)}小时）`,
                  }))}
                  maxTagCount="responsive"
                  style={{ width: '100%' }}
                  getPopupContainer={(trigger) => trigger.parentElement || document.body}
                />
              </div>

              <div style={{ display: 'grid', gap: 8 }}>
                {historyDraft.records.map((record) => {
                  const student = selectedHistoryGroup.students.find((item) => item.id === record.studentId)
                  const deductHours = record.status === 'PRESENT' || record.status === 'ABSENT'
                    ? historyDraft.actualMinutes / 60
                    : 0
                  return (
                    <div
                      key={record.studentId}
                      style={{
                        display: 'grid',
                        gridTemplateColumns: isMobile ? 'minmax(0, 1fr)' : 'minmax(0, 1fr) 210px',
                        gap: 8,
                        padding: 10,
                        borderRadius: 10,
                        border: '1px solid var(--color-border, #EEE7E1)',
                        background: '#FCFBF9',
                      }}
                    >
                      <div style={{ minWidth: 0 }}>
                        <Text strong>{student?.name || '学生'}</Text>
                        <Text type="secondary" style={{ display: 'block', fontSize: 12 }}>
                          当前剩余 {Number(student?.remainHours || 0).toFixed(2)} 小时 · 本次预计扣 {deductHours.toFixed(2)} 小时
                        </Text>
                      </div>
                      <Radio.Group
                        value={record.status}
                        onChange={(event) => {
                          const status = event.target.value as HistoryStatus
                          setHistoryDraft((current) => ({
                            ...current,
                            records: current.records.map((item) => (
                              item.studentId === record.studentId ? { ...item, status } : item
                            )),
                          }))
                          setHistoryConfirmed(false)
                        }}
                        style={{ display: 'grid', gridTemplateColumns: 'repeat(2, minmax(0, 1fr))', gap: 4, width: '100%' }}
                      >
                        <Radio.Button value="PRESENT" style={{ textAlign: 'center' }}>正常出勤（扣课）</Radio.Button>
                        <Radio.Button value="LEAVE" style={{ textAlign: 'center' }}>学生请假（不扣课）</Radio.Button>
                        <Radio.Button value="ABSENT" style={{ textAlign: 'center' }}>缺勤（扣课）</Radio.Button>
                        <Radio.Button value="MAKEUP" style={{ textAlign: 'center' }}>补课标记（不扣课）</Radio.Button>
                      </Radio.Group>
                    </div>
                  )
                })}
              </div>

              <div>
                <Text strong style={{ display: 'block', marginBottom: 5 }}>补录原因 *</Text>
                <Input.TextArea
                  rows={3}
                  maxLength={500}
                  showCount
                  value={historyDraft.reason}
                  onChange={(event) => {
                    setHistoryDraft((current) => ({ ...current, reason: event.target.value }))
                    setHistoryConfirmed(false)
                  }}
                  placeholder="例如：系统上线前已完成授课，根据原始考勤表补录"
                  style={{ resize: 'none' }}
                />
              </div>

              <Checkbox
                checked={historyConfirmed}
                onChange={(event) => setHistoryConfirmed(event.target.checked)}
              >
                我已核对原始考勤记录，并确认同步扣减课时、生成对应教师工资。
              </Checkbox>

              <div style={{
                display: 'grid',
                gridTemplateColumns: '1fr 1fr',
                gap: 10,
                paddingTop: 12,
                borderTop: '1px solid var(--color-border, #EEE7E1)',
              }}>
                <Button onClick={() => setHistoryOpen(false)} style={{ minHeight: 44, borderRadius: 10 }}>
                  取消
                </Button>
                <Button
                  type="primary"
                  loading={historySaving}
                  disabled={!historyConfirmed}
                  onClick={submitHistory}
                  style={{ minHeight: 44, borderRadius: 10, background: '#E8784A' }}
                >
                  确认补录并结算
                </Button>
              </div>
            </>
          )}
        </div>
      </BrandModal>

      {/* Create Modal */}
      <BrandModal title="安排突击全能班课程" open={createOpen}
        onCancel={() => setCreateOpen(false)} onOk={handleCreate}
        confirmLoading={saving} okText="确认排课" cancelText="取消" width={440}
        okButtonProps={{ style: { background: INTENSIVE_COLOR, borderColor: INTENSIVE_COLOR } }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12, paddingTop: 8 }}>
          <div>
            <Text strong style={{ fontSize: 12, display: 'block', marginBottom: 4 }}>桌位 *</Text>
            <MobileSelect
              placeholder="选择一对一桌位"
              style={{ width: '100%' }}
              value={createData.roomId || undefined}
              onChange={(value) => {
                const spot = spots.find((s) => s.id === value)
                setCreateData((current) => ({ ...current, roomId: value, roomName: (spot?.name as string) || '' }))
              }}
              options={spots.map((spot) => ({ label: spot.name as string, value: spot.id as string }))}
            />
            {spots.length === 0 && (
              <Text type="secondary" style={{ fontSize: 11, display: 'block', marginTop: 4 }}>
                暂无一对一桌位，请到系统设置 → 教室管理中添加类型为“一对一”的教室/桌位
              </Text>
            )}
          </div>
          <div>
            <Text strong style={{ fontSize: 12, display: 'block', marginBottom: 4 }}>时间 *</Text>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
              <div>
                <Text type="secondary" style={{ fontSize: 11, display: 'block', marginBottom: 4 }}>开始时间</Text>
                <Input
                  type="time"
                  value={createData.startTime}
                  onChange={(event) => setCreateData((current) => ({ ...current, startTime: event.target.value }))}
                  style={{ minHeight: 42 }}
                />
              </div>
              <div>
                <Text type="secondary" style={{ fontSize: 11, display: 'block', marginBottom: 4 }}>结束时间</Text>
                <Input
                  type="time"
                  value={createData.endTime}
                  onChange={(event) => setCreateData((current) => ({ ...current, endTime: event.target.value }))}
                  style={{ minHeight: 42 }}
                />
              </div>
            </div>
          </div>
          <div>
            <Text strong style={{ fontSize: 12, display: 'block', marginBottom: 4 }}>班型 *</Text>
            <Radio.Group
              value={createData.teachingType}
              onChange={(event) => setCreateData((current) => ({ ...current, teachingType: event.target.value, studentIds: [] }))}
              optionType="button"
              buttonStyle="solid"
              options={[
                { label: '一对一', value: 'ONE_ON_ONE' },
                { label: '一对二', value: 'ONE_ON_TWO' },
                { label: '一对三', value: 'ONE_ON_THREE' },
              ]}
            />
          </div>
          <div>
            <Text strong style={{ fontSize: 12, display: 'block', marginBottom: 4 }}>老师 *</Text>
            <MobileSelect placeholder="选择老师" style={{ width: '100%' }}
              value={createData.teacherId || undefined} onChange={v => setCreateData(p => ({ ...p, teacherId: v }))}
              searchable={teacherList.length > 10}
              options={teacherList.map((t: Record<string, unknown>) => ({ label: t.name as string, value: t.id as string }))} />
          </div>
          <div>
            <Text strong style={{ fontSize: 12, display: 'block', marginBottom: 4 }}>学员（需要 {getPersonalClassLimit(createData.teachingType)} 人）*</Text>
            <AdaptiveSelect mode="multiple" placeholder="选择学员" style={{ width: '100%' }}
              value={createData.studentIds} onChange={(value: string[]) => {
                const limit = getPersonalClassLimit(createData.teachingType)
                if (value.length > limit) return message.warning(`最多选择${limit}名学员`)
                setCreateData((current) => ({ ...current, studentIds: value }))
              }}
              showSearch={studentList.length > 10}
              filterOption={(input, option) => String(option?.label ?? '').toLowerCase().includes(input.toLowerCase())}
              options={studentList.map((s: Record<string, unknown>) => ({ label: `${s.name}${s.grade ? ` (${s.grade})` : ''}`, value: s.id as string }))} />
          </div>
          <div>
            <Text strong style={{ fontSize: 12, display: 'block', marginBottom: 4 }}>课程/科目 *</Text>
            <AdaptiveSelect showSearch optionFilterProp="label" placeholder="选择课程" style={{ width: '100%' }}
              value={createData.courseId || undefined} onChange={(value) => setCreateData((current) => ({ ...current, courseId: value }))}
              options={courseList.map((course) => ({ label: `${course.name}${course.subject ? ` · ${course.subject}` : ''}`, value: course.id as string }))} />
          </div>
          {conflictMsg && (
            <div style={{ background: 'rgba(226,75,74,.08)', border: '1px solid rgba(226,75,74,.2)', borderRadius: 6, padding: 10, fontSize: 11, color: '#E24B4A' }}>
              {conflictMsg}
            </div>
          )}
        </div>
      </BrandModal>
    </div>
    </PageLayout>
  )
}

'use client'

import { Suspense, useEffect, useState } from 'react'
import { useRouter, useSearchParams } from 'next/navigation'
import dynamic from 'next/dynamic'
import { Button, Card, Input, Spin, message } from 'antd'
import { BrandModal } from '@/components/Common/BrandModal'
import { format, startOfWeek } from 'date-fns'
import useSWR from 'swr'
import { PageLayout } from '@/components/Layout/PageLayout'
import { ClassMatrixView } from './ClassMatrixView'
import { useIsMobile } from '@/hooks/useIsMobile'
import { useDivision } from '@/contexts/DivisionContext'
import { useSWRConfig } from 'swr'
import {
  ApartmentOutlined, AppstoreOutlined, CalendarOutlined, CloseCircleOutlined,
  CrownOutlined, EnvironmentOutlined, HeatMapOutlined, PlusOutlined, TeamOutlined,
} from '@ant-design/icons'
import { OneOnOneView } from './OneOnOneView'

const RoomMatrixView = dynamic(() => import('./RoomMatrixView').then((module) => module.RoomMatrixView))
const TeacherWeekView = dynamic(() => import('./TeacherWeekView').then((module) => module.TeacherWeekView))
const WeekHeatmapView = dynamic(() => import('./WeekHeatmapView').then((module) => module.WeekHeatmapView))
const MobileRoomView = dynamic(() => import('./MobileRoomView').then((module) => module.MobileRoomView))
const OneOnOneModal = dynamic(() => import('./OneOnOneModal').then((module) => module.OneOnOneModal))
const ScheduleDetailPanel = dynamic(() => import('./_components/ScheduleDetailPanel').then((module) => module.ScheduleDetailPanel))

const VIEW_TABS = [
  { key: 'class-matrix', label: '班级课表', icon: <AppstoreOutlined /> },
  { key: 'room-matrix', label: '教室矩阵', icon: <EnvironmentOutlined /> },
  { key: 'teacher-week', label: '教师课表', icon: <TeamOutlined /> },
  { key: 'one-on-one', label: 'VIP课程', icon: <CrownOutlined /> },
  { key: 'week-heatmap', label: '周总览', icon: <HeatMapOutlined /> },
]

const fetchJson = async (url: string) => {
  const res = await fetch(url)
  const payload = await res.json().catch(() => ({}))
  if (!res.ok) throw new Error(payload.error || '加载失败')
  return payload
}

export default function SchedulePage() {
  return (
    <Suspense fallback={<div style={{ padding: 80, textAlign: 'center' }}><Spin size="large" /></div>}>
      <SchedulePageInner />
    </Suspense>
  )
}

function SchedulePageInner() {
  const searchParamsHook = useSearchParams()
  const router = useRouter()
  const isMobile = useIsMobile() ?? false
  const { division } = useDivision()
  const { mutate: mutateSWR } = useSWRConfig()
  const requestedView = searchParamsHook.get('view')
  const urlView = VIEW_TABS.some((tab) => tab.key === requestedView) ? requestedView! : 'class-matrix'

  const [viewMode, setViewMode] = useState(urlView)
  useEffect(() => setViewMode(urlView), [urlView])
  const switchView = (nextView: string) => {
    setViewMode(nextView)
    const params = new URLSearchParams(searchParamsHook.toString())
    if (nextView === 'class-matrix') params.delete('view')
    else params.set('view', nextView)
    const query = params.toString()
    window.history.pushState(null, '', query ? `/schedule?${query}` : '/schedule')
  }
  const [oneOnOneOpen, setOneOnOneOpen] = useState(false)
  const [oneOnOneDate] = useState(format(new Date(), 'yyyy-MM-dd'))
  const [selectedDate, setSelectedDate] = useState(new Date())
  const [weekStart, setWeekStart] = useState(startOfWeek(new Date(), { weekStartsOn: 1 }))
  const [selectedLesson, setSelectedLesson] = useState<Record<string, unknown> | null>(null)
  const [editLesson, setEditLesson] = useState<Record<string, string>>({})
  const [savingLesson, setSavingLesson] = useState(false)
  const [cancelLessonId, setCancelLessonId] = useState('')
  const [cancelReason, setCancelReason] = useState('')
  const [cancelling, setCancelling] = useState(false)

  const { data: overviewData } = useSWR(
    `/api/schedules/overview?division=${encodeURIComponent(division)}`,
    fetchJson,
    { refreshInterval: 60_000 },
  )
  const overview = (overviewData as { data?: Record<string, number> } | undefined)?.data

  const handleRoomCellClick = (_room: Record<string, unknown>, _period: unknown) => {
    router.push(`/schedule/workbench?action=extra&date=${encodeURIComponent(format(selectedDate, 'yyyy-MM-dd'))}`)
  }

  const handleLessonClick = (lesson: Record<string, unknown>) => {
    setSelectedLesson(lesson)
    setEditLesson({
      lessonDate: format(new Date(lesson.lessonDate as string), 'yyyy-MM-dd'),
      startTime: String(lesson.startTime || ''),
      endTime: String(lesson.endTime || ''),
      teacherId: String((lesson.teacher as Record<string, unknown> | undefined)?.id || lesson.teacherId || ''),
      subject: String(lesson.subject || ''),
      status: String(lesson.status || 'SCHEDULED'),
    })
  }

  const handleHeatmapCellClick = (date: Date) => {
    setSelectedDate(date)
    switchView('class-matrix')
  }

  const saveLesson = async () => {
    if (!selectedLesson?.id) return
    setSavingLesson(true)
    try {
      const res = await fetch(`/api/class-lessons/${selectedLesson.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(editLesson),
      })
      const payload = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(payload.error || '保存失败')
      message.success('课次已更新')
      setSelectedLesson(null)
      mutateSWR(key => typeof key === 'string' && (key.startsWith('/api/schedules/') || key.startsWith('/api/class-lessons/')))
    } catch (error) {
      message.error(error instanceof Error ? error.message : '保存失败')
    } finally {
      setSavingLesson(false)
    }
  }

  const cancelLesson = async (id: string) => {
    setCancelLessonId(id)
    setCancelReason('')
  }

  const confirmCancelLesson = async () => {
    if (cancelReason.trim().length < 2) {
      message.warning('请填写停课原因')
      return
    }
    setCancelling(true)
    try {
      const res = await fetch(`/api/class-lessons/${cancelLessonId}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'CANCELLED', cancelReason: cancelReason.trim() }),
      })
      const payload = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(payload.error || '取消失败')
      message.success(payload.notifiedParents > 0
        ? `本次课已取消，已通知 ${payload.notifiedParents} 位家长`
        : '本次课已取消，课表已更新')
      setSelectedLesson(null)
      setCancelLessonId('')
      mutateSWR(key => typeof key === 'string' && (key.startsWith('/api/schedules/') || key.startsWith('/api/class-lessons/')))
    } catch (error) {
      message.error(error instanceof Error ? error.message : '取消失败')
    } finally {
      setCancelling(false)
    }
  }

  return (
    <PageLayout
      title="排课系统"
      subtitle="今日课次 · 教室矩阵 · 教师课表 · VIP课程 · 周总览"
    >
      {/* 综合概览大卡 */}
      <div style={{
        borderRadius: 16,
        background: 'linear-gradient(135deg,#123C35 0%,#0E5E4E 60%,#0B4B40 100%)',
        boxShadow: '0 8px 24px rgba(14,94,78,.18)',
        padding: isMobile ? '14px' : '18px 22px',
        marginBottom: 12,
        overflow: 'hidden',
      }}>
        <div style={{ display: 'flex', alignItems: 'stretch', gap: isMobile ? 10 : 24, flexWrap: isMobile ? 'wrap' : 'nowrap' }}>
          <div style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, color: 'rgba(242,227,182,.8)', fontSize: isMobile ? 11.5 : 13, fontWeight: 600, letterSpacing: 1 }}>
              <CalendarOutlined /> 本周排课总览
            </div>
            <div style={{ display: 'flex', alignItems: 'baseline', gap: 6, marginTop: 6 }}>
              <span style={{ color: '#F7F3E8', fontSize: isMobile ? 34 : 44, fontWeight: 800, fontVariantNumeric: 'tabular-nums', lineHeight: 1 }}>{overview?.weekTotal ?? 0}</span>
              <span style={{ color: 'rgba(242,227,182,.7)', fontSize: isMobile ? 12 : 14, fontWeight: 600 }}>节课次</span>
            </div>
            <div style={{ marginTop: 6, display: 'flex', gap: isMobile ? 10 : 18, flexWrap: 'wrap', color: 'rgba(247,243,232,.72)', fontSize: isMobile ? 10.5 : 12 }}>
              <span><CalendarOutlined style={{ marginRight: 3 }} />今日 {overview?.todayTotal ?? 0} 节</span>
              <span><CloseCircleOutlined style={{ marginRight: 3 }} />今日取消 {overview?.todayCancelled ?? 0}</span>
              <span><CloseCircleOutlined style={{ marginRight: 3 }} />本周取消 {overview?.weekCancelled ?? 0}</span>
            </div>
          </div>
          <div style={{
            display: 'grid',
            gridTemplateColumns: isMobile ? 'repeat(3, minmax(0,1fr))' : 'repeat(3, minmax(0,120px))',
            gap: isMobile ? 8 : 14,
            borderLeft: isMobile ? 'none' : '1px solid rgba(242,227,182,.22)',
            borderTop: isMobile ? '1px solid rgba(242,227,182,.22)' : 'none',
            paddingLeft: isMobile ? 0 : 24,
            paddingTop: isMobile ? 10 : 0,
            width: isMobile ? '100%' : 'auto',
          }}>
            {[
              { label: '活跃教室', value: overview?.activeRooms ?? 0, icon: <EnvironmentOutlined /> },
              { label: '上课教师', value: overview?.weekTeachers ?? 0, icon: <TeamOutlined /> },
              { label: '运行班级', value: overview?.runningGroups ?? 0, icon: <ApartmentOutlined /> },
            ].map((item) => (
              <div key={item.label} style={{ display: 'flex', flexDirection: 'column', alignItems: isMobile ? 'center' : 'flex-start', gap: 4, minWidth: 0 }}>
                <span style={{ color: 'rgba(242,227,182,.75)', fontSize: isMobile ? 11 : 12 }}>{item.icon} {item.label}</span>
                <span style={{ color: '#F7F3E8', fontSize: isMobile ? 20 : 26, fontWeight: 800, fontVariantNumeric: 'tabular-nums' }}>{item.value}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      <Card variant="borderless" style={{ marginBottom: 12, borderRadius: 14, background: '#ffffff', border: '1px solid #EDE9E1', boxShadow: '0 2px 8px rgba(23,47,41,.05)' }} styles={{ body: { padding: '10px 14px' } }}>
        <div className="mobile-scroll-x" style={{ display: 'flex', gap: 6, alignItems: 'center', flexWrap: isMobile ? 'nowrap' : 'wrap', overflowX: isMobile ? 'auto' : undefined }}>
          {VIEW_TABS.map(tab => (
            <button
              key={tab.key}
              onClick={() => {
                switchView(tab.key)
              }}
              style={{
                display: 'inline-flex', alignItems: 'center', gap: 6,
                padding: isMobile ? '7px 12px' : '8px 18px',
                border: viewMode === tab.key ? '1px solid rgba(14,94,78,.45)' : '1px solid #EEE7E1',
                borderRadius: 999,
                background: viewMode === tab.key ? 'linear-gradient(135deg,#123C35,#0E5E4E)' : '#FAF8F4',
                color: viewMode === tab.key ? '#F2E3B6' : '#5A6472',
                fontWeight: viewMode === tab.key ? 700 : 500,
                fontSize: 13,
                cursor: 'pointer',
                transition: 'all .18s',
                whiteSpace: 'nowrap',
                flexShrink: 0,
                boxShadow: viewMode === tab.key ? '0 3px 10px rgba(14,94,78,.25)' : 'none',
              }}
            >
              {tab.icon}
              {tab.label}
            </button>
          ))}
        </div>
      </Card>

      <div style={{ maxWidth: '100%' }}>
        {viewMode === 'class-matrix' ? (
          <ClassMatrixView selectedDate={selectedDate} setSelectedDate={setSelectedDate} onLessonClick={handleLessonClick} />
        ) : viewMode === 'room-matrix' && isMobile ? (
          <MobileRoomView selectedDate={selectedDate} setSelectedDate={setSelectedDate}
            onNewCourseClick={() => router.push(`/schedule/workbench?action=extra&date=${encodeURIComponent(format(selectedDate, 'yyyy-MM-dd'))}`)} onLessonClick={handleLessonClick} />
        ) : viewMode === 'room-matrix' ? (
          <div style={{ overflowX: 'auto' }}>
            <RoomMatrixView selectedDate={selectedDate} setSelectedDate={setSelectedDate}
              onCellClick={handleRoomCellClick} onLessonClick={handleLessonClick}
              onNewCourseClick={() => router.push(`/schedule/workbench?action=extra&date=${encodeURIComponent(format(selectedDate, 'yyyy-MM-dd'))}`)} />
          </div>
        ) : viewMode === 'teacher-week' ? (
          <TeacherWeekView onLessonClick={handleLessonClick} />
        ) : viewMode === 'one-on-one' ? (
          <OneOnOneView selectedDate={selectedDate} setSelectedDate={setSelectedDate} onLessonClick={handleLessonClick} />
        ) : viewMode === 'week-heatmap' ? (
          <WeekHeatmapView weekStart={weekStart} setWeekStart={setWeekStart} onCellClick={handleHeatmapCellClick} />
        ) : null}
      </div>

      {selectedLesson && <ScheduleDetailPanel
        selectedLesson={selectedLesson}
        editLesson={editLesson}
        setEditLesson={setEditLesson}
        savingLesson={savingLesson}
        onClose={() => setSelectedLesson(null)}
        onSave={saveLesson}
        onCancel={cancelLesson}
      />}

      <BrandModal
        title="取消本次课"
        open={Boolean(cancelLessonId)}
        onCancel={() => setCancelLessonId('')}
        onOk={confirmCancelLesson}
        confirmLoading={cancelling}
        okText="确认取消"
        okButtonProps={{ danger: true }}
      >
        <p>仅能取消尚未开始、未产生考勤或结算的课次。取消后保留课次记录，并通知相关家长。</p>
        <Input.TextArea aria-label="停课原因" placeholder="请输入停课原因，例如：国庆假期调整" value={cancelReason} onChange={(event) => setCancelReason(event.target.value)} maxLength={200} showCount rows={3} />
      </BrandModal>

      {oneOnOneOpen && <OneOnOneModal open={oneOnOneOpen} onClose={() => setOneOnOneOpen(false)}
        defaultDate={oneOnOneDate} onSuccess={() => setOneOnOneOpen(false)} />}
    </PageLayout>
  )
}

'use client'

import { useMemo, useState, type ReactNode } from 'react'
import useSWR from 'swr'
import { useSWRConfig } from 'swr'
import { useRouter } from 'next/navigation'
import dayjs, { type Dayjs } from 'dayjs'
import { Alert, Button, Card, DatePicker, Empty, Input, Popconfirm, Select, Space, Tag, message } from 'antd'
import {
  ArrowLeftOutlined, CalendarOutlined, CheckCircleOutlined, ClockCircleOutlined,
  CrownOutlined, PlusOutlined, ReloadOutlined, TeamOutlined, UserSwitchOutlined,
} from '@ant-design/icons'
import { PageLayout } from '@/components/Layout/PageLayout'
import { AdaptiveSelect } from '@/components/AdaptiveSelect'
import { ManualLessonModal } from '@/app/(main)/schedule/_components/ManualLessonModal'
import { ScheduleFormModal } from '@/app/(main)/schedule/_components/ScheduleFormModal'
import { CopyFridayToSaturdayModal } from '@/app/(main)/schedule/_components/CopyFridayToSaturdayModal'
import { SchedulePeriodSettingsModal } from '@/app/(main)/schedule/_components/SchedulePeriodSettingsModal'
import { useDivision } from '@/contexts/DivisionContext'
import { useIsMobile } from '@/hooks/useIsMobile'
import { useSchedulePeriods } from '@/hooks/useSchedulePeriods'

type ActionKey = 'move-date' | 'extra' | 'new' | 'copy' | 'teachers' | 'hours' | 'periods'
type Group = {
  id: string
  name: string
  status: string
  teacherId: string | null
  teacher?: { id: string; name: string } | null
  term?: { name: string; status: string } | null
  course?: { name: string; subject: string | null; grade: string | null } | null
  teacherAssignments?: Array<{ teacherId: string; subject: string | null; teacher?: { id: string; name: string } | null }>
  enrollments?: Array<{
    id: string
    studentId: string
    subjects: string[]
    remainHours: number
    usedHours: number
    totalHours: number
    enrolledAt: string
    student?: { name: string } | null
  }>
  lessonMinutes?: number
}
type Teacher = { id: string; name: string }

const fetchJson = async (url: string) => {
  const response = await fetch(url)
  const payload = await response.json().catch(() => ({}))
  if (!response.ok) throw new Error(payload.error || '数据加载失败')
  return payload
}

const actionItems: Array<{ key: ActionKey; label: string; description: string; icon: ReactNode }> = [
  { key: 'move-date', label: '调整上课日', description: '按原课表补入目标日期，并按规则处理替换日', icon: <CalendarOutlined /> },
  { key: 'extra', label: '现有班级临时加课', description: '为已开班的某个科目新增一次课', icon: <PlusOutlined /> },
  { key: 'new', label: '新建课次', description: '创建独立课程或个性化课次', icon: <CalendarOutlined /> },
  { key: 'copy', label: '周五复制到周六', description: '先检查冲突，再批量复制课次安排', icon: <CheckCircleOutlined /> },
  { key: 'teachers', label: '教师更换', description: '查看当前授课老师并调整后续课次', icon: <UserSwitchOutlined /> },
  { key: 'hours', label: '学生课时', description: '查看学生余额并按科目校准插班生课时', icon: <ClockCircleOutlined /> },
  { key: 'periods', label: '时间段设置', description: '管理常规课、寒假班和暑假班课时段', icon: <ClockCircleOutlined /> },
]

export function ScheduleWorkbench({ initialGroupId, initialAction, initialDate }: { initialGroupId?: string; initialAction?: string; initialDate?: string }) {
  const router = useRouter()
  const isMobile = useIsMobile() ?? false
  const { division } = useDivision()
  const { mutate: mutateCache } = useSWRConfig()
  const [groupId, setGroupId] = useState(initialGroupId || '')
  const initialKey = actionItems.some((item) => item.key === initialAction) ? initialAction as ActionKey : 'move-date'
  const initialDay = initialDate && dayjs(initialDate).isValid() ? dayjs(initialDate) : dayjs()
  const [activeAction, setActiveAction] = useState<ActionKey>(initialKey)
  const [moveDate, setMoveDate] = useState<Dayjs | null>(initialDay)
  const [moving, setMoving] = useState(false)
  const [syncing, setSyncing] = useState(false)
  const [oldTeacherKey, setOldTeacherKey] = useState('')
  const [newTeacherId, setNewTeacherId] = useState<string>()
  const [replaceNote, setReplaceNote] = useState('')
  const [replacing, setReplacing] = useState(false)
  const [addTeacherId, setAddTeacherId] = useState<string>()
  const [addTeacherSubject, setAddTeacherSubject] = useState('')
  const [addingTeacher, setAddingTeacher] = useState(false)
  const initialModal = initialAction === 'extra' || initialAction === 'new' || initialAction === 'copy' || initialAction === 'periods' ? initialAction : null
  const [modal, setModal] = useState<'extra' | 'new' | 'copy' | 'periods' | null>(initialModal)
  const { periods, mutate: mutatePeriods } = useSchedulePeriods(division)

  const { data: groupRows, error: groupsError, isLoading: groupsLoading, mutate: mutateGroups } = useSWR<Group[]>(
    `/api/class-groups?division=${encodeURIComponent(division)}`,
    fetchJson,
    { refreshInterval: 30_000, revalidateOnFocus: true, revalidateOnReconnect: true },
  )
  const { data: group, error: groupError, isLoading: groupLoading, mutate: mutateGroup } = useSWR<Group>(
    groupId ? `/api/class-groups/${groupId}` : null,
    fetchJson,
    { revalidateOnFocus: true },
  )
  const {
    data: teacherData,
    error: teacherError,
    isLoading: teachersLoading,
    mutate: mutateTeachers,
  } = useSWR('/api/teachers?status=ACTIVE', fetchJson)
  const teachers: Teacher[] = Array.isArray(teacherData?.teachers) ? teacherData.teachers : Array.isArray(teacherData) ? teacherData : []
  const activeGroups = Array.isArray(groupRows) ? groupRows.filter((item) => item.status !== 'ARCHIVED') : []
  const historical = group?.term?.status !== 'ACTIVE'

  const assignments = useMemo(() => {
    const rows = Array.isArray(group?.teacherAssignments) ? group.teacherAssignments : []
    if (rows.length) return rows.map((item) => ({
      teacherId: item.teacherId,
      teacherName: item.teacher?.name || '教师待定',
      subject: item.subject || group?.course?.subject || '主讲',
    }))
    return group?.teacherId ? [{ teacherId: group.teacherId, teacherName: group.teacher?.name || '教师待定', subject: group.course?.subject || '主讲' }] : []
  }, [group])
  const replacementOptions = teachers.filter((teacher) => teacher.id !== oldTeacherKey.split('::')[0]).map((teacher) => ({ value: teacher.id, label: teacher.name }))
  const teacherOptions = teachers.map((teacher) => ({ value: teacher.id, label: teacher.name }))
  const selectedAssignment = assignments.find((item) => `${item.teacherId}::${item.subject}` === oldTeacherKey)
  const enrollments = Array.isArray(group?.enrollments) ? group.enrollments : []

  const changeGroup = (value: string) => {
    setGroupId(value)
    setOldTeacherKey('')
    setNewTeacherId(undefined)
  }

  const refreshGroupData = async () => {
    await Promise.all([
      mutateGroup(),
      mutateGroups(),
      mutateCache((key) => typeof key === 'string' && (key.startsWith('/api/class-lessons') || key.startsWith('/api/schedules'))),
    ])
  }

  const moveClassDate = async () => {
    if (!groupId || !moveDate) return message.warning('先选择班级和调整日期')
    if (historical) return message.error('历史批次只允许查看，不能调整课次')
    setMoving(true)
    try {
      const response = await fetch('/api/class-lessons/add-day', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ date: moveDate.format('YYYY-MM-DD'), division, groupIds: [groupId], keepPlannedTotal: true }),
      })
      const payload = await response.json().catch(() => ({}))
      if (!response.ok) throw new Error(payload.error || '调整上课日失败')
      const created = Number(payload.createdLessons || 0)
      const replaced = Number(payload.replacedLessons || 0)
      message.success(`已处理「${group?.name || '当前班级'}」：新增 ${created} 节，按规则替换 ${replaced} 节`)
      await refreshGroupData()
    } catch (error) {
      message.error(error instanceof Error ? error.message : '调整上课日失败')
    } finally {
      setMoving(false)
    }
  }

  const replaceTeacher = async () => {
    if (!groupId || !selectedAssignment || !newTeacherId) return message.warning('请选择原任课安排和新老师')
    setReplacing(true)
    try {
      const response = await fetch(`/api/class-groups/${groupId}/replace-teacher`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          oldTeacherId: selectedAssignment.teacherId,
          newTeacherId,
          subject: selectedAssignment.subject === '主讲' ? null : selectedAssignment.subject,
          note: replaceNote.trim() || undefined,
        }),
      })
      const payload = await response.json().catch(() => ({}))
      if (!response.ok) throw new Error(payload.error || '更换老师失败')
      message.success(`已更换任课老师，更新 ${payload.affectedLessons || 0} 节未完成课次`)
      setOldTeacherKey('')
      setNewTeacherId(undefined)
      setReplaceNote('')
      await refreshGroupData()
    } catch (error) {
      message.error(error instanceof Error ? error.message : '更换老师失败')
    } finally {
      setReplacing(false)
    }
  }

  const syncStudentHours = async () => {
    if (!groupId) return message.warning('先选择班级')
    setSyncing(true)
    try {
      const response = await fetch(`/api/class-groups/${groupId}/sync-hours`, { method: 'POST' })
      const payload = await response.json().catch(() => ({}))
      if (!response.ok) throw new Error(payload.error || '课时校准失败')
      message.success(payload.message || `已校准 ${payload.updated || 0} 位插班生课时`)
      await mutateGroup()
    } catch (error) {
      message.error(error instanceof Error ? error.message : '课时校准失败')
    } finally {
      setSyncing(false)
    }
  }

  const addTeacherAssignment = async () => {
    if (!groupId || !addTeacherId || !addTeacherSubject) return message.warning('请选择老师和科目')
    setAddingTeacher(true)
    try {
      const response = await fetch(`/api/class-groups/${groupId}/add-teacher`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ teacherId: addTeacherId, subject: addTeacherSubject }),
      })
      const payload = await response.json().catch(() => ({}))
      if (!response.ok) throw new Error(payload.error || '添加任课老师失败')
      message.success(`已添加 ${addTeacherSubject} 任课老师`)
      setAddTeacherId(undefined)
      setAddTeacherSubject('')
      await refreshGroupData()
    } catch (error) {
      message.error(error instanceof Error ? error.message : '添加任课老师失败')
    } finally {
      setAddingTeacher(false)
    }
  }

  const groupOptions = activeGroups.map((item) => ({
    value: item.id,
    label: `${item.name} · ${item.course?.name || '课程'} · ${item.status === 'ACTIVE' ? '在读' : '待开班'}`,
  }))

  return (
    <PageLayout
      title="排课与课时工作台"
      subtitle="把调课、临时加课、教师安排与学生课时放在同一处管理；每项操作仍按原业务规则记录。"
    >
      <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : 'minmax(260px, 1.1fr) minmax(260px, 1fr)', gap: 12, marginBottom: 16 }}>
        <Card bordered={false} style={{ borderRadius: 14, border: '1px solid var(--color-hairline)', background: 'var(--color-surface-1)' }}>
          <div style={{ fontSize: 12, color: 'var(--color-ink-muted)', marginBottom: 7 }}>先选择班级</div>
          {groupsError ? <Alert type="error" showIcon message="班级清单加载失败" description={groupsError.message} action={<Button size="small" icon={<ReloadOutlined />} onClick={() => void mutateGroups()}>重试</Button>} /> : (
            <AdaptiveSelect
              showSearch={!isMobile}
              optionFilterProp="label"
              placeholder={groupsLoading ? '正在加载班级…' : '搜索班级或课程'}
              value={groupId || undefined}
              options={groupOptions}
              onChange={changeGroup}
              listHeight={260}
              virtual={false}
              style={{ width: '100%' }}
              getPopupContainer={(trigger) => trigger.parentElement || document.body}
            />
          )}
          {groupId && group && (
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginTop: 10 }}>
              <Tag color={group.status === 'ACTIVE' ? 'green' : 'gold'}>{group.status === 'ACTIVE' ? '在读' : '待开班'}</Tag>
              {group.course?.grade && <Tag>{group.course.grade}</Tag>}
              {group.term?.name && <Tag>{group.term.name}</Tag>}
              <span style={{ color: 'var(--color-ink-muted)', fontSize: 12, alignSelf: 'center' }}>{group.course?.name || '课程'} · {enrollments.length} 名学员</span>
            </div>
          )}
        </Card>
        <Card bordered={false} style={{ borderRadius: 14, border: '1px solid var(--color-hairline)', background: 'var(--color-surface-1)' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 9, color: 'var(--color-ink-muted)', fontSize: 12 }}><TeamOutlined /> 当前任课安排</div>
          {groupLoading ? <span>正在加载班级资料…</span> : groupError ? <Alert type="error" showIcon message={groupError.message} /> : assignments.length ? (
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 7 }}>
              {assignments.map((item) => <Tag key={`${item.teacherId}::${item.subject}`} color="processing">{item.subject} · {item.teacherName}</Tag>)}
            </div>
          ) : <span style={{ color: 'var(--color-ink-muted)' }}>尚未配置老师</span>}
        </Card>
      </div>

      {historical && group && <Alert type="info" showIcon style={{ marginBottom: 14 }} message="当前班级属于历史批次" description="可查看课时和老师资料，但排课、换老师和课时校准操作已锁定。" />}

      <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr 1fr' : 'repeat(3, minmax(0, 1fr))', gap: 9, marginBottom: 16 }}>
        {actionItems.map((item) => {
          const active = activeAction === item.key
          return (
            <button
              key={item.key}
              type="button"
              onClick={() => {
                setActiveAction(item.key)
                if (item.key === 'extra') setModal('extra')
                if (item.key === 'new') setModal('new')
                if (item.key === 'copy') setModal('copy')
                if (item.key === 'periods') setModal('periods')
              }}
              style={{
                display: 'flex', alignItems: 'flex-start', gap: 10, minWidth: 0, minHeight: 74,
                padding: isMobile ? 10 : 13, textAlign: 'left', borderRadius: 13,
                border: `1px solid ${active ? 'var(--color-primary)' : 'var(--color-hairline)'}`,
                background: active ? 'var(--color-primary-bg)' : 'var(--color-surface-1)',
                color: 'var(--color-ink)', cursor: 'pointer',
              }}
            >
              <span style={{ color: 'var(--color-primary)', fontSize: 18, flexShrink: 0, marginTop: 1 }}>{item.icon}</span>
              <span style={{ minWidth: 0 }}><strong style={{ display: 'block', fontSize: 13, lineHeight: 1.4 }}>{item.label}</strong><small style={{ display: 'block', color: 'var(--color-ink-muted)', fontSize: 11, lineHeight: 1.4, marginTop: 3 }}>{item.description}</small></span>
            </button>
          )
        })}
      </div>

      {activeAction === 'move-date' && (
        <Card title="计划内调整上课日" bordered={false} style={{ borderRadius: 14, border: '1px solid var(--color-hairline)' }}>
          {!groupId ? <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="选择一个班级后开始调整" /> : (
            <Space direction="vertical" style={{ width: '100%' }} size={12}>
              <DatePicker value={moveDate} onChange={setMoveDate} allowClear={false} style={{ width: isMobile ? '100%' : 280, minHeight: 44 }} />
              <Alert type="info" showIcon message="仅处理当前班级" description="系统会按该班级已有时段、学科和教师补入课次，并按原规则取消一教学日的同课次数量，保留取消记录供审计。重复执行会先检查目标日期，避免重复创建。" />
              <Popconfirm title={`确认把 ${moveDate?.format('YYYY-MM-DD') || '所选日期'} 加入「${group?.name || '当前班级'}」？`} description="本操作会写入课次安排并可能取消对应未来教学日。" onConfirm={() => void moveClassDate()} okText="确认调整" cancelText="返回">
                <Button type="primary" icon={<CalendarOutlined />} loading={moving} disabled={!moveDate || historical}>确认调课</Button>
              </Popconfirm>
            </Space>
          )}
        </Card>
      )}

      {activeAction === 'teachers' && (
        <Card title="教师更换" bordered={false} style={{ borderRadius: 14, border: '1px solid var(--color-hairline)' }}>
          {!groupId ? <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="先选择班级，查看任课安排" /> : (
            <Space direction="vertical" style={{ width: '100%' }} size={12}>
              {teacherError ? (
                <Alert
                  type="error"
                  showIcon
                  message="教师名单加载失败，暂时无法选择接任老师"
                  description={teacherError.message}
                  action={<Button size="small" icon={<ReloadOutlined />} onClick={() => void mutateTeachers()}>重试</Button>}
                />
              ) : teachersLoading ? (
                <span style={{ color: 'var(--color-ink-muted)', fontSize: 12 }}>正在加载教师名单…</span>
              ) : null}
              <AdaptiveSelect
                placeholder="选择要调整的学科教师"
                value={oldTeacherKey || undefined}
                onChange={(value) => { setOldTeacherKey(value); setNewTeacherId(undefined) }}
                options={assignments.map((item) => ({ value: `${item.teacherId}::${item.subject}`, label: `${item.subject} · ${item.teacherName}` }))}
                style={{ width: '100%' }}
                getPopupContainer={(trigger) => trigger.parentElement || document.body}
              />
              <AdaptiveSelect
                showSearch={!isMobile}
                optionFilterProp="label"
                placeholder="选择接任老师"
                value={newTeacherId}
                onChange={setNewTeacherId}
                options={replacementOptions}
                style={{ width: '100%' }}
                getPopupContainer={(trigger) => trigger.parentElement || document.body}
              />
              <Input placeholder="更换原因（可选，便于后续追溯）" maxLength={120} value={replaceNote} onChange={(event) => setReplaceNote(event.target.value)} />
              {selectedAssignment && <Alert type="warning" showIcon message={`将把 ${selectedAssignment.subject} 的后续任课调整给新老师`} description="已完成课次保留原记录；若目标老师在相同时间已有课程，系统会阻止本次更换并列出冲突。" />}
              <Popconfirm title="确认更换该学科任课老师？" description="操作会更新后续未完成课次、任课关系和家长课表通知。" onConfirm={() => void replaceTeacher()} okText="确认更换" cancelText="取消">
                <Button type="primary" icon={<UserSwitchOutlined />} loading={replacing} disabled={!selectedAssignment || !newTeacherId || historical}>确认更换</Button>
              </Popconfirm>
              <div style={{ borderTop: '1px solid var(--color-hairline)', paddingTop: 12, marginTop: 4 }}>
                <strong style={{ display: 'block', marginBottom: 8 }}>添加任课科目</strong>
                <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : '1fr 1fr auto', gap: 8 }}>
                  <AdaptiveSelect
                    showSearch={!isMobile}
                    optionFilterProp="label"
                    placeholder="选择老师"
                    value={addTeacherId}
                    onChange={setAddTeacherId}
                    options={teacherOptions}
                    style={{ width: '100%' }}
                    getPopupContainer={(trigger) => trigger.parentElement || document.body}
                  />
                  <Select
                    placeholder="选择科目"
                    value={addTeacherSubject || undefined}
                    onChange={setAddTeacherSubject}
                    options={['语文', '数学', '英语', '物理', '化学', '生物', '地理', '历史', '政治'].map((subject) => ({ label: subject, value: subject }))}
                    style={{ width: '100%' }}
                  />
                  <Button loading={addingTeacher} disabled={!addTeacherId || !addTeacherSubject || historical} onClick={() => void addTeacherAssignment()}>添加</Button>
                </div>
              </div>
            </Space>
          )}
        </Card>
      )}

      {activeAction === 'hours' && (
        <Card
          title="学生课时查询"
          extra={<Button icon={<ReloadOutlined />} loading={syncing} disabled={!groupId || historical} onClick={() => void syncStudentHours()}>按报名科目校准插班生</Button>}
          bordered={false}
          style={{ borderRadius: 14, border: '1px solid var(--color-hairline)' }}
        >
          {!groupId ? <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="先选择班级，查看学员课时" /> : !enrollments.length ? <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="当前班级暂无在读学员" /> : (
            <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : 'repeat(2, minmax(0, 1fr))', gap: 9 }}>
              {enrollments.map((enrollment) => (
                <div key={enrollment.id} style={{ padding: 12, borderRadius: 12, background: 'var(--color-surface-2)', border: '1px solid var(--color-hairline)' }}>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8 }}>
                    <strong style={{ minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{enrollment.student?.name || '未命名学员'}</strong>
                    <Tag color="green">剩余 {Number(enrollment.remainHours || 0).toFixed(2)} 小时</Tag>
                  </div>
                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: '4px 12px', marginTop: 7, color: 'var(--color-ink-muted)', fontSize: 12 }}>
                    <span>已用 {Number(enrollment.usedHours || 0).toFixed(2)} 小时</span>
                    <span>总计 {Number(enrollment.totalHours || 0).toFixed(2)} 小时</span>
                    <span>报名：{enrollment.subjects?.length ? enrollment.subjects.join('、') : '未填写科目'}</span>
                  </div>
                </div>
              ))}
            </div>
          )}
          <div style={{ marginTop: 12, color: 'var(--color-ink-muted)', fontSize: 12, lineHeight: 1.6 }}>
            校准只处理开班后加入的插班生，按每人报名科目、加入时间和未完成有效课次计算；已使用课时保留并写入调整流水。
          </div>
        </Card>
      )}

      {groupError && <Alert style={{ marginTop: 12 }} type="error" showIcon message="班级详情加载失败" description={groupError.message} action={<Button size="small" onClick={() => void mutateGroup()}>重试</Button>} />}

      {modal === 'extra' && <ManualLessonModal initialGroupId={groupId || undefined} initialDate={initialDate || undefined} onClose={() => setModal(null)} onSuccess={() => void refreshGroupData()} />}
      {modal === 'new' && <ScheduleFormModal open onClose={() => setModal(null)} onSuccess={() => void refreshGroupData()} />}
      {modal === 'copy' && <CopyFridayToSaturdayModal open onClose={() => setModal(null)} onSuccess={() => void refreshGroupData()} groupIds={groupId ? [groupId] : undefined} />}
      {modal === 'periods' && <SchedulePeriodSettingsModal open periods={periods} onClose={() => setModal(null)} onSaved={() => void mutatePeriods()} />}
    </PageLayout>
  )
}

'use client'
import { AdaptiveSelect } from '@/components/AdaptiveSelect';

import { useState, useEffect, type ReactNode } from 'react'
import useSWR from 'swr'
import {
  Button,
  Card,
  Col,
  Drawer,
  Empty,
  Form,
  Input,
  Pagination,
  Popconfirm,
  Row,
  Segmented,
  Spin,
  Statistic,
  Tabs,
  Tag,
  Typography,
  Alert,
  message,
} from 'antd'
import { BrandModal } from '@/components/Common/BrandModal'
import { EditOutlined, HistoryOutlined, KeyOutlined, LinkOutlined, PlusOutlined, StopOutlined } from '@ant-design/icons'
import { isUserActive } from '@/lib/user-status'
import { useIsMobile } from '@/hooks/useIsMobile'
import { PASSWORD_MIN_LENGTH, validatePassword } from '@/lib/password-policy'
import { formatLocaleDateTime } from '@/lib/format-date'

type AccountStatus = 'active' | 'disabled' | string

interface UserAccount {
  id: string
  email: string
  phone?: string | null
  name: string
  role: 'admin' | 'teacher' | 'parent' | string
  status: AccountStatus
  isSuperAdmin?: boolean
  lastLoginAt: string | null
  lastLoginIp?: string | null
  lastLoginDevice?: string | null
  createdAt: string
  passwordSecurity: {
    encrypted: boolean
    changedAt: string | null
    source: string
    history: Array<{ changedAt: string; source: string; operator: string }>
  }
}

interface TeacherAccount {
  id: string
  name: string
  phone: string
  email: string | null
  subjects: string
  status: string
  account: UserAccount | null
}

interface StudentLite {
  id: string
  name: string
  grade: string | null
  parentName: string | null
  parentPhone: string | null
  parentId: string | null
  parentUserId: string | null
  status: string
}

interface ParentAccount extends UserAccount {
  students: StudentLite[]
}

interface AccountsResponse {
  admins: UserAccount[]
  teachers: TeacherAccount[]
  parents: ParentAccount[]
  studentsWithoutParent: StudentLite[]
}

type ModalMode = 'admin' | 'teacher' | 'parent' | 'edit' | 'phone' | 'reset' | 'bind'
type AccountSelection =
  | { role: 'admin'; record: UserAccount }
  | { role: 'teacher'; record: TeacherAccount }
  | { role: 'parent'; record: ParentAccount }

const ACCOUNT_PAGE_SIZE = 8

function AccountPersonCard({
  name,
  role,
  status,
  primary,
  secondary,
  onClick,
}: {
  name: string
  role: string
  status: string | null | undefined
  primary: string
  secondary: string
  onClick: () => void
}) {
  const tone = status == null ? 'pending' : isUserActive(status) ? 'active' : 'disabled'
  const statusLabel = status == null ? '未创建账号' : isUserActive(status) ? '正常' : '已停用'

  return (
    <button type="button" className="settings-account-person-card" onClick={onClick}>
      <span className="settings-account-card-heading">
        <span className="settings-account-card-avatar" aria-hidden="true">{Array.from(name.trim())[0] || '用'}</span>
        <span className="settings-account-card-identity">
          <span className="settings-account-card-name">{name || '未命名'}</span>
          <span className="settings-account-card-role">{role}</span>
        </span>
        <span className={`settings-account-card-status is-${tone}`}>{statusLabel}</span>
      </span>
      <span className="settings-account-card-meta">
        <span className="settings-account-card-meta-item">
          <span className="settings-account-card-meta-label">主要账号</span>
          <span className="settings-account-card-meta-value">{primary || '未登记'}</span>
        </span>
        <span className="settings-account-card-meta-item">
          <span className="settings-account-card-meta-label">关联信息</span>
          <span className="settings-account-card-meta-value">{secondary || '暂无'}</span>
        </span>
      </span>
      <span className="settings-account-card-open">查看详情与操作 <span aria-hidden="true">→</span></span>
    </button>
  )
}

const fetcher = async (url: string) => {
  const res = await fetch(url)
  const data = await res.json().catch(() => ({}))
  if (!res.ok) throw new Error(data.error || '请求失败')
  return data
}

function statusTag(status: AccountStatus) {
  return <Tag color={isUserActive(status) ? 'green' : 'red'}>{isUserActive(status) ? '正常' : '已停用'}</Tag>
}

export function AdminsTab({ currentUserId, initialRole = 'admin' }: { currentUserId: string; initialRole?: string }) {
  const { data, error, isLoading, mutate } = useSWR<AccountsResponse>('/api/settings/accounts', fetcher)
  const [activeRole, setActiveRole] = useState(initialRole)
  useEffect(() => { setActiveRole(initialRole) }, [initialRole])
  const [keyword, setKeyword] = useState('')
  const [statusFilter, setStatusFilter] = useState<string | undefined>()
  const [currentPage, setCurrentPage] = useState(1)
  const [selectedAccount, setSelectedAccount] = useState<AccountSelection | null>(null)
  const [mode, setMode] = useState<ModalMode | null>(null)
  const [target, setTarget] = useState<UserAccount | TeacherAccount | ParentAccount | null>(null)
  const [submitting, setSubmitting] = useState(false)
  const [issuedCredential, setIssuedCredential] = useState<{ email: string; password: string } | null>(null)
  const [passwordHistoryTarget, setPasswordHistoryTarget] = useState<UserAccount | null>(null)
  const [form] = Form.useForm()
  const isMobile = useIsMobile() ?? false

  useEffect(() => { setCurrentPage(1) }, [activeRole, keyword, statusFilter])

  const studentsWithoutParent = data?.studentsWithoutParent || []

  const runJson = async (url: string, init: RequestInit) => {
    const res = await fetch(url, {
      ...init,
      headers: { 'Content-Type': 'application/json', ...(init.headers || {}) },
    })
    const payload = await res.json().catch(() => ({}))
    if (!res.ok) throw new Error(payload.error || '操作失败')
    return payload
  }

  const openModal = (nextMode: ModalMode, nextTarget: typeof target = null) => {
    setMode(nextMode)
    setTarget(nextTarget)
    form.resetFields()
    if (nextMode === 'edit' && nextTarget && 'email' in nextTarget) {
      form.setFieldsValue({
        name: nextTarget.name,
        email: nextTarget.email,
        ...('role' in nextTarget && nextTarget.role === 'admin' ? { phone: nextTarget.phone || '' } : {}),
      })
    }
    if (nextMode === 'phone' && nextTarget && 'role' in nextTarget && nextTarget.role === 'admin') {
      form.setFieldsValue({ phone: nextTarget.phone || '' })
    }
  }

  const closeModal = () => {
    setMode(null)
    setTarget(null)
    form.resetFields()
  }

  const changeStatus = async (userId: string, status: 'active' | 'disabled') => {
    try {
      await runJson('/api/settings/accounts', {
        method: 'PATCH',
        body: JSON.stringify({ action: 'status', userId, status }),
      })
      message.success(isUserActive(status) ? '账号已启用' : '账号已停用')
      mutate()
    } catch (error) {
      message.error(error instanceof Error ? error.message : '操作失败')
    }
  }

  const softDelete = async (userId: string) => {
    try {
      await runJson(`/api/settings/accounts?userId=${encodeURIComponent(userId)}`, { method: 'DELETE' })
      message.success('账号已停用')
      mutate()
    } catch (error) {
      message.error(error instanceof Error ? error.message : '操作失败')
    }
  }

  const unbindStudent = async (studentId: string) => {
    try {
      await runJson('/api/settings/accounts', {
        method: 'PATCH',
        body: JSON.stringify({ action: 'unbind-student', studentId }),
      })
      message.success('已解绑学员')
      mutate()
    } catch (error) {
      message.error(error instanceof Error ? error.message : '操作失败')
    }
  }

  const handleSubmit = async (values: Record<string, unknown>) => {
    setSubmitting(true)
    try {
      if (mode === 'admin' || mode === 'teacher' || mode === 'parent') {
        const payload = await runJson('/api/settings/accounts', {
          method: 'POST',
          body: JSON.stringify({ ...values, role: mode }),
        })
        if (payload.initialPassword) {
          setIssuedCredential({ email: payload.user.email, password: payload.initialPassword })
        } else {
          message.success('账号已创建')
        }
      }
      if (mode === 'edit' && target && 'id' in target) {
        await runJson('/api/settings/accounts', {
          method: 'PATCH',
          body: JSON.stringify({ ...values, action: 'update', userId: target.id }),
        })
        message.success('账号已更新')
      }
      if (mode === 'phone' && target && 'id' in target) {
        await runJson('/api/settings/accounts', {
          method: 'PATCH',
          body: JSON.stringify({ action: 'update-login-phone', userId: target.id, phone: values.phone || '' }),
        })
        message.success(values.phone ? '登录手机号已绑定' : '登录手机号已解除绑定')
      }
      if (mode === 'reset' && target && 'id' in target) {
        await runJson('/api/settings/accounts', {
          method: 'PATCH',
          body: JSON.stringify({ ...values, action: 'reset-password', userId: target.id }),
        })
        message.success('密码已重置，旧设备会失效')
      }
      if (mode === 'bind' && target && 'id' in target) {
        await runJson('/api/settings/accounts', {
          method: 'PATCH',
          body: JSON.stringify({ ...values, action: 'bind-students', userId: target.id }),
        })
        message.success('学员已绑定')
      }
      closeModal()
      mutate()
    } catch (error) {
      message.error(error instanceof Error ? error.message : '操作失败')
    } finally {
      setSubmitting(false)
    }
  }

  const filterUsers = <T extends UserAccount>(items: T[]) => items.filter((item) => {
    const text = [item.name, item.email, item.phone || '', item.role].join('').toLowerCase()
    return (!keyword || text.includes(keyword.toLowerCase())) && (!statusFilter || item.status === statusFilter)
  })

  const passwordRule = {
    validator: async (_: unknown, value: unknown) => {
      const result = validatePassword(String(value || ''))
      if (!result.valid) throw new Error(result.errors[0])
    },
  }

  const optionalPasswordRule = {
    validator: async (_: unknown, value: unknown) => {
      if (!value) return
      const result = validatePassword(String(value))
      if (!result.valid) throw new Error(result.errors[0])
    },
  }

  const admins = filterUsers(data?.admins || [])
  const parents = filterUsers(data?.parents || [])
  const currentAdmin = (data?.admins || []).find((admin) => admin.id === currentUserId)
  const currentIsSuperAdmin = currentAdmin?.isSuperAdmin === true
  const teachers = (data?.teachers || []).filter((teacher) => {
    const text = `${teacher.name}${teacher.phone}${teacher.email || ''}${teacher.account?.email || ''}`.toLowerCase()
    return (!keyword || text.includes(keyword.toLowerCase())) && (!statusFilter || teacher.account?.status === statusFilter)
  })

  const userActions = (record: UserAccount, closeDetails = false) => {
    const openAction = (nextMode: ModalMode) => {
      if (closeDetails) setSelectedAccount(null)
      openModal(nextMode, record)
    }
    const completeStatusChange = (status: 'active' | 'disabled') => {
      if (closeDetails) setSelectedAccount(null)
      return changeStatus(record.id, status)
    }

    return (
      <div className="settings-account-detail-actions">
        <Button icon={<EditOutlined />} onClick={() => openAction('edit')}>编辑资料</Button>
        <Button icon={<KeyOutlined />} onClick={() => openAction('reset')}>重置密码</Button>
        {isUserActive(record.status) ? (
          <Popconfirm title="确定停用该账号？" onConfirm={() => completeStatusChange('disabled')}>
            <Button danger icon={<StopOutlined />} disabled={record.id === currentUserId}>停用账号</Button>
          </Popconfirm>
        ) : (
          <Button onClick={() => completeStatusChange('active')}>启用账号</Button>
        )}
        <Popconfirm
          title="按现有规范仅停用账号，不删除业务数据。确定继续？"
          onConfirm={() => {
            if (closeDetails) setSelectedAccount(null)
            return softDelete(record.id)
          }}
        >
          <Button danger disabled={record.id === currentUserId}>删除/停用</Button>
        </Popconfirm>
      </div>
    )
  }

  const cardPageOffset = (currentPage - 1) * ACCOUNT_PAGE_SIZE
  const adminCards: ReactNode[] = admins.slice(cardPageOffset, cardPageOffset + ACCOUNT_PAGE_SIZE).map((record) => (
    <AccountPersonCard
      key={record.id}
      name={record.name}
      role={record.isSuperAdmin ? '最高权益管理员' : '管理员账号'}
      status={record.status}
      primary={record.email}
      secondary={record.phone ? `登录手机号 ${record.phone}` : '未绑定登录手机号'}
      onClick={() => setSelectedAccount({ role: 'admin', record })}
    />
  ))
  const teacherCards: ReactNode[] = teachers.slice(cardPageOffset, cardPageOffset + ACCOUNT_PAGE_SIZE).map((record) => (
    <AccountPersonCard
      key={record.id}
      name={record.name}
      role="教师账号"
      status={record.account?.status}
      primary={record.phone || '未登记手机号'}
      secondary={record.account?.email || record.email || '尚未创建登录账号'}
      onClick={() => setSelectedAccount({ role: 'teacher', record })}
    />
  ))
  const parentCards: ReactNode[] = parents.slice(cardPageOffset, cardPageOffset + ACCOUNT_PAGE_SIZE).map((record) => (
    <AccountPersonCard
      key={record.id}
      name={record.name}
      role="家长账号"
      status={record.status}
      primary={record.email || record.phone || '未登记账号'}
      secondary={record.students.length ? `已绑定 ${record.students.length} 位学员` : '尚未绑定学员'}
      onClick={() => setSelectedAccount({ role: 'parent', record })}
    />
  ))

  const renderAccountPanel = (cards: ReactNode[], total: number) => (
    <div className="settings-account-card-panel">
      <div className="settings-account-card-count">共 {total} 个账号 · 点击人员卡片查看详情和操作</div>
      {isLoading ? <div className="settings-account-card-loading"><Spin /></div> : total ? (
        <div className="settings-account-card-grid">{cards}</div>
      ) : (
        <Empty description="没有符合条件的账号" />
      )}
      {!isLoading && total > ACCOUNT_PAGE_SIZE && (
        <Pagination
          current={currentPage}
          pageSize={ACCOUNT_PAGE_SIZE}
          total={total}
          showSizeChanger={false}
          onChange={setCurrentPage}
          size={isMobile ? 'small' : 'default'}
        />
      )}
    </div>
  )

  const selectedRecord = selectedAccount?.record
  const detailAccount: UserAccount | null = selectedAccount
    ? selectedAccount.role === 'teacher' ? selectedAccount.record.account : selectedAccount.record
    : null
  const detailName = selectedRecord?.name || ''
  const detailRoleLabel = selectedAccount?.role === 'admin' ? '管理员账号'
    : selectedAccount?.role === 'teacher' ? '教师账号' : selectedAccount?.role === 'parent' ? '家长账号' : ''
  const detailStatus = selectedAccount?.role === 'teacher'
    ? selectedAccount.record.account?.status
    : selectedAccount?.record.status
  const detailEmail = selectedAccount?.role === 'teacher'
    ? selectedAccount.record.account?.email || selectedAccount.record.email || '未登记'
    : selectedRecord && 'email' in selectedRecord ? selectedRecord.email || '未登记' : '未登记'
  const detailPhone = selectedAccount?.role === 'teacher'
    ? selectedAccount.record.phone || '未登记'
    : selectedRecord && 'phone' in selectedRecord ? selectedRecord.phone || '未登记' : '未登记'
  const openDetailModal = (nextMode: ModalMode, nextTarget: typeof target) => {
    setSelectedAccount(null)
    openModal(nextMode, nextTarget)
  }

  const toolbar = (
    <div className="settings-account-toolbar">
      <div className="settings-account-filters">
        <Input.Search
          placeholder="搜索姓名、账号、手机号"
          allowClear
          value={keyword}
          onChange={(event) => setKeyword(event.target.value)}
          className="settings-account-search"
        />
        <Segmented
          block={isMobile}
          value={statusFilter || 'all'}
          onChange={(value) => setStatusFilter(value === 'all' ? '' : String(value))}
          options={[
            { label: '全部', value: 'all' },
            { label: '正常', value: 'active' },
            { label: '已停用', value: 'disabled' },
          ]}
          className="settings-account-status"
        />
      </div>
      <div className="settings-account-actions">
        {activeRole === 'admin' && <Button type="primary" icon={<PlusOutlined />} style={{ background: 'var(--color-primary)' }} onClick={() => openModal('admin')}>新增管理员</Button>}
        {activeRole === 'parent' && <Button type="primary" icon={<PlusOutlined />} style={{ background: 'var(--color-primary)' }} onClick={() => openModal('parent')}>新增家长账号</Button>}
      </div>
    </div>
  )

  return (
    <Card bordered={false} style={{ borderRadius: 10 }}>
      {error && <Alert type="error" showIcon message="账号与绑定数据加载失败" description={error.message} action={<Button onClick={() => mutate()}>重试</Button>} style={{ marginBottom: 16 }} />}

      <Row gutter={[10, 10]} style={{ marginBottom: 16 }}>
        <Col xs={12} sm={6}>
          <div style={{ padding: '10px 14px', borderRadius: 10, background: '#FAFAF8', border: '1px solid #EDE9E1' }}>
            <div style={{ fontSize: isMobile ? 11 : 12, color: '#8C827A' }}>管理员</div>
            <div style={{ fontSize: isMobile ? 18 : 22, fontWeight: 700, color: '#17352F', marginTop: 2 }}>
              {data?.admins.length ?? 0}<span style={{ fontSize: 12, fontWeight: 400, marginLeft: 2 }}>个</span>
            </div>
          </div>
        </Col>
        <Col xs={12} sm={6}>
          <div style={{ padding: '10px 14px', borderRadius: 10, background: '#FAFAF8', border: '1px solid #EDE9E1' }}>
            <div style={{ fontSize: isMobile ? 11 : 12, color: '#8C827A' }}>教师账号</div>
            <div style={{ fontSize: isMobile ? 18 : 22, fontWeight: 700, color: '#14574D', marginTop: 2 }}>
              {data?.teachers.length ?? 0}<span style={{ fontSize: 12, fontWeight: 400, marginLeft: 2 }}>位</span>
            </div>
          </div>
        </Col>
        <Col xs={12} sm={6}>
          <div style={{ padding: '10px 14px', borderRadius: 10, background: '#FAFAF8', border: '1px solid #EDE9E1' }}>
            <div style={{ fontSize: isMobile ? 11 : 12, color: '#8C827A' }}>家长账号</div>
            <div style={{ fontSize: isMobile ? 18 : 22, fontWeight: 700, color: '#17352F', marginTop: 2 }}>
              {data?.parents.length ?? 0}<span style={{ fontSize: 12, fontWeight: 400, marginLeft: 2 }}>个</span>
            </div>
          </div>
        </Col>
        <Col xs={12} sm={6}>
          <div style={{ padding: '10px 14px', borderRadius: 10, background: studentsWithoutParent.length > 0 ? '#FFF7F0' : '#FAFAF8', border: `1px solid ${studentsWithoutParent.length > 0 ? '#F3D2BA' : '#EDE9E1'}` }}>
            <div style={{ fontSize: isMobile ? 11 : 12, color: studentsWithoutParent.length > 0 ? '#C45724' : '#8C827A' }}>待绑定学员</div>
            <div style={{ fontSize: isMobile ? 18 : 22, fontWeight: 700, color: studentsWithoutParent.length > 0 ? '#E8784A' : '#8C827A', marginTop: 2 }}>
              {studentsWithoutParent.length}<span style={{ fontSize: 12, fontWeight: 400, marginLeft: 2 }}>位</span>
            </div>
          </div>
        </Col>
      </Row>

      {toolbar}
      <Tabs
        activeKey={activeRole}
        onChange={(role) => { setActiveRole(role); setCurrentPage(1) }}
        items={[
          {
            key: 'admin',
            label: '管理员账号',
            children: renderAccountPanel(adminCards, admins.length),
          },
          {
            key: 'teacher',
            label: '教师账号',
            children: renderAccountPanel(teacherCards, teachers.length),
          },
          {
            key: 'parent',
            label: '家长账号与绑定',
            children: renderAccountPanel(parentCards, parents.length),
          },
        ]}
      />

      <Drawer
        title="人员账号详情"
        open={Boolean(selectedAccount)}
        onClose={() => setSelectedAccount(null)}
        placement={isMobile ? 'bottom' : 'right'}
        width={isMobile ? '100%' : 520}
        height={isMobile ? '86vh' : undefined}
        rootClassName="settings-account-detail-drawer"
        styles={{ body: { padding: '18px 20px' }, header: { padding: '16px 20px' } }}
        destroyOnHidden
      >
        {selectedAccount && (
          <div className="settings-account-detail">
            <div className="settings-account-detail-profile">
              <span className="settings-account-card-avatar" aria-hidden="true">{Array.from(detailName.trim())[0] || '用'}</span>
              <div className="settings-account-detail-identity">
                <strong>{detailName || '未命名'}</strong>
                <span>{detailRoleLabel}</span>
              </div>
              {detailStatus == null ? <Tag>未创建账号</Tag> : statusTag(detailStatus)}
            </div>

            <section className="settings-account-detail-section">
              <h3>账号信息</h3>
              <dl className="settings-account-detail-grid">
                <div><dt>登录账号</dt><dd>{detailEmail}</dd></div>
                <div><dt>手机号</dt><dd>{detailPhone}</dd></div>
                {selectedAccount.role === 'teacher' && <div><dt>授课学科</dt><dd>{selectedAccount.record.subjects || '未登记'}</dd></div>}
                {detailAccount && <div><dt>最近登录</dt><dd>{formatLocaleDateTime(detailAccount.lastLoginAt)}</dd></div>}
                {selectedAccount.role !== 'teacher' && <div><dt>创建时间</dt><dd>{formatLocaleDateTime(selectedAccount.record.createdAt)}</dd></div>}
              </dl>
            </section>

            {detailAccount && (
              <section className="settings-account-detail-section">
                <h3>密码与安全</h3>
                <div className="settings-account-security-card">
                  <Tag color={detailAccount.passwordSecurity.encrypted ? 'green' : 'red'}>
                    {detailAccount.passwordSecurity.encrypted ? '密码已加密' : '需要处理'}
                  </Tag>
                  <Typography.Text type="secondary">
                    {detailAccount.passwordSecurity.source}
                    {detailAccount.passwordSecurity.changedAt ? ` · ${formatLocaleDateTime(detailAccount.passwordSecurity.changedAt)}` : ''}
                  </Typography.Text>
                  <Button
                    type="link"
                    icon={<HistoryOutlined />}
                    onClick={() => { setSelectedAccount(null); setPasswordHistoryTarget(detailAccount) }}
                  >
                    查看密码修改记录
                  </Button>
                </div>
              </section>
            )}

            {selectedAccount.role === 'parent' && (
              <section className="settings-account-detail-section">
                <div className="settings-account-section-heading">
                  <h3>绑定学员</h3>
                  <Button icon={<LinkOutlined />} onClick={() => openDetailModal('bind', selectedAccount.record)}>绑定学员</Button>
                </div>
                {selectedAccount.record.students.length ? (
                  <div className="settings-account-students">
                    {selectedAccount.record.students.map((student) => (
                      <div className="settings-account-student" key={student.id}>
                        <span>{student.name}{student.grade ? ` · ${student.grade}` : ''}</span>
                        <Button type="link" danger onClick={() => { setSelectedAccount(null); void unbindStudent(student.id) }}>解绑</Button>
                      </div>
                    ))}
                  </div>
                ) : <Typography.Text type="secondary">当前没有绑定学员</Typography.Text>}
              </section>
            )}

            <section className="settings-account-detail-section">
              <h3>账号操作</h3>
              {selectedAccount.role === 'teacher' && !selectedAccount.record.account && (
                <Button block type="primary" icon={<PlusOutlined />} onClick={() => openDetailModal('teacher', selectedAccount.record)}>
                  创建教师登录账号
                </Button>
              )}
              {selectedAccount.role === 'admin' && detailAccount?.id === currentUserId && (
                <Button block icon={<EditOutlined />} onClick={() => openDetailModal('phone', detailAccount)}>
                  {detailAccount.phone ? '修改登录手机号' : '绑定登录手机号'}
                </Button>
              )}
              {selectedAccount.role === 'admin' && detailAccount?.id !== currentUserId && detailAccount?.isSuperAdmin && !currentIsSuperAdmin && (
                <Typography.Text type="secondary">最高权益管理员，仅最高权益管理员可操作此账号。</Typography.Text>
              )}
              {detailAccount && !(selectedAccount.role === 'admin' && detailAccount.id === currentUserId)
                && !(selectedAccount.role === 'admin' && detailAccount.isSuperAdmin && !currentIsSuperAdmin)
                && userActions(detailAccount, true)}
            </section>
          </div>
        )}
      </Drawer>

      <BrandModal
        title={mode === 'admin' ? '新增管理员' : mode === 'teacher' ? '创建教师登录账号' : mode === 'parent' ? '新增家长账号' : mode === 'reset' ? '重置密码' : mode === 'bind' ? '绑定学员' : mode === 'phone' ? '设置登录手机号' : '编辑账号'}
        open={Boolean(mode)}
        onCancel={closeModal}
        onOk={() => form.submit()}
        confirmLoading={submitting}
        destroyOnHidden
      >
        <Form form={form} layout="vertical" onFinish={handleSubmit}>
          {mode === 'teacher' && target && 'phone' in target && (
            <>
              <Form.Item label="教师（使用档案手机号登录）"><Input value={target.name} disabled /></Form.Item>
              <Form.Item name="teacherId" initialValue={target.id} hidden><Input /></Form.Item>
              <Form.Item name="email" label="登录邮箱" tooltip="留空时优先使用教师邮箱，没有教师邮箱则使用手机号生成 @tea.com 账号">
                <Input placeholder={target.email || `${target.phone}@tea.com`} />
              </Form.Item>
              <Form.Item name="password" label="初始密码" tooltip="留空时使用教师姓名拼音（小写、无空格）；填写自定义密码时需符合密码规则" rules={[optionalPasswordRule]}>
                <Input.Password placeholder="留空使用教师姓名拼音" autoComplete="new-password" />
              </Form.Item>
            </>
          )}

          {(mode === 'admin' || (mode === 'edit' && target && 'role' in target && target.role === 'admin')) && (
            <Form.Item
              name="phone"
              label="登录手机号"
              extra="教师档案手机号不会自动绑定到管理员账号；绑定后可用原账号密码登录管理端，同一手机号不能重复绑定。"
            >
              <Input type="tel" inputMode="tel" placeholder="请输入11位中国大陆手机号" autoComplete="tel" />
            </Form.Item>
          )}

          {mode === 'phone' && (
            <Form.Item
              name="phone"
              label="登录手机号"
              extra="教师档案手机号不会自动绑定到管理员账号；绑定后可用原账号密码登录管理端，同一手机号不能重复绑定。留空可解除绑定。"
            >
              <Input type="tel" inputMode="tel" placeholder="请输入11位中国大陆手机号" autoComplete="tel" />
            </Form.Item>
          )}

          {(mode === 'admin' || mode === 'parent' || mode === 'edit') && (
            <>
              <Form.Item name="name" label="姓名" rules={[{ required: true, message: '请输入姓名' }]}>
                <Input />
              </Form.Item>
              <Form.Item
                name="email"
                label="登录邮箱"
                rules={[
                  { required: mode !== 'parent', message: '请输入登录邮箱' },
                  { type: 'email', message: '请输入正确邮箱' },
                ]}
              >
                <Input placeholder={mode === 'parent' ? '可留空，系统按手机号生成' : undefined} />
              </Form.Item>
            </>
          )}

          {mode === 'parent' && (
            <>
              <Form.Item name="phone" label="手机号" rules={[{ required: true, message: '请输入手机号' }]}>
                <Input type="tel" inputMode="numeric" />
              </Form.Item>
              <Form.Item name="studentIds" label="绑定学员">
                <AdaptiveSelect
                  mode="multiple"
                  placeholder="选择需要绑定的学员"
                  options={studentsWithoutParent.map((student) => ({ label: `${student.name}${student.grade ? ` / ${student.grade}` : ''}`, value: student.id }))}
                />
              </Form.Item>
              <Form.Item name="password" label="初始密码" tooltip="留空时使用首位绑定学员姓名拼音；未绑定学员时使用家长姓名拼音" rules={[optionalPasswordRule]}>
                <Input.Password placeholder="留空使用学员姓名拼音" autoComplete="new-password" />
              </Form.Item>
            </>
          )}

          {mode === 'admin' && (
            <Form.Item
              name="password"
              label="初始密码"
              rules={[
                { required: true, message: '请输入初始密码' },
                passwordRule,
              ]}
            >
              <Input.Password autoComplete="new-password" placeholder={`至少 ${PASSWORD_MIN_LENGTH} 位，包含英文字母`} />
            </Form.Item>
          )}

          {mode === 'reset' && (
            <Form.Item name="password" label="新密码" rules={[{ required: true, message: '请输入新密码' }, passwordRule]}>
              <Input.Password autoComplete="new-password" placeholder={`至少 ${PASSWORD_MIN_LENGTH} 位，包含英文字母`} />
            </Form.Item>
          )}

          {mode === 'bind' && (
            <Form.Item name="studentIds" label="绑定学员" rules={[{ required: true, message: '请选择学员' }]}>
              <AdaptiveSelect
                mode="multiple"
                placeholder="选择需要绑定的学员"
                options={studentsWithoutParent.map((student) => ({ label: `${student.name}${student.grade ? ` / ${student.grade}` : ''}`, value: student.id }))}
              />
            </Form.Item>
          )}
        </Form>
      </BrandModal>

      <BrandModal
        title="账号创建成功"
        open={Boolean(issuedCredential)}
        onCancel={() => setIssuedCredential(null)}
        footer={<Button type="primary" onClick={() => setIssuedCredential(null)}>我已安全保存</Button>}
        width={460}
      >
        <Alert
          type="warning"
          showIcon
          message="初始密码仅显示这一次"
          description="请通过安全方式交给本人。系统不会保存可查看的明文密码，关闭后只能重新重置。"
          style={{ marginBottom: 18 }}
        />
        <Typography.Paragraph>
          <Typography.Text type="secondary">登录账号</Typography.Text><br />
          <Typography.Text strong copyable>{issuedCredential?.email}</Typography.Text>
        </Typography.Paragraph>
        <Typography.Paragraph>
          <Typography.Text type="secondary">初始密码</Typography.Text><br />
          <Typography.Text strong copyable>{issuedCredential?.password}</Typography.Text>
        </Typography.Paragraph>
      </BrandModal>

      <BrandModal
        title={`${passwordHistoryTarget?.name || ''} · 密码安全记录`}
        open={Boolean(passwordHistoryTarget)}
        onCancel={() => setPasswordHistoryTarget(null)}
        footer={<Button onClick={() => setPasswordHistoryTarget(null)}>关闭</Button>}
        width={560}
      >
        <Alert
          type="info"
          showIcon
          message="系统只记录修改时间、方式和操作人，不保存或展示明文密码。"
          style={{ marginBottom: 16 }}
        />
        {passwordHistoryTarget?.passwordSecurity.history.length ? (
          <div className="settings-password-history-list">
            {passwordHistoryTarget.passwordSecurity.history.map((entry) => (
              <article className="settings-password-history-item" key={`${entry.changedAt}-${entry.source}`}>
                <strong>{formatLocaleDateTime(entry.changedAt)}</strong>
                <span>方式：{entry.source || '未记录'}</span>
                <span>操作人：{entry.operator || '未记录'}</span>
              </article>
            ))}
          </div>
        ) : <Empty description="暂无历史审计记录" />}
      </BrandModal>
    </Card>
  )
}

'use client'

import { useMemo, useState } from 'react'
import Link from 'next/link'
import useSWR from 'swr'
import { Empty, Spin } from 'antd'
import {
  CheckCircleOutlined, CloseCircleOutlined, FileSearchOutlined, BookOutlined,
  MessageOutlined, FileTextOutlined, TrophyOutlined, SearchOutlined, CalendarOutlined,
} from '@ant-design/icons'
import { PageLayout } from '@/components/Layout/PageLayout'
import { StudentAvatar } from '@/components/Common/StudentAvatar'

type CompletenessItem = {
  studentId: string
  name: string
  grade: string | null
  gender?: string | null
  mainTeacherName: string | null
  hasPractice: boolean
  hasFeedback: boolean
  hasSummary: boolean
  missingCount: number
}

type CompletenessPayload = {
  summary: { noPractice: number; noFeedback: number; noSummary: number }
  items: CompletenessItem[]
}

const fetcher = (url: string) => fetch(url).then(async (res) => {
  const data = await res.json()
  if (!res.ok) throw new Error(data.error || '请求失败')
  return data
})

const GRADE_ORDER = ['初一', '初二', '初三', '高一', '高二', '高三', '个性化']

function AvatarBlock({ name, gender, size = 40 }: { name: string; gender?: string | null; size?: number }) {
  return <StudentAvatar name={name} gender={gender} size={size} />
}

function MissingTag({ ok, label, missingLabel }: { ok: boolean; label: string; missingLabel: string }) {
  return (
    <div style={{
      display: 'inline-flex', alignItems: 'center', gap: 4,
      fontSize: 11.5, fontWeight: 700, padding: '3px 9px', borderRadius: 999,
      color: ok ? '#1D7A52' : '#C2413C',
      background: ok ? 'rgba(29,154,98,.1)' : 'rgba(194,65,60,.09)',
      border: `1px solid ${ok ? 'rgba(29,154,98,.28)' : 'rgba(194,65,60,.25)'}`,
    }}>
      {ok ? <CheckCircleOutlined /> : <CloseCircleOutlined />}
      {ok ? `${label}齐` : `缺${missingLabel}`}
    </div>
  )
}

export default function StudentArchiveDashboardPage() {
  const [months, setMonths] = useState(1)
  const [statusFilter, setStatusFilter] = useState<'all' | 'noPractice' | 'noFeedback' | 'noSummary' | 'complete'>('all')
  const [search, setSearch] = useState('')
  const { data, isLoading } = useSWR<CompletenessPayload>(`/api/admin/profile-completeness?months=${months}`, fetcher)

  const items = data?.items ?? []
  const filtered = useMemo(() => {
    let result = items
    if (statusFilter === 'noPractice') result = result.filter((item) => !item.hasPractice)
    if (statusFilter === 'noFeedback') result = result.filter((item) => !item.hasFeedback)
    if (statusFilter === 'noSummary') result = result.filter((item) => !item.hasSummary)
    if (statusFilter === 'complete') result = result.filter((item) => item.missingCount === 0)
    if (search.trim()) result = result.filter((item) => item.name.includes(search.trim()))
    return [...result].sort((a, b) => {
      const ga = GRADE_ORDER.indexOf(a.grade || ''), gb = GRADE_ORDER.indexOf(b.grade || '')
      if ((ga === -1 ? 99 : ga) !== (gb === -1 ? 99 : gb)) return (ga === -1 ? 99 : ga) - (gb === -1 ? 99 : gb)
      return b.missingCount - a.missingCount
    })
  }, [items, statusFilter, search])

  const summary = data?.summary ?? { noPractice: 0, noFeedback: 0, noSummary: 0 }
  const total = items.length
  const completeCount = items.filter((item) => item.missingCount === 0).length

  const statCards = [
    { key: 'noPractice', label: '本期未做题', value: summary.noPractice, color: '#E8784A', icon: <FileTextOutlined />, note: total ? `占学员 ${Math.round((summary.noPractice / total) * 100)}%` : '暂无数据' },
    { key: 'noFeedback', label: '本期无反馈', value: summary.noFeedback, color: '#7C5CFF', icon: <MessageOutlined />, note: total ? `占学员 ${Math.round((summary.noFeedback / total) * 100)}%` : '暂无数据' },
    { key: 'noSummary', label: '本期无小结', value: summary.noSummary, color: '#D9534F', icon: <BookOutlined />, note: total ? `占学员 ${Math.round((summary.noSummary / total) * 100)}%` : '暂无数据' },
    { key: 'complete', label: '资料齐全学员', value: completeCount, color: '#1D9E75', icon: <TrophyOutlined />, note: total ? `完成率 ${Math.round((completeCount / total) * 100)}%` : '暂无数据' },
  ]

  const filterButtons = [
    { key: 'all', label: '全部' },
    { key: 'noPractice', label: '未做题' },
    { key: 'noFeedback', label: '缺反馈' },
    { key: 'noSummary', label: '缺小结' },
    { key: 'complete', label: '齐全' },
  ] as const

  return (
    <PageLayout
      title="学情资料检查"
      subtitle="按月核对做题练习、课堂反馈与阶段小结的记录情况，优先处理红色缺项"
    >
      <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
        {/* 统计卡 */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 10 }}>
          {statCards.map((card) => (
            <div
              key={card.key}
              style={{
                borderRadius: 16, padding: '14px 14px',
                background: card.key === 'complete'
                  ? 'linear-gradient(150deg,#17352F,#0E5E4E)'
                  : '#fff',
                border: card.key === 'complete' ? '1px solid rgba(201,164,92,.5)' : '1px solid #F0E9DF',
                boxShadow: '0 4px 14px rgba(58,50,39,.06)',
                position: 'relative', overflow: 'hidden',
              }}
            >
              {card.key === 'complete' && (
                <div style={{ position: 'absolute', top: -30, right: -20, width: 110, height: 110, borderRadius: '50%', background: 'radial-gradient(circle, rgba(242,227,182,.25), transparent 70%)', pointerEvents: 'none' }} />
              )}
              <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                <div style={{
                  width: 40, height: 40, borderRadius: 12, flexShrink: 0, display: 'grid', placeItems: 'center', fontSize: 17,
                  background: card.key === 'complete'
                    ? 'linear-gradient(145deg,#F2E3B6,#D8BC7C)'
                    : `${card.color}15`,
                  color: card.key === 'complete' ? '#123C35' : card.color,
                }}>{card.icon}</div>
                <div style={{ minWidth: 0 }}>
                  <div style={{ fontSize: 23, fontWeight: 800, color: card.key === 'complete' ? '#F2E3B6' : '#1F2329', lineHeight: 1.15, fontVariantNumeric: 'tabular-nums' }}>{card.value}</div>
                  <div style={{ fontSize: 11.5, color: card.key === 'complete' ? 'rgba(245,241,232,.65)' : '#98A2B3', marginTop: 1 }}>{card.label}</div>
                </div>
              </div>
              <div style={{ fontSize: 11, color: card.key === 'complete' ? 'rgba(242,227,182,.75)' : '#B8B2A8', marginTop: 8 }}>{card.note}</div>
            </div>
          ))}
        </div>

        {/* 工具条 */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10, flexWrap: 'wrap' }}>
          <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
            {filterButtons.map((button) => (
              <button
                key={button.key}
                onClick={() => setStatusFilter(button.key)}
                style={{
                  fontFamily: 'inherit', cursor: 'pointer', fontSize: 12, fontWeight: 700,
                  padding: '5px 12px', borderRadius: 999,
                  border: statusFilter === button.key ? '1px solid #0E5E4E' : '1px solid #E5DFD6',
                  color: statusFilter === button.key ? '#fff' : '#6B7280',
                  background: statusFilter === button.key ? 'linear-gradient(135deg,#0E5E4E,#123C35)' : '#fff',
                }}
              >{button.label}</button>
            ))}
          </div>
          <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
            <div style={{ position: 'relative' }}>
              <SearchOutlined style={{ position: 'absolute', left: 10, top: '50%', transform: 'translateY(-50%)', fontSize: 12, color: '#98A2B3' }} />
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="搜索学员姓名"
                style={{
                  fontFamily: 'inherit', fontSize: 13, padding: '6px 10px 6px 28px', borderRadius: 10,
                  border: '1px solid #E5DFD6', outline: 'none', width: 150, background: '#fff',
                }}
              />
            </div>
            <select
              value={months}
              onChange={(event) => setMonths(Number(event.target.value))}
              style={{
                fontFamily: 'inherit', fontSize: 13, padding: '6px 10px', borderRadius: 10,
                border: '1px solid #E5DFD6', background: '#fff', color: '#1F2329', outline: 'none',
              }}
            >
              <option value={1}>近 1 个月</option>
              <option value={3}>近 3 个月</option>
              <option value={6}>近 6 个月</option>
              <option value={12}>近 12 个月</option>
            </select>
          </div>
        </div>

        {/* 学员卡片列表 */}
        {isLoading ? (
          <div style={{ textAlign: 'center', padding: 64 }}><Spin size="large" /></div>
        ) : filtered.length === 0 ? (
          <div style={{ background: '#fff', borderRadius: 16, border: '1px solid #F0E9DF', padding: 40 }}>
            <Empty description={items.length === 0 ? '暂无学员数据' : '没有符合筛选条件的学员'} />
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            {filtered.map((item) => {
              const complete = item.missingCount === 0
              return (
                <div
                  key={item.studentId}
                  style={{
                    borderRadius: 16, overflow: 'hidden',
                    background: complete ? '#fff' : '#FFFDF9',
                    border: complete ? '1px solid #F0E9DF' : '1px solid rgba(232,120,74,.35)',
                    boxShadow: complete ? '0 3px 12px rgba(58,50,39,.05)' : '0 4px 14px rgba(232,120,74,.08)',
                  }}
                >
                  <div style={{ display: 'flex', alignItems: 'center', gap: 11, padding: '12px 14px 10px' }}>
                    <AvatarBlock name={item.name} gender={item.gender} />
                    <div style={{ minWidth: 0, flex: 1 }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 7, flexWrap: 'wrap' }}>
                        <span style={{ fontSize: 14.5, fontWeight: 800, color: '#1F2329' }}>{item.name}</span>
                        {item.grade && (
                          <span style={{
                            fontSize: 10.5, fontWeight: 700, padding: '1px 7px', borderRadius: 999,
                            color: '#0E5E4E', background: 'rgba(14,94,78,.08)', border: '1px solid rgba(14,94,78,.25)',
                          }}>{item.grade}</span>
                        )}
                      </div>
                      <div style={{ fontSize: 12, color: '#98A2B3', marginTop: 2 }}>
                        主教师：{item.mainTeacherName || '未分配'}
                      </div>
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', flexShrink: 0 }}>
                      <div style={{ display: 'flex', alignItems: 'baseline', gap: 4 }}>
                        <span style={{ fontSize: 11, color: '#98A2B3' }}>完整度</span>
                        <span style={{ fontSize: 16, fontWeight: 800, color: complete ? '#1D9E75' : '#E8784A', fontVariantNumeric: 'tabular-nums' }}>
                          {3 - item.missingCount}/3
                        </span>
                      </div>
                      <div style={{ width: 72, height: 5, borderRadius: 999, background: 'rgba(152,162,179,.15)', overflow: 'hidden', marginTop: 4 }}>
                        <div style={{
                          height: '100%', width: `${((3 - item.missingCount) / 3) * 100}%`, borderRadius: 999,
                          background: complete ? 'linear-gradient(90deg,#1D9E75,#27A644)' : 'linear-gradient(90deg,#E8784A,#D9534F)',
                        }} />
                      </div>
                    </div>
                  </div>

                  <div style={{ padding: '0 14px 12px' }}>
                    <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
                      <MissingTag ok={item.hasPractice} label="做题" missingLabel="做题" />
                      <MissingTag ok={item.hasFeedback} label="反馈" missingLabel="反馈" />
                      <MissingTag ok={item.hasSummary} label="小结" missingLabel="小结" />
                    </div>
                  </div>

                  <div style={{
                    display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap',
                    padding: '8px 14px', borderTop: '1px solid #F4EFE8', background: 'rgba(247,245,241,.6)',
                  }}>
                    {!item.hasPractice && (
                      <Link
                        href="/grades/practice"
                        style={{
                          fontSize: 12, fontWeight: 700, color: '#C2413C', textDecoration: 'none',
                          display: 'inline-flex', alignItems: 'center', gap: 4,
                          padding: '5px 9px', borderRadius: 8,
                          border: '1px solid rgba(194,65,60,.3)', background: '#fff',
                        }}
                      >去题库统计</Link>
                    )}
                    <Link
                      href="/gradebook"
                      style={{
                        fontSize: 12, fontWeight: 600, color: '#8A6517', textDecoration: 'none',
                        display: 'inline-flex', alignItems: 'center', gap: 4,
                        padding: '5px 9px', borderRadius: 8,
                        border: '1px solid #E5C37A', background: '#FEF8E8',
                      }}
                    ><TrophyOutlined /> 录测评</Link>
                    <Link
                      href={`/schedule/intensive?studentId=${item.studentId}`}
                      style={{
                        fontSize: 12, fontWeight: 600, color: '#14574D', textDecoration: 'none',
                        display: 'inline-flex', alignItems: 'center', gap: 4,
                        padding: '5px 9px', borderRadius: 8,
                        border: '1px solid rgba(20,87,77,.25)', background: '#E8F2F0',
                      }}
                    ><CalendarOutlined /> 安排排课</Link>
                    <Link
                      href={`/students/${item.studentId}#learning`}
                      style={{
                        fontSize: 12, fontWeight: 700, color: '#0E5E4E', textDecoration: 'none',
                        display: 'inline-flex', alignItems: 'center', gap: 4, flex: 1, justifyContent: 'center', minWidth: 100,
                        padding: '5px 9px', borderRadius: 8,
                        border: '1px solid rgba(14,94,78,.3)', background: '#fff',
                      }}
                    ><FileSearchOutlined /> 查看完整学情</Link>
                  </div>
                </div>
              )
            })}
          </div>
        )}
      </div>
    </PageLayout>
  )
}

'use client'

import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { Button, Space, Tooltip, Typography } from 'antd'
import {
  CalendarOutlined,
  DeleteOutlined,
  EditOutlined,
  EyeOutlined,
  WarningOutlined,
} from '@ant-design/icons'
import { StudentAvatar } from '@/components/Common/StudentAvatar'
import { StatusBadge } from './StatusBadge'
import { MEMBERSHIP_THEME, resolveMembership } from '@/constants/membership'
import {
  hasLowPrepaidHours,
  hasOutstandingPrepaidBalance,
  hasOverdueFees,
} from '@/lib/student-billing-status'
import styles from './StudentCard.module.css'

const { Text } = Typography

const TYPE_CONFIG: Record<string, { bg: string; text: string; label: string }> = {
  ONE_ON_ONE:   { bg: '#EEEDFE', text: '#3C3489', label: '一对一' },
  ONE_ON_TWO:   { bg: '#E6F1FB', text: '#185FA5', label: '一对二' },
  ONE_ON_THREE: { bg: '#FBEAF0', text: '#72243E', label: '一对三' },
  SMALL_GROUP:  { bg: '#FBEAF0', text: '#72243E', label: '一对三' },
  GROUP:        { bg: '#FAEEDA', text: '#633806', label: '精品班课' },
  STUDY_HALL:   { bg: '#FFF0E8', text: '#A63F18', label: '晚托作业班' },
}

function CourseTypeBadge({ type }: { type?: string | null }) {
  const config = TYPE_CONFIG[type || ''] || { bg: '#F4F5F7', text: '#6B7280', label: '未分班' }
  return (
    <span
      style={{
        borderRadius: 6,
        padding: '2px 7px',
        fontSize: 11,
        background: config.bg,
        color: config.text,
        fontWeight: 600,
        lineHeight: 1.4,
      }}
    >
      {config.label}
    </span>
  )
}

type StudentFee = {
  id: string
  status?: string | null
  dueDate?: string | null
  amount?: number | null
}

type StudentEnrollment = {
  id: string
  remainHours?: number | null
  totalHours?: number | null
  usedHours?: number | null
  group?: {
    name?: string | null
    lessonMinutes?: number | null
    intensiveMode?: string | null
    course?: { name?: string | null; type?: string | null } | null
  } | null
}

type StudentCardProps = {
  student: {
    id: string
    name: string
    status: string
    gender?: string | null
    grade?: string | null
    school?: string | null
    enrolledAt: Date | string
    remainHours: number
    totalHours: number
    taughtHours: number
    source?: string | null
    membershipLevel?: string
    courseType?: string | null
    fees?: StudentFee[]
    enrollments?: StudentEnrollment[]
    studyHallMemberships?: Array<{
      id: string
      remainingDays: number | null
      totalDays: number | null
      quotaState: 'UNSET' | 'ACTIVE' | 'LOW' | 'EXPIRED'
      studyClass: { name: string; scheduleType: 'WEEKDAY_LATE' | 'WEEKEND' }
    }>
    mainTeacher?: { id: string; name: string } | null
    schedules?: Array<{ schedule: { course?: { id: string; name: string } | null } }>
  }
  onEdit: (student: Record<string, unknown>) => void
  onDelete: (student: Record<string, unknown>) => void
}

export function StudentCard({ student, onEdit, onDelete }: StudentCardProps) {
  const router = useRouter()
  const isLowHours = student.status === 'ACTIVE' && hasLowPrepaidHours(student.enrollments)
  const isOwed =
    student.status === 'ACTIVE' &&
    (Array.isArray(student.fees)
      ? hasOverdueFees(student.fees)
      : hasOutstandingPrepaidBalance(student.enrollments))

  const membershipLevel = resolveMembership(student.membershipLevel)
  const membershipTheme = MEMBERSHIP_THEME[membershipLevel]
  const isSvipCard = membershipLevel === 'SVIP'
  const isVipCard = membershipLevel === 'VIP'

  // Calculate actual remain hours displayed
  const totalRemain = Number(student.remainHours || 0)
  const totalTaught = Number(student.taughtHours || 0)

  return (
    <article className={styles.card}>
      {/* Top tier subtle indicator */}
      {isSvipCard && <div className={styles.svipStrip} />}
      {isVipCard && !isSvipCard && <div className={styles.vipStrip} />}

      <div>
        {/* Header: Avatar, Name, Tier, School */}
        <div className={styles.headRow}>
          <StudentAvatar gender={student.gender} name={student.name} size={36} rounded />
          <div className={styles.identityCol}>
            <div className={styles.nameRow}>
              <span className={styles.studentName}>{student.name}</span>
              {(isVipCard || isSvipCard) && (
                <span
                  className={styles.membershipTag}
                  style={{
                    background: isSvipCard
                      ? 'linear-gradient(135deg,#C9A45C,#A8873D)'
                      : membershipTheme.bg,
                    color: isSvipCard ? '#fff' : membershipTheme.accent,
                    border: `1px solid ${isSvipCard ? '#D6B56A' : membershipTheme.border}`,
                  }}
                >
                  {isSvipCard ? '★ SVIP' : 'VIP'}
                </span>
              )}
            </div>
            <div className={styles.metaSubtitle}>
              {[student.grade || '未设年级', student.school].filter(Boolean).join(' · ')}
            </div>
          </div>
        </div>

        {/* Badges: Status & Course Type */}
        <div className={styles.badgesRow}>
          <StatusBadge status={student.status} isOwed={isOwed} />
          <CourseTypeBadge type={student.courseType} />
          {isLowHours && (
            <span
              style={{
                fontSize: 10.5,
                fontWeight: 700,
                color: '#E03E2D',
                background: '#FFF0EE',
                border: '1px solid #F1D3CF',
                padding: '1px 6px',
                borderRadius: 999,
                display: 'inline-flex',
                alignItems: 'center',
                gap: 3,
              }}
            >
              <WarningOutlined /> 课时告急
            </span>
          )}
        </div>

        {/* Hours Summary Box */}
        <div className={styles.hoursBar}>
          <div className={styles.remainHoursItem}>
            <span>剩余课时:</span>
            <span
              className={`${styles.remainHoursVal} ${
                isLowHours ? styles.remainHoursDanger : styles.remainHoursNormal
              }`}
            >
              {totalRemain.toFixed(1)} 节
            </span>
          </div>
          <div className={styles.taughtHoursItem}>
            已上 {totalTaught.toFixed(1)}h
          </div>
        </div>

        {/* Study Hall membership if enrolled */}
        {student.studyHallMemberships?.map((membership) => (
          <div key={membership.id} className={styles.studyHallLine}>
            {membership.studyClass.scheduleType === 'WEEKEND' ? '周末作业班' : '晚托班'}：
            {membership.studyClass.name} ·{' '}
            {membership.quotaState === 'UNSET'
              ? '未设天数'
              : membership.quotaState === 'EXPIRED'
              ? '已到期'
              : `余${membership.remainingDays}/${membership.totalDays}天`}
          </div>
        ))}
      </div>

      {/* Action Dock (数据链路连通坞) */}
      <div className={styles.actionDock}>
        <div className={styles.primaryLinks}>
          <Link href={`/students/${student.id}`} className={styles.quickLinkBtn}>
            📋 档案
          </Link>
          <Link
            href={`/schedule/intensive?studentId=${student.id}`}
            className={styles.quickLinkBtn}
            style={{
              background: 'rgba(201, 164, 92, 0.12)',
              borderColor: 'rgba(201, 164, 92, 0.3)',
              color: '#8A6517',
            }}
          >
            📅 排课
          </Link>
        </div>

        <div className={styles.iconActions}>
          <Tooltip title="编辑学员资料">
            <Button
              type="text"
              size="small"
              icon={<EditOutlined style={{ color: 'var(--color-ink-muted)' }} />}
              onClick={() => onEdit(student)}
            />
          </Tooltip>
          <Tooltip title="学员离校处理">
            <Button
              type="text"
              size="small"
              danger
              icon={<DeleteOutlined />}
              onClick={() => onDelete(student)}
            />
          </Tooltip>
        </div>
      </div>
    </article>
  )
}
